fn decode_authority_record<R: CanonicalAuthorityRecord>(
    bytes: &[u8],
    expected: [u8; 32],
) -> Result<R, JournalStoreError> {
    if expected == [0; 32] || bytes.len() > R::MAXIMUM {
        return Err(JournalStoreError::Corrupt);
    }
    let record = R::decode(bytes).map_err(|_| JournalStoreError::Corrupt)?;
    if record.storage_id() != expected || record.encode() != bytes {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(record)
}

fn encode_object<R: CanonicalJournalRecord>(
    record: &R,
) -> Result<EncodedObject, JournalStoreError> {
    record.validate().map_err(supplied_decode_error)?;
    let bytes = record.encode();
    if bytes.len() > class_maximum(R::STORAGE_CLASS) {
        return Err(JournalStoreError::LimitExceeded);
    }
    // Do not trust even an in-memory producer: prove strict round-trip
    // canonicality and rederive its content identity before touching a store.
    let decoded = R::decode(&bytes).map_err(supplied_decode_error)?;
    decoded.validate().map_err(supplied_decode_error)?;
    if decoded.encode() != bytes || decoded.id() != record.id() {
        return Err(JournalStoreError::NonCanonical);
    }
    Ok(EncodedObject {
        class: R::STORAGE_CLASS,
        id: *record.id().as_bytes(),
        bytes,
    })
}

fn decode_object<R: CanonicalJournalRecord>(
    bytes: &[u8],
    expected: R::Id,
) -> Result<R, JournalStoreError> {
    if bytes.len() > class_maximum(R::STORAGE_CLASS) {
        return Err(JournalStoreError::Corrupt);
    }
    let decoded = R::decode(bytes).map_err(|_| JournalStoreError::Corrupt)?;
    decoded.validate().map_err(|_| JournalStoreError::Corrupt)?;
    if decoded.id() != expected || decoded.encode() != bytes {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(decoded)
}

fn ensure_readable_content_class(class: JournalStorageClass) -> Result<(), JournalStoreError> {
    if matches!(
        class,
        JournalStorageClass::Genesis | JournalStorageClass::Heads
    ) {
        Err(JournalStoreError::InvalidClass)
    } else {
        Ok(())
    }
}

fn ensure_writable_content_class(class: JournalStorageClass) -> Result<(), JournalStoreError> {
    if class == JournalStorageClass::InvocationHistoryNode {
        Err(JournalStoreError::InvalidClass)
    } else {
        ensure_readable_content_class(class)
    }
}

fn ensure_publication_class(class: JournalStorageClass) -> Result<(), JournalStoreError> {
    if matches!(
        class,
        JournalStorageClass::OrderedEntry
            | JournalStorageClass::LocalEntry
            | JournalStorageClass::MergeEvent
            | JournalStorageClass::Checkpoint
    ) {
        Ok(())
    } else {
        Err(JournalStoreError::InvalidClass)
    }
}

fn decode_anchor<T: CanonicalJournalRecord, R: CanonicalJournalRecord>(
    anchor: &R,
) -> Result<T, JournalStoreError> {
    T::decode(&anchor.encode()).map_err(|_| JournalStoreError::NonCanonical)
}

fn ordered_base(heads: &JournalHeads) -> OrderedBase {
    OrderedBase {
        index: heads.ordered_index,
        head: heads.ordered_head,
    }
}

fn validate_publication_shape<R: CanonicalJournalRecord>(
    current: &JournalHeads,
    anchor: &R,
    next: &JournalHeads,
) -> Result<(), JournalStoreError> {
    validate_publication_shape_with_mode(
        current,
        anchor,
        next,
        ReplayPublicationMode::Canonical,
        false,
    )
}

fn validate_publication_shape_with_mode<R: CanonicalJournalRecord>(
    current: &JournalHeads,
    anchor: &R,
    next: &JournalHeads,
    mode: ReplayPublicationMode,
    transition_proof_change: bool,
) -> Result<(), JournalStoreError> {
    match R::STORAGE_CLASS {
        JournalStorageClass::OrderedEntry => {
            let entry = decode_anchor::<OrderedEntry, _>(anchor)?;
            let entry_base = OrderedBase {
                index: entry.index,
                head: Some(entry.id()),
            };
            let (expected_frontier, expected_merge_invocations, expected_fence, expected_seal) =
                match mode {
                    ReplayPublicationMode::Canonical => {
                        let (fence, seal) = if entry.merge_seal.is_some() {
                            (entry_base, entry.merge_seal)
                        } else {
                            (current.merge_fence, current.merge_seal)
                        };
                        (
                            current.merge_frontier,
                            entry
                                .merge_seal
                                .is_none()
                                .then_some(current.merge_invocations),
                            fence,
                            seal,
                        )
                    }
                    ReplayPublicationMode::SharedOrderedPreserveMerge => {
                        if entry.merge_seal.is_some() {
                            return Err(JournalStoreError::NonCanonical);
                        }
                        (
                            current.merge_frontier,
                            Some(current.merge_invocations),
                            current.merge_fence,
                            current.merge_seal,
                        )
                    }
                    ReplayPublicationMode::SharedOrderedInstallFence => {
                        if entry.merge_seal.is_none() {
                            return Err(JournalStoreError::NonCanonical);
                        }
                        (entry.merge_frontier, None, entry_base, entry.merge_seal)
                    }
                };
            let canonical_frontier = match mode {
                ReplayPublicationMode::Canonical => entry.merge_frontier == current.merge_frontier,
                ReplayPublicationMode::SharedOrderedPreserveMerge
                | ReplayPublicationMode::SharedOrderedInstallFence => true,
            };
            if entry.genesis != current.genesis
                || entry.input.runtime != current.runtime
                || entry.parent != current.ordered_head
                || entry.index
                    != current
                        .ordered_index
                        .checked_add(1)
                        .ok_or(JournalStoreError::LimitExceeded)?
                || !canonical_frontier
                || next.ordered_head != Some(entry.id())
                || next.ordered_index != entry.index
                || next.merge_frontier != expected_frontier
                || next.merge_fence != expected_fence
                || next.merge_seal != expected_seal
                || expected_merge_invocations
                    .is_some_and(|expected| next.merge_invocations != expected)
                || next.local_invocations != current.local_invocations
                || next.local_head != current.local_head
                || next.local_revision != current.local_revision
                || (!transition_proof_change && next.transition_proofs != current.transition_proofs)
                || next.checkpoint != current.checkpoint
            {
                return Err(JournalStoreError::NonCanonical);
            }
        }
        JournalStorageClass::LocalEntry => {
            if mode != ReplayPublicationMode::Canonical {
                return Err(JournalStoreError::NonCanonical);
            }
            let entry = decode_anchor::<LocalEntry, _>(anchor)?;
            if entry.genesis != current.genesis
                || entry.input.runtime != current.runtime
                || entry.node != current.node
                || entry.parent != current.local_head
                || entry.revision
                    != current
                        .local_revision
                        .checked_add(1)
                        .ok_or(JournalStoreError::LimitExceeded)?
                || entry.ordered_base != ordered_base(current)
                || entry.merge_frontier != current.merge_frontier
                || next.local_head != Some(entry.id())
                || next.local_revision != entry.revision
                || next.ordered_head != current.ordered_head
                || next.ordered_index != current.ordered_index
                || next.merge_frontier != current.merge_frontier
                || next.merge_fence != current.merge_fence
                || next.merge_seal != current.merge_seal
                || next.runtime != current.runtime
                || next.ordered_invocations != current.ordered_invocations
                || next.merge_invocations != current.merge_invocations
                || (!transition_proof_change && next.transition_proofs != current.transition_proofs)
                || next.checkpoint != current.checkpoint
            {
                return Err(JournalStoreError::NonCanonical);
            }
        }
        JournalStorageClass::MergeEvent => {
            if mode != ReplayPublicationMode::Canonical {
                return Err(JournalStoreError::NonCanonical);
            }
            let event = decode_anchor::<MergeEvent, _>(anchor)?;
            if event.genesis != current.genesis
                || event.input.runtime != current.runtime
                || next.ordered_head != current.ordered_head
                || next.ordered_index != current.ordered_index
                || next.merge_frontier == current.merge_frontier
                || next.merge_fence != current.merge_fence
                || next.merge_seal != current.merge_seal
                || next.runtime != current.runtime
                || next.ordered_invocations != current.ordered_invocations
                || next.local_invocations != current.local_invocations
                || next.local_head != current.local_head
                || next.local_revision != current.local_revision
                || (!transition_proof_change && next.transition_proofs != current.transition_proofs)
                || next.checkpoint != current.checkpoint
            {
                return Err(JournalStoreError::NonCanonical);
            }
        }
        JournalStorageClass::Checkpoint => {
            if mode != ReplayPublicationMode::Canonical {
                return Err(JournalStoreError::NonCanonical);
            }
            let checkpoint = decode_anchor::<CheckpointManifest, _>(anchor)?;
            if checkpoint.genesis != current.genesis
                || checkpoint.runtime != current.runtime
                || checkpoint.publication_revision != current.publication_revision
                || checkpoint.ordered_head != current.ordered_head
                || checkpoint.ordered_index != current.ordered_index
                || checkpoint.merge_frontier != current.merge_frontier
                || checkpoint.merge_fence != current.merge_fence
                || checkpoint.merge_seal != current.merge_seal
                || checkpoint.ordered_invocations != current.ordered_invocations
                || checkpoint.merge_invocations != current.merge_invocations
                || checkpoint.transition_proofs != next.transition_proofs
                || next.checkpoint != Some(checkpoint.id())
                || next.ordered_head != current.ordered_head
                || next.ordered_index != current.ordered_index
                || next.merge_frontier != current.merge_frontier
                || next.merge_fence != current.merge_fence
                || next.merge_seal != current.merge_seal
                || next.runtime != current.runtime
                || next.ordered_invocations != current.ordered_invocations
                || next.merge_invocations != current.merge_invocations
                || next.local_invocations != current.local_invocations
                || next.local_head != current.local_head
                || next.local_revision != current.local_revision
                || (!transition_proof_change && next.transition_proofs != current.transition_proofs)
            {
                return Err(JournalStoreError::NonCanonical);
            }
        }
        _ => return Err(JournalStoreError::InvalidClass),
    }
    Ok(())
}

fn validate_blob_reference(
    class: JournalBlobClass,
    reference: &BlobRef,
) -> Result<(), JournalStoreError> {
    if reference.hash == Hash::ZERO || reference.len > blob_maximum(class) as u64 {
        return Err(JournalStoreError::LimitExceeded);
    }
    Ok(())
}

fn validate_supplied_blob(
    class: JournalBlobClass,
    reference: &BlobRef,
    bytes: &[u8],
) -> Result<(), JournalStoreError> {
    validate_blob_reference(class, reference)?;
    if reference.len != bytes.len() as u64 || !reference.matches(bytes) {
        return Err(JournalStoreError::NonCanonical);
    }
    Ok(())
}

fn validate_stored_blob(
    class: JournalBlobClass,
    reference: &BlobRef,
    bytes: &[u8],
) -> Result<(), JournalStoreError> {
    if reference.len > blob_maximum(class) as u64
        || reference.len != bytes.len() as u64
        || !reference.matches(bytes)
    {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(())
}

fn genesis_state_component(state: &RuntimeState, lane: PersistedLane) -> &[u8] {
    match lane {
        PersistedLane::Control => &state.control,
        PersistedLane::Linear => &state.linear,
        PersistedLane::Merge => &state.merge,
        PersistedLane::Local => &state.local,
    }
}

/// Phase-one authority dispatch. Root bootstrap is fully reverified here;
/// ordinary `SystemAuthorized` records remain fail-closed until the live
/// system Agent can mint the opaque post-finalization capability required by
/// the ordinary-genesis verifier. A valid unsupported variant is therefore
/// unavailable, not corrupt authority data.
fn phase_one_root_admission(
    admission: &AgentGenesisAdmissionRecord,
) -> Result<&SystemAgentGenesisAdmissionRecord, JournalStoreError> {
    match admission {
        AgentGenesisAdmissionRecord::RootBootstrap(admission) => Ok(admission),
        AgentGenesisAdmissionRecord::SystemAuthorized { .. } => Err(JournalStoreError::Unavailable),
    }
}

struct SealedGenesisShape {
    initial: JournalHeads,
    local_invocations: InvocationIndexManifest,
    lanes: [LaneStateManifest; 4],
}

fn validate_authority_links(
    genesis: &AgentJournalGenesis,
    root: &RootAnchorRecord,
    evidence: &SystemAgentGenesisEvidence,
    admission: &AgentGenesisAdmissionRecord,
) -> Result<(), JournalStoreError> {
    let root_admission = phase_one_root_admission(admission)?;
    let root_id = root.id();
    let evidence_id = evidence.id();
    let admission_id = admission.id();
    decode_authority_record::<RootAnchorRecord>(&root.encode(), *root_id.as_bytes())?;
    decode_authority_record::<SystemAgentGenesisEvidence>(
        &evidence.encode(),
        *evidence_id.as_bytes(),
    )?;
    decode_authority_record::<AgentGenesisAdmissionRecord>(
        &admission.encode(),
        *admission_id.as_bytes(),
    )?;

    let claim = evidence.claim();
    if admission_id != genesis.admission
        || root_admission.root_anchor() != root_id
        || root_admission.root_anchor_config_version() != root.config_version()
        || root_admission.root_anchor_config() != root.config_commitment()
        || root_admission.evidence() != evidence_id
        || root_admission.claim() != claim.authority_claim()
        || claim.root_anchor() != root_id
        || claim.root_anchor_config_version() != root.config_version()
        || claim.root_anchor_config() != root.config_commitment()
        || claim.space() != root.space()
        || claim.system_agent() != root.system_agent()
        || claim.authority_binding() != root.authority_binding()
        || claim.root_certification() != root.root_certification()
        || claim.space() != genesis.runtime().space
        || claim.system_agent() != genesis.runtime().agent
        || claim.genesis_intent()
            != genesis
                .genesis_intent()
                .map_err(|_| JournalStoreError::Corrupt)?
        || claim.runtime_binding() != genesis.runtime().commitment()
        || claim.sequence()
            != genesis
                .genesis_authority_sequence()
                .map_err(|_| JournalStoreError::Corrupt)?
        || evidence
            .certificate()
            .verify(root.initial_committee(), claim.authority_claim())
            .is_err()
    {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(())
}

fn validate_sealed_authority_shape(sealed: &ReplaySealedGenesis) -> Result<(), JournalStoreError> {
    let genesis = sealed.genesis();
    let root = sealed.root_anchor();
    let evidence = sealed.admission_evidence();
    let admission = sealed.admission_record();
    validate_authority_links(genesis, root, evidence, admission)
        .map_err(|_| JournalStoreError::NonCanonical)?;
    let claim = evidence.claim();
    if sealed.admission_commitment() != genesis.admission.as_hash()
        || claim.post_create_state()
            != system_genesis_post_create_state_commitment(sealed.post_create())
                .map_err(|_| JournalStoreError::NonCanonical)?
        || claim.artifact_closure()
            != sealed
                .artifacts()
                .system_genesis_commitment()
                .map_err(|_| JournalStoreError::NonCanonical)?
    {
        return Err(JournalStoreError::NonCanonical);
    }
    Ok(())
}

/// Defensively prove that every storage-visible member of the opaque
/// admission token is the exact clean-generation closure. The token remains
/// the semantic authority: this check deliberately does not re-execute the
/// admitted Create operation or invent a second trust decision in storage.
fn validate_sealed_genesis_shape(
    sealed: &ReplaySealedGenesis,
    agent: AgentId,
    node: NodeId,
) -> Result<SealedGenesisShape, JournalStoreError> {
    validate_sealed_authority_shape(sealed)?;
    let genesis = sealed.genesis();
    encode_object(genesis)?;
    if genesis.runtime().agent != agent || sealed.admission_commitment() == Hash::ZERO {
        return Err(JournalStoreError::ScopeMismatch);
    }

    let post_create = sealed.post_create();
    if post_create
        .encoded_len()
        .is_none_or(|len| len > MAX_RUNTIME_STATE_BYTES)
    {
        return Err(JournalStoreError::LimitExceeded);
    }
    let ReplayOperation::CleanManage {
        request: crate::agent_sdk::ManagementRequest::Create(descriptor),
        ..
    } = &genesis.create.operation
    else {
        return Err(JournalStoreError::NonCanonical);
    };
    if post_create.is_empty()
        || descriptor.identity.agent.0 != agent.0
        || sealed.replica().node != node
        || !super::bootstrap::descriptor_matches_root_replica(descriptor, sealed.replica())
    {
        return Err(JournalStoreError::ScopeMismatch);
    }

    let expected_frontier = MergeFrontier {
        genesis: genesis.id(),
        events: Vec::new(),
    };
    if sealed.empty_frontier() != &expected_frontier {
        return Err(JournalStoreError::NonCanonical);
    }
    encode_object(sealed.empty_frontier())?;

    let expected_ordered =
        InvocationIndexManifest::empty(genesis.id(), InvocationOwnershipScope::Ordered);
    let expected_merge =
        InvocationIndexManifest::empty(genesis.id(), InvocationOwnershipScope::Merge);
    let local_invocations = *sealed.local_invocations();
    if sealed.ordered_invocations() != &expected_ordered
        || sealed.merge_invocations() != &expected_merge
        || local_invocations
            != InvocationIndexManifest::empty(genesis.id(), InvocationOwnershipScope::Local(node))
    {
        return Err(JournalStoreError::NonCanonical);
    }
    encode_object(sealed.ordered_invocations())?;
    encode_object(sealed.merge_invocations())?;
    encode_object(&local_invocations)?;

    let artifacts = sealed.artifacts();
    encode_object(artifacts)?;
    if artifacts.genesis != genesis.id()
        || !artifacts
            .artifacts
            .iter()
            .any(|artifact| artifact == &genesis.runtime().package)
    {
        return Err(JournalStoreError::NonCanonical);
    }

    let lanes = [
        sealed.lane_manifest(PersistedLane::Control),
        sealed.lane_manifest(PersistedLane::Linear),
        sealed.lane_manifest(PersistedLane::Merge),
        sealed.lane_manifest(PersistedLane::Local),
    ];
    for lane in &lanes {
        encode_object(lane)?;
        let bytes = genesis_state_component(post_create, lane.lane);
        if lane.genesis != genesis.id()
            || lane.runtime != *genesis.runtime()
            || lane.state != BlobRef::of_bytes(bytes)
        {
            return Err(JournalStoreError::NonCanonical);
        }
    }

    let initial = sealed.initial_heads();
    encode_object(&initial)?;
    if initial
        != JournalHeads::initial(
            genesis.id(),
            genesis.admission,
            node,
            sealed.empty_frontier().id(),
            genesis.runtime().clone(),
        )
        || initial.ordered_invocations != sealed.ordered_invocations().id()
        || initial.merge_invocations != sealed.merge_invocations().id()
        || initial.local_invocations != local_invocations.id()
    {
        return Err(JournalStoreError::NonCanonical);
    }

    Ok(SealedGenesisShape {
        initial,
        local_invocations,
        lanes,
    })
}

/// Validate the storage-visible closure of an opaque ordinary-Agent genesis
/// seal. Local receipt admission and Shared system-finality admission remain
/// distinct opaque constructors; this helper only shares their physical
/// crash protocol after that trust boundary has been crossed.
fn validate_sealed_ordinary_genesis_shape<T: ReplaySealedOrdinaryGenesis>(
    sealed: &T,
    agent: AgentId,
    node: NodeId,
) -> Result<SealedGenesisShape, JournalStoreError> {
    sealed
        .validate_seal()
        .map_err(|_| JournalStoreError::NonCanonical)?;
    let genesis = sealed.genesis();
    encode_object(genesis)?;
    if genesis.runtime().agent != agent
        || sealed.replica().node != node
        || sealed.admission_commitment() == Hash::ZERO
    {
        return Err(JournalStoreError::ScopeMismatch);
    }

    let post_create = sealed.post_create();
    if post_create
        .encoded_len()
        .is_none_or(|len| len > MAX_RUNTIME_STATE_BYTES)
    {
        return Err(JournalStoreError::LimitExceeded);
    }
    if !sealed.validates_post_create_state() {
        return Err(JournalStoreError::ScopeMismatch);
    }
    if let Some(admission) = sealed.admission_record()
        && (admission.id() != genesis.admission || admission.validate().is_err())
    {
        return Err(JournalStoreError::NonCanonical);
    }

    let expected_frontier = MergeFrontier {
        genesis: genesis.id(),
        events: Vec::new(),
    };
    if sealed.empty_frontier() != &expected_frontier {
        return Err(JournalStoreError::NonCanonical);
    }
    encode_object(sealed.empty_frontier())?;

    let expected_ordered =
        InvocationIndexManifest::empty(genesis.id(), InvocationOwnershipScope::Ordered);
    let expected_merge =
        InvocationIndexManifest::empty(genesis.id(), InvocationOwnershipScope::Merge);
    let local_invocations = *sealed.local_invocations();
    if sealed.ordered_invocations() != &expected_ordered
        || sealed.merge_invocations() != &expected_merge
        || local_invocations
            != InvocationIndexManifest::empty(genesis.id(), InvocationOwnershipScope::Local(node))
    {
        return Err(JournalStoreError::NonCanonical);
    }
    encode_object(sealed.ordered_invocations())?;
    encode_object(sealed.merge_invocations())?;
    encode_object(&local_invocations)?;

    let artifacts = sealed.artifacts();
    encode_object(artifacts)?;
    if artifacts.genesis != genesis.id()
        || !artifacts
            .artifacts
            .iter()
            .any(|artifact| artifact == &genesis.runtime().package)
    {
        return Err(JournalStoreError::NonCanonical);
    }

    let lanes = [
        sealed.lane_manifest(PersistedLane::Control),
        sealed.lane_manifest(PersistedLane::Linear),
        sealed.lane_manifest(PersistedLane::Merge),
        sealed.lane_manifest(PersistedLane::Local),
    ];
    for lane in &lanes {
        encode_object(lane)?;
        let bytes = genesis_state_component(post_create, lane.lane);
        if lane.genesis != genesis.id()
            || lane.runtime != *genesis.runtime()
            || lane.state != BlobRef::of_bytes(bytes)
        {
            return Err(JournalStoreError::NonCanonical);
        }
    }

    let initial = sealed.initial_heads();
    encode_object(&initial)?;
    let mut expected_initial = JournalHeads::initial(
        genesis.id(),
        genesis.admission,
        node,
        sealed.empty_frontier().id(),
        genesis.runtime().clone(),
    );
    if let Some(checkpoint) = sealed.genesis_checkpoint() {
        let expected_checkpoint = super::replay::derive_checkpoint::<
            core::convert::Infallible,
            core::convert::Infallible,
        >(
            genesis.id(),
            genesis.admission,
            genesis.runtime().clone(),
            0,
            OrderedBase::post_genesis(),
            expected_initial.merge_frontier,
            expected_initial.merge_fence,
            None,
            expected_initial.ordered_invocations,
            expected_initial.merge_invocations,
            expected_initial.transition_proofs,
            lanes
                .iter()
                .map(|lane| super::journal::CheckpointLane {
                    lane: lane.lane,
                    node: (lane.lane == PersistedLane::Local).then_some(node),
                    state: lane.id(),
                    invocations: (lane.lane == PersistedLane::Local)
                        .then_some(local_invocations.id()),
                })
                .collect(),
            artifacts.id(),
            super::replay::clean_create_management_evidence(&genesis.create),
        )
        .map_err(|_| JournalStoreError::NonCanonical)?;
        if checkpoint != expected_checkpoint {
            return Err(JournalStoreError::NonCanonical);
        }
        expected_initial.previous = Some(expected_initial.id());
        expected_initial.publication_revision = 1;
        expected_initial.checkpoint = Some(checkpoint.id());
    }
    if initial != expected_initial
        || initial.ordered_invocations != sealed.ordered_invocations().id()
        || initial.merge_invocations != sealed.merge_invocations().id()
        || initial.local_invocations != local_invocations.id()
    {
        return Err(JournalStoreError::NonCanonical);
    }

    Ok(SealedGenesisShape {
        initial,
        local_invocations,
        lanes,
    })
}

fn require_record<S, R>(store: &S, id: R::Id) -> Result<R, JournalStoreError>
where
    S: AgentJournalStore,
    R: CanonicalJournalRecord,
{
    store.get::<R>(id)?.ok_or(JournalStoreError::MissingObject)
}

/// Persist and exact-read back the canonical empty proof index before an
/// initial head can make its root authoritative. This is intentionally part
/// of both in-memory and file-backed initialization rather than a lazy repair
/// on open: a visible head with a missing index is corrupt.
fn persist_initial_transition_proof_index<S: AgentJournalStore>(
    store: &mut S,
    initial: &JournalHeads,
) -> Result<bool, JournalStoreError> {
    let expected = TransitionProofIndexManifest::empty(initial.genesis);
    if expected.id() != initial.transition_proofs {
        return Err(JournalStoreError::NonCanonical);
    }
    let created = store.put(&expected)?;
    let retained = store
        .get::<TransitionProofIndexManifest>(initial.transition_proofs)?
        .ok_or(JournalStoreError::MissingObject)?;
    if retained != expected || retained.id() != initial.transition_proofs {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(created)
}

fn require_blob<S: AgentJournalStore>(
    store: &S,
    class: JournalBlobClass,
    reference: &BlobRef,
) -> Result<(), JournalStoreError> {
    if store.load_blob(class, reference)?.is_none() {
        return Err(JournalStoreError::MissingObject);
    }
    Ok(())
}

fn validate_lane_state<S: AgentJournalStore>(
    store: &S,
    id: super::journal::LaneStateId,
) -> Result<LaneStateManifest, JournalStoreError> {
    let manifest = validate_lane_state_record(store, id)?;
    // Do not substitute a whole-tree audit on the publication fast path.
    // External roots need incremental replay-sealed availability before they
    // can be admitted here. GC's explicit maintenance traversal is separate.
    #[cfg(feature = "experimental-state-blocks")]
    if manifest.external_root.is_some() {
        return Err(JournalStoreError::Unavailable);
    }
    Ok(manifest)
}

fn validate_lane_state_record<S: AgentJournalStore>(
    store: &S,
    id: super::journal::LaneStateId,
) -> Result<LaneStateManifest, JournalStoreError> {
    let manifest = require_record::<S, LaneStateManifest>(store, id)?;
    require_blob(store, JournalBlobClass::LaneState, &manifest.state)?;
    Ok(manifest)
}

fn validate_artifact_closure<S: AgentJournalStore>(
    store: &S,
    id: super::journal::ArtifactClosureId,
    genesis: super::journal::AgentJournalGenesisId,
) -> Result<(), JournalStoreError> {
    let closure = require_record::<S, ArtifactClosure>(store, id)?;
    let referenced_bytes = closure
        .artifacts
        .iter()
        .try_fold(0_u64, |bytes, artifact| bytes.checked_add(artifact.len))
        .ok_or(JournalStoreError::LimitExceeded)?;
    if closure.genesis != genesis
        || closure.artifacts.len() > MAX_ARTIFACT_CLOSURE_ENTRIES
        || referenced_bytes > MAX_ARTIFACT_CLOSURE_REFERENCED_BYTES
    {
        return Err(JournalStoreError::Corrupt);
    }
    for reference in &closure.artifacts {
        require_blob(store, JournalBlobClass::CatalogArtifact, reference)?;
    }
    Ok(())
}

fn service_proof_blob(reference: &crate::agent_sdk::BlobRef) -> BlobRef {
    BlobRef {
        hash: Hash(reference.hash.0),
        len: reference.len,
    }
}

fn transition_proof_anchor_for_position(
    position: ReplayPosition,
) -> Result<TransitionProofAnchor, JournalStoreError> {
    match position {
        ReplayPosition::Genesis => Err(JournalStoreError::NonCanonical),
        ReplayPosition::Ordered {
            id,
            index,
            merge_frontier,
            merge_seal,
        } => Ok(TransitionProofAnchor::Ordered {
            entry: id,
            index,
            merge_frontier,
            merge_seal,
        }),
        ReplayPosition::Merge {
            id,
            causal_height,
            ordered_base,
        } => Ok(TransitionProofAnchor::Merge {
            event: id,
            causal_height,
            ordered_base,
        }),
        ReplayPosition::Local {
            id,
            node,
            revision,
            ordered_base,
            merge_frontier,
        } => Ok(TransitionProofAnchor::Local {
            entry: id,
            node,
            revision,
            ordered_base,
            merge_frontier,
        }),
    }
}

fn transition_proof_input_at_position<S: AgentJournalStore>(
    store: &S,
    publication: &ReplaySealedPublication,
    position: ReplayPosition,
) -> Result<ReplayInput, JournalStoreError> {
    let staged_anchor_input = match (publication.anchor(), position) {
        (
            ReplayPublicationAnchor::Ordered(entry),
            ReplayPosition::Ordered {
                id,
                index,
                merge_frontier,
                merge_seal,
            },
        ) if entry.id() == id
            && entry.index == index
            && entry.merge_frontier == merge_frontier
            && entry.merge_seal == merge_seal =>
        {
            Some(entry.input.clone())
        }
        (
            ReplayPublicationAnchor::Local(entry),
            ReplayPosition::Local {
                id,
                node,
                revision,
                ordered_base,
                merge_frontier,
            },
        ) if entry.id() == id
            && entry.node == node
            && entry.revision == revision
            && entry.ordered_base == ordered_base
            && entry.merge_frontier == merge_frontier =>
        {
            Some(entry.input.clone())
        }
        (
            ReplayPublicationAnchor::Merge { event, .. },
            ReplayPosition::Merge {
                id,
                causal_height,
                ordered_base,
            },
        ) if event.id() == id
            && event.causal_height == causal_height
            && event.ordered_base == ordered_base =>
        {
            Some(event.input.clone())
        }
        _ => None,
    };
    if let Some(input) = staged_anchor_input {
        return Ok(input);
    }
    match position {
        ReplayPosition::Genesis => Err(JournalStoreError::NonCanonical),
        ReplayPosition::Ordered {
            id,
            index,
            merge_frontier,
            merge_seal,
        } => {
            let entry = require_record::<S, OrderedEntry>(store, id)?;
            (entry.id() == id
                && entry.index == index
                && entry.merge_frontier == merge_frontier
                && entry.merge_seal == merge_seal)
                .then_some(entry.input)
                .ok_or(JournalStoreError::Corrupt)
        }
        ReplayPosition::Merge {
            id,
            causal_height,
            ordered_base,
        } => {
            let event = require_record::<S, MergeEvent>(store, id)?;
            (event.id() == id
                && event.causal_height == causal_height
                && event.ordered_base == ordered_base)
                .then_some(event.input)
                .ok_or(JournalStoreError::Corrupt)
        }
        ReplayPosition::Local {
            id,
            node,
            revision,
            ordered_base,
            merge_frontier,
        } => {
            let entry = require_record::<S, LocalEntry>(store, id)?;
            (entry.id() == id
                && entry.node == node
                && entry.revision == revision
                && entry.ordered_base == ordered_base
                && entry.merge_frontier == merge_frontier)
                .then_some(entry.input)
                .ok_or(JournalStoreError::Corrupt)
        }
    }
}

fn validate_transition_proof_requirement<S: AgentJournalStore>(
    store: &S,
    publication: &ReplaySealedPublication,
    requirement: &super::replay::ReplayTransitionProofRequirement,
    entry: TransitionProofIndexEntry,
    proof: &JournalTransitionProof,
    prepared: bool,
) -> Result<(), JournalStoreError> {
    let binding = requirement.binding();
    let expected_anchor = transition_proof_anchor_for_position(requirement.position())?;
    let input = transition_proof_input_at_position(store, publication, requirement.position())?;
    let statement = &proof.proof_record().statement;
    if input.id() != requirement.input()
        || proof.input() != requirement.input()
        || proof.anchor() != expected_anchor
        || prepared && proof.predecessor() != publication.expected()
        || entry.key != binding.key()
        || statement.key() != binding.key()
        || statement.work != binding.work()
        || statement.transition != binding.transition()
        || statement.before != binding.before()
        || statement.after != binding.after()
        || proof.publication().as_bytes() != binding.publication().as_bytes()
        || TransitionProofIndexEntry::for_record(proof).map_err(|_| JournalStoreError::Corrupt)?
            != entry
        || !transition_proof_lifecycle_matches_input(requirement.lifecycle(), &input)
    {
        return Err(JournalStoreError::NonCanonical);
    }
    Ok(())
}

fn validate_transition_proof_retirement<S: AgentJournalStore>(
    store: &S,
    publication: &ReplaySealedPublication,
    predecessor: &JournalHeads,
    retirement: super::replay::ReplayTransitionProofRetirement,
) -> Result<(), JournalStoreError> {
    if matches!(publication.anchor(), ReplayPublicationAnchor::Merge { .. }) {
        // Merge results are provisional. Only an Ordered fence may carry
        // retirement authority for a canonical Merge acknowledgement.
        return Err(JournalStoreError::NonCanonical);
    }
    let input = transition_proof_input_at_position(store, publication, retirement.position())?;
    let ReplayOperation::CleanAcknowledge {
        context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
        expected_live: Some(expected_live),
        work,
        ..
    } = &input.operation
    else {
        return Err(JournalStoreError::NonCanonical);
    };
    if input.id() != retirement.input()
        || *expected_live != retirement.key()
        || expected_live.invocation != work.invocation
    {
        return Err(JournalStoreError::NonCanonical);
    }
    match (publication.anchor(), retirement.position()) {
        (ReplayPublicationAnchor::Ordered(anchor), ReplayPosition::Ordered { id, .. })
            if anchor.id() == id && anchor.input.id() == retirement.input() =>
        {
            Ok(())
        }
        (ReplayPublicationAnchor::Local(anchor), ReplayPosition::Local { id, .. })
            if anchor.id() == id && anchor.input.id() == retirement.input() =>
        {
            Ok(())
        }
        (ReplayPublicationAnchor::Ordered(anchor), ReplayPosition::Merge { id, .. })
            if anchor.merge_seal.is_some() =>
        {
            if predecessor.id() != publication.expected() {
                return Err(JournalStoreError::Conflict);
            }
            let frontier = require_record::<S, MergeFrontier>(store, anchor.merge_frontier)?;
            let boundary = retained_merge_boundary(store, predecessor)?;
            let dag = validate_frontier(store, &frontier, &boundary.tips)?;
            dag.contains_at_or_below(&frontier.events, id)?
                .then_some(())
                .ok_or(JournalStoreError::NonCanonical)
        }
        _ => Err(JournalStoreError::NonCanonical),
    }
}

fn transition_proof_lifecycle_matches_input(
    lifecycle: super::replay::ReplayTransitionProofLifecycle,
    input: &ReplayInput,
) -> bool {
    match (lifecycle, &input.operation) {
        (
            super::replay::ReplayTransitionProofLifecycle::Invoke,
            ReplayOperation::CleanInvoke {
                context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
                ..
            },
        ) => true,
        (
            super::replay::ReplayTransitionProofLifecycle::Resume(expected),
            ReplayOperation::CleanResume {
                context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
                expected_live: Some(encoded),
                work,
                ..
            },
        ) => *encoded == expected && expected.invocation == work.invocation,
        (
            super::replay::ReplayTransitionProofLifecycle::Acknowledge(expected),
            ReplayOperation::CleanAcknowledge {
                context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
                expected_live: Some(encoded),
                work,
                ..
            },
        ) => *encoded == expected && expected.invocation == work.invocation,
        _ => false,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StoredTransitionProofRequirementContext {
    Lifecycle,
    Recanonicalize,
    Preserve,
}

#[derive(Clone, Debug)]
struct StoredTransitionProofLifecycleInput {
    input: ReplayInput,
    position: ReplayPosition,
    lifecycle: ReplayTransitionProofLifecycle,
    requirement_context: StoredTransitionProofRequirementContext,
    final_acknowledgement: bool,
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct StoredTransitionProofShadow {
    retired_root: Option<InvocationHistoryNodeId>,
    live: BTreeMap<
        crate::agent_sdk::InvocationId,
        Option<crate::agent_sdk::proof::TransitionProofKey>,
    >,
}

impl StoredTransitionProofShadow {
    fn from_manifest(manifest: &TransitionProofIndexManifest) -> Self {
        Self {
            retired_root: manifest.retired_root(),
            live: manifest
                .live_entries()
                .iter()
                .map(|key| (key.invocation, Some(*key)))
                .collect(),
        }
    }

    fn from_replay_boundary(publication: &ReplaySealedPublication) -> Self {
        Self {
            retired_root: publication.transition_proof_boundary().retired_root(),
            live: publication
                .transition_proof_boundary()
                .live_entries()
                .map(|key| (key.invocation, Some(key)))
                .collect(),
        }
    }

    fn matches_manifest(&self, manifest: &TransitionProofIndexManifest) -> bool {
        self.retired_root == manifest.retired_root()
            && self.live.values().filter(|key| key.is_some()).count()
                == manifest.live_entries().len()
            && manifest
                .live_entries()
                .iter()
                .all(|key| self.live(key.invocation) == Some(*key))
    }

    fn seed_terminal<S: InvocationHistoryStore<Error = JournalStoreError>>(
        &mut self,
        store: &S,
        genesis: AgentJournalGenesisId,
        invocation: crate::agent_sdk::InvocationId,
    ) -> Result<(), JournalStoreError> {
        if transition_proof_retirement_for_invocation(
            store,
            genesis,
            self.retired_root,
            invocation,
        )?
        .is_some()
        {
            if self.live(invocation).is_some() {
                return Err(JournalStoreError::Corrupt);
            }
            self.live.insert(invocation, None);
        }
        Ok(())
    }

    fn live(
        &self,
        invocation: crate::agent_sdk::InvocationId,
    ) -> Option<crate::agent_sdk::proof::TransitionProofKey> {
        self.live.get(&invocation).copied().flatten()
    }

    fn has_tombstone(&self, invocation: crate::agent_sdk::InvocationId) -> bool {
        self.live.get(&invocation) == Some(&None)
    }

    fn install(&mut self, key: crate::agent_sdk::proof::TransitionProofKey) {
        self.live.insert(key.invocation, Some(key));
    }

    fn retire(&mut self, key: crate::agent_sdk::proof::TransitionProofKey) -> bool {
        if self.live(key.invocation) != Some(key) {
            return false;
        }
        self.live.insert(key.invocation, None);
        true
    }

    fn overlay(
        &mut self,
        external: &BTreeMap<
            crate::agent_sdk::InvocationId,
            Option<crate::agent_sdk::proof::TransitionProofKey>,
        >,
    ) {
        for (invocation, key) in external {
            match key {
                Some(key) => {
                    self.live.insert(*invocation, Some(*key));
                }
                None => {
                    self.live.insert(*invocation, None);
                }
            }
        }
    }
}

fn transition_proof_lifecycle(
    input: &ReplayInput,
) -> Option<(
    crate::agent_sdk::InvocationId,
    ReplayTransitionProofLifecycle,
)> {
    match &input.operation {
        ReplayOperation::CleanInvoke {
            context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
            work,
            ..
        } => Some((work.invocation, ReplayTransitionProofLifecycle::Invoke)),
        ReplayOperation::CleanResume {
            context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
            expected_live: Some(expected),
            work,
            ..
        } if expected.invocation == work.invocation => Some((
            work.invocation,
            ReplayTransitionProofLifecycle::Resume(*expected),
        )),
        ReplayOperation::CleanAcknowledge {
            context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
            expected_live: Some(expected),
            work,
            ..
        } if expected.invocation == work.invocation => Some((
            work.invocation,
            ReplayTransitionProofLifecycle::Acknowledge(*expected),
        )),
        _ => None,
    }
}

fn transition_proof_lifecycle_is_admitted(
    shadow: &StoredTransitionProofShadow,
    invocation: crate::agent_sdk::InvocationId,
    lifecycle: ReplayTransitionProofLifecycle,
) -> bool {
    match lifecycle {
        ReplayTransitionProofLifecycle::Invoke => !shadow.live.contains_key(&invocation),
        ReplayTransitionProofLifecycle::Resume(expected)
        | ReplayTransitionProofLifecycle::Acknowledge(expected) => {
            expected.invocation == invocation && shadow.live(invocation) == Some(expected)
        }
    }
}

fn transition_proof_position(event: &MergeEvent) -> ReplayPosition {
    ReplayPosition::Merge {
        id: event.id(),
        causal_height: event.causal_height,
        ordered_base: event.ordered_base,
    }
}

fn load_publication_merge_suffix<S: AgentJournalStore>(
    store: &S,
    publication: &ReplaySealedPublication,
    predecessor: &JournalHeads,
    frontier_id: MergeFrontierId,
) -> Result<Vec<MergeEvent>, JournalStoreError> {
    let frontier = match publication.anchor() {
        ReplayPublicationAnchor::Merge { frontier, .. } if frontier.id() == frontier_id => {
            frontier.clone()
        }
        _ => require_record::<S, MergeFrontier>(store, frontier_id)?,
    };
    if frontier.id() != frontier_id || frontier.genesis != predecessor.genesis {
        return Err(JournalStoreError::NonCanonical);
    }
    let boundary = retained_merge_boundary(store, predecessor)?;
    let staged_event = match publication.anchor() {
        ReplayPublicationAnchor::Merge { event, .. } => Some(event),
        _ => None,
    };
    let mut events = BTreeMap::new();
    let mut stack = frontier.events.clone();
    let mut bytes = 0_usize;
    while let Some(id) = stack.pop() {
        if events.contains_key(&id) {
            continue;
        }
        let event = match staged_event {
            Some(event) if event.id() == id => event.clone(),
            _ => require_record::<S, MergeEvent>(store, id)?,
        };
        if event.id() != id || event.genesis != predecessor.genesis {
            return Err(JournalStoreError::Corrupt);
        }
        bytes = bytes
            .checked_add(event.encode().len())
            .ok_or(JournalStoreError::LimitExceeded)?;
        if events.len() >= MAX_REPLAY_SUFFIX_ENTRIES || bytes > MAX_REPLAY_SUFFIX_BYTES {
            return Err(JournalStoreError::LimitExceeded);
        }
        if !boundary.tips.contains(&id) {
            stack.extend(event.parents.iter().copied());
        }
        events.insert(id, event);
    }
    if !boundary.tips.iter().all(|id| events.contains_key(id)) {
        return Err(JournalStoreError::Corrupt);
    }
    let dag = ValidatedMergeDag {
        events,
        boundary: boundary.tips.clone(),
    };
    if dag.canonical_frontier(&frontier.events)? != frontier.events {
        return Err(JournalStoreError::NonCanonical);
    }
    for (id, event) in &dag.events {
        if dag.boundary.contains(id) {
            continue;
        }
        let expected_height = if event.parents.is_empty() {
            1
        } else {
            event
                .parents
                .iter()
                .map(|parent| {
                    dag.events
                        .get(parent)
                        .map(|event| event.causal_height)
                        .ok_or(JournalStoreError::Corrupt)
                })
                .collect::<Result<Vec<_>, _>>()?
                .into_iter()
                .max()
                .ok_or(JournalStoreError::Corrupt)?
                .checked_add(1)
                .ok_or(JournalStoreError::LimitExceeded)?
        };
        if event.causal_height != expected_height {
            return Err(JournalStoreError::Corrupt);
        }
    }
    let mut suffix = dag
        .events
        .into_iter()
        .filter(|(id, _)| !dag.boundary.contains(id))
        .map(|(_, event)| event)
        .collect::<Vec<_>>();
    suffix.sort_unstable_by_key(|event| (event.causal_height, event.id()));
    Ok(suffix)
}

fn transition_proof_lifecycle_input(
    input: ReplayInput,
    position: ReplayPosition,
    requirement_context: StoredTransitionProofRequirementContext,
    final_acknowledgement: bool,
) -> Option<StoredTransitionProofLifecycleInput> {
    let (_, lifecycle) = transition_proof_lifecycle(&input)?;
    Some(StoredTransitionProofLifecycleInput {
        input,
        position,
        lifecycle,
        requirement_context,
        final_acknowledgement,
    })
}

fn canonical_transition_proof_inputs<S: AgentJournalStore>(
    store: &S,
    publication: &ReplaySealedPublication,
    predecessor: &JournalHeads,
) -> Result<
    (
        Vec<StoredTransitionProofLifecycleInput>,
        Option<StoredTransitionProofLifecycleInput>,
        BTreeSet<MergeEventId>,
    ),
    JournalStoreError,
> {
    let mut merge_inputs = Vec::new();
    let mut predecessor_suffix = BTreeSet::new();
    if !matches!(publication.anchor(), ReplayPublicationAnchor::Local(_)) {
        for event in load_publication_merge_suffix(
            store,
            publication,
            predecessor,
            predecessor.merge_frontier,
        )? {
            predecessor_suffix.insert(event.id());
        }
    }

    let current_input = match publication.anchor() {
        ReplayPublicationAnchor::Merge {
            event: imported,
            frontier,
        } => {
            for event in
                load_publication_merge_suffix(store, publication, predecessor, frontier.id())?
            {
                let context = if event.id() == imported.id() {
                    StoredTransitionProofRequirementContext::Lifecycle
                } else {
                    StoredTransitionProofRequirementContext::Recanonicalize
                };
                if let Some(input) = transition_proof_lifecycle_input(
                    event.input.clone(),
                    transition_proof_position(&event),
                    context,
                    false,
                ) {
                    merge_inputs.push(input);
                }
            }
            None
        }
        ReplayPublicationAnchor::Ordered(entry) => {
            let replaying_merge = entry.merge_seal.is_some()
                || !matches!(publication.mode(), ReplayPublicationMode::Canonical);
            if replaying_merge {
                let context = if matches!(
                    publication.mode(),
                    ReplayPublicationMode::SharedOrderedPreserveMerge
                ) {
                    StoredTransitionProofRequirementContext::Preserve
                } else {
                    StoredTransitionProofRequirementContext::Recanonicalize
                };
                for event in load_publication_merge_suffix(
                    store,
                    publication,
                    predecessor,
                    entry.merge_frontier,
                )? {
                    if let Some(input) = transition_proof_lifecycle_input(
                        event.input.clone(),
                        transition_proof_position(&event),
                        context,
                        entry.merge_seal.is_some(),
                    ) {
                        merge_inputs.push(input);
                    }
                }
            }
            transition_proof_lifecycle_input(
                entry.input.clone(),
                ReplayPosition::Ordered {
                    id: entry.id(),
                    index: entry.index,
                    merge_frontier: entry.merge_frontier,
                    merge_seal: entry.merge_seal,
                },
                StoredTransitionProofRequirementContext::Lifecycle,
                true,
            )
        }
        ReplayPublicationAnchor::Local(entry) => transition_proof_lifecycle_input(
            entry.input.clone(),
            ReplayPosition::Local {
                id: entry.id(),
                node: entry.node,
                revision: entry.revision,
                ordered_base: entry.ordered_base,
                merge_frontier: entry.merge_frontier,
            },
            StoredTransitionProofRequirementContext::Lifecycle,
            true,
        ),
        ReplayPublicationAnchor::Checkpoint(_) => None,
    };
    Ok((merge_inputs, current_input, predecessor_suffix))
}

fn transition_proof_external_projection<S: AgentJournalStore>(
    store: &S,
    predecessor: &JournalHeads,
    previous: &TransitionProofIndexManifest,
    boundary: &StoredTransitionProofShadow,
    predecessor_merge_suffix: &BTreeSet<MergeEventId>,
) -> Result<
    BTreeMap<crate::agent_sdk::InvocationId, Option<crate::agent_sdk::proof::TransitionProofKey>>,
    JournalStoreError,
> {
    let mut external = BTreeMap::new();
    for boundary_key in boundary.live.values().flatten() {
        if previous.get(*boundary_key).is_none() {
            return Err(JournalStoreError::MissingObject);
        }
        if previous.live(boundary_key.invocation).is_none()
            && transition_proof_key_is_retired(
                store,
                predecessor.genesis,
                previous.retired_root(),
                *boundary_key,
            )?
        {
            external.insert(boundary_key.invocation, None);
        }
    }
    // A post-boundary acknowledgement can retire a proof first published by
    // any lane. Its current live slot is empty, so boundary/current
    // comparison alone cannot preserve the external tombstone. Retained
    // records plus exact purpose-tagged history make that absence
    // independently discoverable; a later current live edge for the same
    // invocation is overlaid below and wins.
    for entry in previous.entries() {
        if previous.live(entry.key.invocation).is_some() {
            continue;
        }
        if transition_proof_key_is_retired(
            store,
            predecessor.genesis,
            previous.retired_root(),
            entry.key,
        )? {
            external.insert(entry.key.invocation, None);
        }
    }
    for key in previous.live_entries() {
        if boundary.live(key.invocation) == Some(*key) {
            continue;
        }
        let entry = previous.get(*key).ok_or(JournalStoreError::Corrupt)?;
        let proof = require_record::<S, JournalTransitionProof>(store, entry.record)?;
        let belongs_to_replaced_merge_suffix = matches!(
            proof.anchor(),
            TransitionProofAnchor::Merge { event, .. }
                if predecessor_merge_suffix.contains(&event)
        );
        if !belongs_to_replaced_merge_suffix {
            external.insert(key.invocation, Some(*key));
        }
    }
    Ok(external)
}

fn retain_transition_proof_record(
    manifest: &TransitionProofIndexManifest,
    entry: TransitionProofIndexEntry,
) -> Result<TransitionProofIndexManifest, JournalStoreError> {
    if let Some(existing) = manifest.get(entry.key) {
        return (existing == entry)
            .then(|| manifest.clone())
            .ok_or(JournalStoreError::Conflict);
    }
    let prior = manifest.live(entry.key.invocation);
    let mut retained = manifest
        .publish(entry, prior)
        .map_err(map_transition_proof_index_error)?;
    match prior {
        Some(prior) => {
            let prior_entry = retained.get(prior).ok_or(JournalStoreError::Corrupt)?;
            retained = retained
                .publish(prior_entry, Some(entry.key))
                .map_err(map_transition_proof_index_error)?;
        }
        None => {
            retained = retained
                .retire(entry.key)
                .map_err(map_transition_proof_index_error)?;
        }
    }
    Ok(retained)
}

fn set_transition_proof_live(
    manifest: &TransitionProofIndexManifest,
    invocation: crate::agent_sdk::InvocationId,
    desired: Option<crate::agent_sdk::proof::TransitionProofKey>,
) -> Result<TransitionProofIndexManifest, JournalStoreError> {
    let current = manifest.live(invocation);
    if current == desired {
        return Ok(manifest.clone());
    }
    match desired {
        Some(key) => {
            if key.invocation != invocation {
                return Err(JournalStoreError::NonCanonical);
            }
            let entry = manifest.get(key).ok_or(JournalStoreError::MissingObject)?;
            manifest
                .publish(entry, current)
                .map_err(map_transition_proof_index_error)
        }
        None => manifest
            .retire(current.ok_or(JournalStoreError::Conflict)?)
            .map_err(map_transition_proof_index_error),
    }
}

fn validate_transition_proof_acknowledgement_action(
    input: &StoredTransitionProofLifecycleInput,
    action_input: super::journal::ReplayInputId,
    action_position: ReplayPosition,
    key: crate::agent_sdk::proof::TransitionProofKey,
    final_acknowledgement: bool,
) -> Result<(), JournalStoreError> {
    let ReplayTransitionProofLifecycle::Acknowledge(expected) = input.lifecycle else {
        return Err(JournalStoreError::NonCanonical);
    };
    if input.input.id() != action_input
        || input.position != action_position
        || expected != key
        || input.final_acknowledgement != final_acknowledgement
        || (!final_acknowledgement && !matches!(input.position, ReplayPosition::Merge { .. }))
    {
        return Err(JournalStoreError::NonCanonical);
    }
    Ok(())
}

fn transition_proof_action_position(action: &ReplayTransitionProofAction) -> ReplayPosition {
    match action {
        ReplayTransitionProofAction::Requirement(requirement) => requirement.position(),
        ReplayTransitionProofAction::Acknowledgement(acknowledgement) => acknowledgement.position(),
        ReplayTransitionProofAction::Retirement(retirement) => retirement.position(),
        ReplayTransitionProofAction::Stale(stale) => stale.position(),
    }
}

#[allow(clippy::too_many_arguments)]
fn apply_transition_proof_lifecycle_input<S: AgentJournalStore>(
    store: &mut S,
    publication: &ReplaySealedPublication,
    predecessor: &JournalHeads,
    previous: &TransitionProofIndexManifest,
    input: &StoredTransitionProofLifecycleInput,
    actions: &[ReplayTransitionProofAction],
    action_cursor: &mut usize,
    publications: &[StagedTransitionProof],
    publication_cursor: &mut usize,
    derived: &mut TransitionProofIndexManifest,
    shadow: &mut StoredTransitionProofShadow,
    projection: &mut StoredTransitionProofShadow,
    anchors: &mut Vec<TransitionProofAnchor>,
    retired: &mut Vec<crate::agent_sdk::proof::TransitionProofKey>,
) -> Result<(), JournalStoreError> {
    let (invocation, lifecycle) =
        transition_proof_lifecycle(&input.input).ok_or(JournalStoreError::NonCanonical)?;
    if lifecycle != input.lifecycle {
        return Err(JournalStoreError::NonCanonical);
    }
    shadow.seed_terminal(store, predecessor.genesis, invocation)?;
    projection.seed_terminal(store, predecessor.genesis, invocation)?;
    if projection.has_tombstone(invocation) {
        // The predecessor root may contain a terminal acknowledgement made
        // after the retained Merge boundary. It is external to the suffix
        // being rebuilt and therefore constrains admission even when its
        // compacted proof record is no longer enumerable from AJP3.
        shadow.live.insert(invocation, None);
    }
    let admitted = transition_proof_lifecycle_is_admitted(shadow, invocation, lifecycle);
    if !admitted {
        let Some(ReplayTransitionProofAction::Stale(stale)) = actions.get(*action_cursor) else {
            return Err(JournalStoreError::NonCanonical);
        };
        if stale.input() != input.input.id()
            || stale.position() != input.position
            || stale.lifecycle() != input.lifecycle
        {
            return Err(JournalStoreError::NonCanonical);
        }
        *action_cursor = action_cursor
            .checked_add(1)
            .ok_or(JournalStoreError::LimitExceeded)?;
        return Ok(());
    }

    match lifecycle {
        ReplayTransitionProofLifecycle::Invoke | ReplayTransitionProofLifecycle::Resume(_) => {
            let Some(ReplayTransitionProofAction::Requirement(requirement)) =
                actions.get(*action_cursor)
            else {
                return Err(JournalStoreError::NonCanonical);
            };
            if requirement.input() != input.input.id()
                || requirement.position() != input.position
                || requirement.lifecycle() != input.lifecycle
            {
                return Err(JournalStoreError::NonCanonical);
            }
            let expected_shape = match (input.requirement_context, input.lifecycle) {
                (
                    StoredTransitionProofRequirementContext::Lifecycle,
                    ReplayTransitionProofLifecycle::Invoke,
                ) => (
                    ReplayTransitionProofIntent::FirstPublication,
                    ReplayTransitionProofProjectionAction::UpdateLive,
                ),
                (
                    StoredTransitionProofRequirementContext::Lifecycle,
                    ReplayTransitionProofLifecycle::Resume(expected),
                ) => (
                    ReplayTransitionProofIntent::Resume(expected),
                    ReplayTransitionProofProjectionAction::UpdateLive,
                ),
                (
                    StoredTransitionProofRequirementContext::Recanonicalize,
                    ReplayTransitionProofLifecycle::Invoke
                    | ReplayTransitionProofLifecycle::Resume(_),
                ) => (
                    ReplayTransitionProofIntent::Recanonicalize,
                    ReplayTransitionProofProjectionAction::UpdateLive,
                ),
                (
                    StoredTransitionProofRequirementContext::Preserve,
                    ReplayTransitionProofLifecycle::Invoke
                    | ReplayTransitionProofLifecycle::Resume(_),
                ) => (
                    ReplayTransitionProofIntent::Recanonicalize,
                    ReplayTransitionProofProjectionAction::ValidateOnly,
                ),
                (_, ReplayTransitionProofLifecycle::Acknowledge(_)) => {
                    return Err(JournalStoreError::NonCanonical);
                }
            };
            if (requirement.intent(), requirement.projection_action()) != expected_shape {
                return Err(JournalStoreError::NonCanonical);
            }
            let (entry, proof, prepared) = match requirement.projection() {
                ReplayTransitionProofProjection::Prepared => {
                    let staged = publications
                        .get(*publication_cursor)
                        .ok_or(JournalStoreError::NonCanonical)?;
                    if staged.store != store.instance_id() || staged.predecessor != predecessor.id()
                    {
                        return Err(JournalStoreError::Conflict);
                    }
                    *publication_cursor = publication_cursor
                        .checked_add(1)
                        .ok_or(JournalStoreError::LimitExceeded)?;
                    let proof =
                        require_record::<S, JournalTransitionProof>(store, staged.entry.record)?;
                    (staged.entry, proof, true)
                }
                ReplayTransitionProofProjection::Published => {
                    let entry = previous
                        .get(requirement.binding().key())
                        .ok_or(JournalStoreError::MissingObject)?;
                    let proof = require_record::<S, JournalTransitionProof>(store, entry.record)?;
                    (entry, proof, false)
                }
            };
            if matches!(
                requirement.projection_action(),
                ReplayTransitionProofProjectionAction::ValidateOnly
            ) && prepared
            {
                return Err(JournalStoreError::NonCanonical);
            }
            validate_transition_proof_requirement(
                store,
                publication,
                requirement,
                entry,
                &proof,
                prepared,
            )?;
            if anchors.contains(&proof.anchor()) {
                return Err(JournalStoreError::NonCanonical);
            }
            anchors.push(proof.anchor());
            *derived = retain_transition_proof_record(derived, entry)?;
            shadow.install(entry.key);
            if matches!(
                requirement.projection_action(),
                ReplayTransitionProofProjectionAction::UpdateLive
            ) {
                projection.install(entry.key);
            }
            *action_cursor = action_cursor
                .checked_add(1)
                .ok_or(JournalStoreError::LimitExceeded)?;
        }
        ReplayTransitionProofLifecycle::Acknowledge(expected) => {
            // Clean operations deliberately do not mutate InvocationIndex.
            // The private replay seal is the Applied/no-effect authority;
            // storage independently binds the exact canonical input,
            // position, and live-edge condition here.
            // A rejected acknowledgement has no action. Do not consume or
            // reject the next canonical acknowledgement merely because it is
            // the next element in the ordered action vector; only an action
            // claiming this exact replay position belongs to this input.
            let action = actions
                .get(*action_cursor)
                .filter(|action| transition_proof_action_position(action) == input.position);
            let consumed = match action {
                Some(ReplayTransitionProofAction::Retirement(retirement))
                    if input.final_acknowledgement =>
                {
                    validate_transition_proof_acknowledgement_action(
                        input,
                        retirement.input(),
                        retirement.position(),
                        retirement.key(),
                        true,
                    )?;
                    validate_transition_proof_retirement(
                        store,
                        publication,
                        predecessor,
                        *retirement,
                    )?;
                    if retired.contains(&expected) {
                        return Err(JournalStoreError::NonCanonical);
                    }
                    retired.push(expected);
                    true
                }
                Some(ReplayTransitionProofAction::Acknowledgement(acknowledgement))
                    if !input.final_acknowledgement =>
                {
                    validate_transition_proof_acknowledgement_action(
                        input,
                        acknowledgement.input(),
                        acknowledgement.position(),
                        acknowledgement.key(),
                        false,
                    )?;
                    true
                }
                Some(
                    ReplayTransitionProofAction::Retirement(_)
                    | ReplayTransitionProofAction::Acknowledgement(_),
                ) => return Err(JournalStoreError::NonCanonical),
                Some(
                    ReplayTransitionProofAction::Requirement(_)
                    | ReplayTransitionProofAction::Stale(_),
                )
                | None => false,
            };
            if !consumed {
                // Rejected/non-Applied acknowledgement has no sealed effect.
                return Ok(());
            }
            if !shadow.retire(expected) {
                return Err(JournalStoreError::NonCanonical);
            }
            if input.final_acknowledgement && !projection.retire(expected) {
                return Err(JournalStoreError::NonCanonical);
            }
            *action_cursor = action_cursor
                .checked_add(1)
                .ok_or(JournalStoreError::LimitExceeded)?;
        }
    }
    Ok(())
}

fn derive_transition_proof_apply<S: AgentJournalStore>(
    store: &mut S,
    publication: &ReplaySealedPublication,
    predecessor: &JournalHeads,
    previous: &TransitionProofIndexManifest,
    publications: &[StagedTransitionProof],
) -> Result<
    (
        TransitionProofIndexManifest,
        Vec<crate::agent_sdk::proof::TransitionProofKey>,
    ),
    JournalStoreError,
> {
    let (merge_inputs, current_input, predecessor_merge_suffix) =
        canonical_transition_proof_inputs(store, publication, predecessor)?;
    let mut all_inputs = merge_inputs.clone();
    if let Some(current) = &current_input {
        all_inputs
            .try_reserve(1)
            .map_err(|_| JournalStoreError::LimitExceeded)?;
        all_inputs.push(current.clone());
    }
    if all_inputs.len() > MAX_REPLAY_SUFFIX_ENTRIES
        || publication.transition_proof_actions().len() > MAX_REPLAY_SUFFIX_ENTRIES
    {
        return Err(JournalStoreError::LimitExceeded);
    }
    let rebuilds_merge = matches!(publication.anchor(), ReplayPublicationAnchor::Merge { .. })
        || matches!(publication.anchor(), ReplayPublicationAnchor::Ordered(entry) if entry.merge_seal.is_some())
        || !matches!(publication.mode(), ReplayPublicationMode::Canonical);
    let preserves_merge = matches!(
        publication.mode(),
        ReplayPublicationMode::SharedOrderedPreserveMerge
    );
    let boundary = StoredTransitionProofShadow::from_replay_boundary(publication);
    let authenticated_boundary =
        transition_proof_index_at_replay_boundary(store, predecessor, predecessor.merge_fence)?;
    if !boundary.matches_manifest(&authenticated_boundary) {
        return Err(JournalStoreError::NonCanonical);
    }
    let external = if rebuilds_merge {
        transition_proof_external_projection(
            store,
            predecessor,
            previous,
            &boundary,
            &predecessor_merge_suffix,
        )?
    } else {
        BTreeMap::new()
    };
    let mut shadow = if rebuilds_merge {
        boundary
    } else {
        StoredTransitionProofShadow::from_manifest(previous)
    };
    // A Shared Ordered splice validates the pinned Merge suffix against its
    // authenticated fence boundary, but it preserves the predecessor's
    // newer physical Merge projection. The current Ordered input must then
    // admit against that physical projection, not the pinned suffix tip.
    let mut projection = if preserves_merge {
        StoredTransitionProofShadow::from_manifest(previous)
    } else {
        shadow.clone()
    };
    // Ordered/Local proof edges and terminal tombstones published after the
    // Merge boundary constrain admission before the replaceable suffix is
    // replayed. Applying them only after the walk would run stale guest/proof
    // work and then merely discard its staged result.
    if rebuilds_merge {
        shadow.overlay(&external);
        projection.overlay(&external);
    }
    let mut derived = previous.clone();
    let mut action_cursor = 0_usize;
    let mut publication_cursor = 0_usize;
    let mut anchors = Vec::new();
    let mut retired = Vec::new();

    for input in &merge_inputs {
        apply_transition_proof_lifecycle_input(
            store,
            publication,
            predecessor,
            previous,
            input,
            publication.transition_proof_actions(),
            &mut action_cursor,
            publications,
            &mut publication_cursor,
            &mut derived,
            &mut shadow,
            &mut projection,
            &mut anchors,
            &mut retired,
        )?;
    }
    if preserves_merge {
        shadow = projection.clone();
    }
    if let Some(input) = &current_input {
        apply_transition_proof_lifecycle_input(
            store,
            publication,
            predecessor,
            previous,
            input,
            publication.transition_proof_actions(),
            &mut action_cursor,
            publications,
            &mut publication_cursor,
            &mut derived,
            &mut shadow,
            &mut projection,
            &mut anchors,
            &mut retired,
        )?;
    }
    if action_cursor != publication.transition_proof_actions().len()
        || publication_cursor != publications.len()
    {
        return Err(JournalStoreError::NonCanonical);
    }

    let mut invocations = derived
        .live_entries()
        .iter()
        .map(|key| key.invocation)
        .chain(projection.live.keys().copied())
        .collect::<Vec<_>>();
    invocations.sort_unstable();
    invocations.dedup();
    for invocation in invocations {
        let desired = projection.live(invocation);
        if let Some(key) = desired {
            if derived.live(invocation) != Some(key)
                && transition_proof_key_is_retired(
                    store,
                    predecessor.genesis,
                    previous.retired_root(),
                    key,
                )?
            {
                return Err(JournalStoreError::Conflict);
            }
        }
        derived = set_transition_proof_live(&derived, invocation, desired)?;
    }
    Ok((derived, retired))
}

fn transition_proof_retirements_are_canonical(
    retirements: &[super::replay::ReplayTransitionProofRetirement],
) -> bool {
    let mut last_merge = None;
    let mut saw_current = false;
    for (index, retirement) in retirements.iter().enumerate() {
        if !retirement.key().validate()
            || retirements[..index].iter().any(|prior| {
                prior.key().invocation == retirement.key().invocation
                    || prior.input() == retirement.input()
                    || prior.position() == retirement.position()
            })
        {
            return false;
        }
        match retirement.position() {
            ReplayPosition::Merge {
                id, causal_height, ..
            } if !saw_current => {
                let order = (causal_height, id);
                if last_merge.is_some_and(|prior| prior >= order) {
                    return false;
                }
                last_merge = Some(order);
            }
            ReplayPosition::Ordered { .. } | ReplayPosition::Local { .. }
                if !saw_current && index + 1 == retirements.len() =>
            {
                saw_current = true;
            }
            ReplayPosition::Genesis
            | ReplayPosition::Merge { .. }
            | ReplayPosition::Ordered { .. }
            | ReplayPosition::Local { .. } => return false,
        }
    }
    true
}

impl<S> JournalVerifiedTransitionPublisher<'_, S>
where
    S: TransitionProofPublicationStore,
{
    pub(crate) fn stage_verified(
        &mut self,
        prepared: &PreparedVerifiedTransition,
        context: TransitionProofStageContext<'_>,
    ) -> Result<StagedTransitionProof, JournalStoreError> {
        let current = self
            .store
            .heads()?
            .ok_or(JournalStoreError::NotInitialized)?;
        let runtime_is_replay_anchored = match context.position {
            ReplayPosition::Ordered { .. } | ReplayPosition::Local { .. } => {
                context.input.runtime == current.runtime
            }
            ReplayPosition::Merge { ordered_base, .. } => {
                ordered_base.index < current.ordered_index
                    || (ordered_base.index == current.ordered_index
                        && ordered_base.head == current.ordered_head)
            }
            ReplayPosition::Genesis => false,
        };
        if current.id() != context.expected_heads
            || current.genesis != context.artifacts.genesis
            || !runtime_is_replay_anchored
            || context
                .expected_live
                .is_some_and(|key| key.invocation != prepared.key().invocation)
        {
            return Err(JournalStoreError::Conflict);
        }
        validate_head_targets(self.store, &current)?;
        let anchor = transition_proof_anchor_for_position(context.position)?;
        let runtime_package = context.input.runtime.package.clone();
        let actor_package = service_proof_blob(prepared.actor_package());
        if !runtime_package.matches(context.runtime_package)
            || !actor_package.matches(context.actor_package)
            || service_proof_blob(&prepared.proof_record().statement.subject.runtime_package)
                != runtime_package
            || !context.artifacts.artifacts.contains(&runtime_package)
            || !context.artifacts.artifacts.contains(&actor_package)
        {
            return Err(JournalStoreError::NonCanonical);
        }

        let manifest = crate::agent_sdk::proof::TransitionProofMaterialManifest::decode(
            prepared.proof_manifest_bytes(),
        )
        .map_err(|_| JournalStoreError::NonCanonical)?;
        if manifest
            .encode()
            .map_err(|_| JournalStoreError::NonCanonical)?
            != prepared.proof_manifest_bytes()
            || !manifest.matches_material(prepared.proof_material())
            || service_proof_blob(&prepared.proof_record().proof)
                != BlobRef::of_bytes(prepared.proof_manifest_bytes())
        {
            return Err(JournalStoreError::NonCanonical);
        }

        // Every referenced byte/object is made durable and exact-read back
        // before a replay-sealed publication can name the resulting index.
        self.store.stage_proof_predecessor(&current)?;
        self.store.put_blob(
            JournalBlobClass::CatalogArtifact,
            &runtime_package,
            context.runtime_package,
        )?;
        self.store.put_blob(
            JournalBlobClass::CatalogArtifact,
            &actor_package,
            context.actor_package,
        )?;
        self.store.put(context.input)?;
        self.store.put(context.artifacts)?;

        let canonical_work = BlobRef::of_bytes(prepared.canonical_work());
        let canonical_transition = BlobRef::of_bytes(prepared.canonical_transition());
        let manifest_ref = BlobRef::of_bytes(prepared.proof_manifest_bytes());
        self.store.put_blob(
            JournalBlobClass::TransitionProof,
            &canonical_work,
            prepared.canonical_work(),
        )?;
        self.store.put_blob(
            JournalBlobClass::TransitionProof,
            &canonical_transition,
            prepared.canonical_transition(),
        )?;
        self.store.put_blob(
            JournalBlobClass::TransitionProof,
            &manifest_ref,
            prepared.proof_manifest_bytes(),
        )?;
        let chunk_bytes =
            usize::try_from(crate::agent_sdk::proof::TRANSITION_PROOF_MATERIAL_CHUNK_BYTES)
                .map_err(|_| JournalStoreError::LimitExceeded)?;
        for (chunk, bytes) in manifest
            .chunks
            .iter()
            .zip(prepared.proof_material().chunks(chunk_bytes))
        {
            self.store.put_blob(
                JournalBlobClass::TransitionProof,
                &service_proof_blob(chunk),
                bytes,
            )?;
        }

        let publication = prepared.expected_fact().publication();
        let proof = JournalTransitionProof::new(
            current.genesis,
            current.id(),
            context.input.id(),
            anchor,
            canonical_work,
            canonical_transition,
            context.artifacts.id(),
            actor_package,
            prepared.proof_record().clone(),
            manifest,
            Hash(publication.0),
        )
        .map_err(|_| JournalStoreError::NonCanonical)?;
        let entry = TransitionProofIndexEntry::for_record(&proof)
            .map_err(|_| JournalStoreError::NonCanonical)?;
        self.store.put(&proof)?;
        if self.store.get::<ReplayInput>(context.input.id())?.as_ref() != Some(context.input)
            || self
                .store
                .get::<ArtifactClosure>(context.artifacts.id())?
                .as_ref()
                != Some(context.artifacts)
            || self
                .store
                .get::<JournalTransitionProof>(proof.id())?
                .as_ref()
                != Some(&proof)
            || self.store.historical_heads(current.id())?.as_ref() != Some(&current)
        {
            return Err(JournalStoreError::Corrupt);
        }
        Ok(StagedTransitionProof {
            store: self.store.instance_id(),
            predecessor: current.id(),
            entry,
        })
    }

    pub(crate) fn stage_apply_batch(
        &mut self,
        publication: &ReplaySealedPublication,
        publications: Vec<StagedTransitionProof>,
    ) -> Result<StagedTransitionProofBatch, JournalStoreError> {
        if publication.transition_proof_batch().is_some()
            || publications.len() > MAX_REPLAY_SUFFIX_ENTRIES
            || publication.transition_proof_actions().len() > MAX_REPLAY_SUFFIX_ENTRIES
        {
            return Err(JournalStoreError::LimitExceeded);
        }
        if publications.iter().enumerate().any(|(index, staged)| {
            publications[..index]
                .iter()
                .any(|prior| prior.entry.key == staged.entry.key)
        }) {
            return Err(JournalStoreError::NonCanonical);
        }
        let current = self
            .store
            .heads()?
            .ok_or(JournalStoreError::NotInitialized)?;
        if current.id() != publication.expected()
            || publication.next().transition_proofs != current.transition_proofs
            || matches!(publication.anchor(), ReplayPublicationAnchor::Checkpoint(_))
            || publication.transition_proof_actions().is_empty()
        {
            return Err(JournalStoreError::Conflict);
        }
        let previous = require_record::<S, TransitionProofIndexManifest>(
            self.store,
            current.transition_proofs,
        )?;
        let (mut next, retired) = derive_transition_proof_apply(
            self.store,
            publication,
            &current,
            &previous,
            &publications,
        )?;
        let retirement_plan = prepare_transition_proof_retirements(
            self.store,
            current.genesis,
            previous.retired_root(),
            &retired,
        )?;
        if let Some(plan) = &retirement_plan {
            next = next
                .with_retired_root(previous.retired_root(), plan.root())
                .map_err(map_transition_proof_index_error)?;
        }
        self.store.stage_proof_predecessor(&current)?;
        self.store.put(&next)?;
        if self
            .store
            .get::<TransitionProofIndexManifest>(next.id())?
            .as_ref()
            != Some(&next)
        {
            return Err(JournalStoreError::Corrupt);
        }
        Ok(StagedTransitionProofBatch {
            store: self.store.instance_id(),
            predecessor: current.id(),
            previous: current.transition_proofs,
            next,
            mutation: StagedTransitionProofMutation::Apply,
            publications,
            retirement_plan,
        })
    }

    pub(crate) fn stage_retirement(
        &mut self,
        expected_live: crate::agent_sdk::proof::TransitionProofKey,
    ) -> Result<StagedTransitionProofBatch, JournalStoreError> {
        let current = self
            .store
            .heads()?
            .ok_or(JournalStoreError::NotInitialized)?;
        let previous = require_record::<S, TransitionProofIndexManifest>(
            self.store,
            current.transition_proofs,
        )?;
        let mut next = previous
            .retire(expected_live)
            .map_err(map_transition_proof_index_error)?;
        let retirement_plan = prepare_transition_proof_retirements(
            self.store,
            current.genesis,
            previous.retired_root(),
            core::slice::from_ref(&expected_live),
        )?;
        if let Some(plan) = &retirement_plan {
            next = next
                .with_retired_root(previous.retired_root(), plan.root())
                .map_err(map_transition_proof_index_error)?;
        }
        self.store.stage_proof_predecessor(&current)?;
        self.store.put(&next)?;
        Ok(StagedTransitionProofBatch {
            store: self.store.instance_id(),
            predecessor: current.id(),
            previous: current.transition_proofs,
            next,
            mutation: StagedTransitionProofMutation::Apply,
            publications: Vec::new(),
            retirement_plan,
        })
    }

    pub(crate) fn stage_checkpoint_compaction(
        &mut self,
    ) -> Result<StagedTransitionProofBatch, JournalStoreError> {
        let current = self
            .store
            .heads()?
            .ok_or(JournalStoreError::NotInitialized)?;
        let previous = require_record::<S, TransitionProofIndexManifest>(
            self.store,
            current.transition_proofs,
        )?;
        let next = previous
            .checkpointed()
            .map_err(map_transition_proof_index_error)?;
        self.store.stage_proof_predecessor(&current)?;
        self.store.put(&next)?;
        Ok(StagedTransitionProofBatch {
            store: self.store.instance_id(),
            predecessor: current.id(),
            previous: current.transition_proofs,
            next,
            mutation: StagedTransitionProofMutation::Checkpoint,
            publications: Vec::new(),
            retirement_plan: None,
        })
    }
}

fn prepare_transition_proof_retirements<S: TransitionProofPublicationStore>(
    store: &S,
    genesis: AgentJournalGenesisId,
    root: Option<InvocationHistoryNodeId>,
    keys: &[crate::agent_sdk::proof::TransitionProofKey],
) -> Result<Option<InvocationHistoryWritePlan>, JournalStoreError> {
    let facts = missing_transition_proof_retirement_facts(store, genesis, root, keys)?;
    if facts.is_empty() {
        return Ok(None);
    }
    let mut history =
        InvocationHistory::open(store, genesis, InvocationOwnershipScope::Ordered, root)
            .map_err(map_invocation_history_error)?;
    history
        .require_history_purpose(true)
        .map_err(map_invocation_history_error)?;
    for fact in facts {
        if !history
            .insert(fact)
            .map_err(map_invocation_history_error)?
            .inserted()
        {
            return Err(JournalStoreError::Corrupt);
        }
    }
    history
        .write_plan()
        .map(Some)
        .map_err(map_invocation_history_error)
}

fn missing_transition_proof_retirement_facts<
    S: InvocationHistoryStore<Error = JournalStoreError>,
>(
    store: &S,
    genesis: AgentJournalGenesisId,
    root: Option<InvocationHistoryNodeId>,
    keys: &[crate::agent_sdk::proof::TransitionProofKey],
) -> Result<Vec<super::journal::InvocationAcknowledgedFact>, JournalStoreError> {
    if keys.is_empty() {
        return Ok(Vec::new());
    }
    let mut exact = keys.to_vec();
    exact.sort_unstable_by_key(|key| (key.invocation, key.execution));
    for pair in exact.windows(2) {
        if pair[0].invocation == pair[1].invocation && pair[0] != pair[1] {
            // One logical invocation has exactly one terminal execution.
            // A batch may retry the same fact, but it cannot mint competing
            // terminal executions beneath the same Patricia key.
            return Err(JournalStoreError::Conflict);
        }
    }
    exact.dedup();
    if exact.len() > MAX_REPLAY_SUFFIX_ENTRIES {
        return Err(JournalStoreError::LimitExceeded);
    }
    let history = InvocationHistory::open(store, genesis, InvocationOwnershipScope::Ordered, root)
        .map_err(map_invocation_history_error)?;
    history
        .require_history_purpose(true)
        .map_err(map_invocation_history_error)?;
    let mut missing = Vec::new();
    for key in exact {
        let fact = super::journal::InvocationAcknowledgedFact::for_transition_proof_retirement(
            genesis, key,
        )
        .map_err(|_| JournalStoreError::NonCanonical)?;
        match history
            .lookup(fact.key())
            .map_err(map_invocation_history_error)?
        {
            Some(existing) if existing == fact => {}
            Some(_) => return Err(JournalStoreError::Conflict),
            None => missing.push(fact),
        }
    }
    missing.sort_unstable_by_key(|fact| fact.key().invocation);
    Ok(missing)
}

fn transition_proof_key_is_retired<S: InvocationHistoryStore<Error = JournalStoreError>>(
    store: &S,
    genesis: AgentJournalGenesisId,
    root: Option<InvocationHistoryNodeId>,
    key: crate::agent_sdk::proof::TransitionProofKey,
) -> Result<bool, JournalStoreError> {
    if !key.validate() {
        return Err(JournalStoreError::NonCanonical);
    }
    Ok(transition_proof_retirement_for_invocation(store, genesis, root, key.invocation)?.is_some())
}

pub(crate) fn transition_proof_retirement_for_invocation<
    S: InvocationHistoryStore<Error = JournalStoreError>,
>(
    store: &S,
    genesis: AgentJournalGenesisId,
    root: Option<InvocationHistoryNodeId>,
    invocation: crate::agent_sdk::InvocationId,
) -> Result<Option<crate::agent_sdk::proof::TransitionProofKey>, JournalStoreError> {
    if invocation == crate::agent_sdk::InvocationId::ZERO {
        return Err(JournalStoreError::NonCanonical);
    }
    let Some(root) = root else {
        return Ok(None);
    };
    let history = InvocationHistory::open(
        store,
        genesis,
        InvocationOwnershipScope::Ordered,
        Some(root),
    )
    .map_err(map_invocation_history_error)?;
    history
        .require_history_purpose(true)
        .map_err(map_invocation_history_error)?;
    let lookup = super::journal::InvocationOwnershipKey {
        scope: InvocationOwnershipScope::Ordered,
        invocation: crate::service::InvocationId(*invocation.as_bytes()),
    };
    match history
        .lookup(lookup)
        .map_err(map_invocation_history_error)?
    {
        Some(fact) => fact
            .transition_proof_retirement_key()
            .filter(|key| key.invocation == invocation)
            .map(Some)
            .ok_or(JournalStoreError::Corrupt),
        None => Ok(None),
    }
}

impl<S> VerifiedTransitionPublisher for JournalVerifiedTransitionPublisher<'_, S>
where
    S: TransitionProofPublicationStore,
{
    type Error = JournalStoreError;

    fn load_published(
        &mut self,
        key: crate::agent_sdk::proof::TransitionProofKey,
    ) -> Result<Option<PublishedAttestedTransition>, Self::Error> {
        if !key.validate() {
            return Err(JournalStoreError::NonCanonical);
        }
        let heads = self
            .store
            .heads()?
            .ok_or(JournalStoreError::NotInitialized)?;
        validate_head_targets(self.store, &heads)?;
        let mut roots = vec![heads.transition_proofs];
        if let Some(checkpoint_id) = heads.checkpoint {
            let checkpoint = require_record::<S, CheckpointManifest>(self.store, checkpoint_id)?;
            if checkpoint.genesis != heads.genesis {
                return Err(JournalStoreError::Corrupt);
            }
            if !roots.contains(&checkpoint.transition_proofs) {
                roots.push(checkpoint.transition_proofs);
            }
        }

        let mut found = None;
        for root in roots {
            let index = validate_transition_proof_index_closure(self.store, root, &heads)?;
            let Some(entry) = index.get(key) else {
                continue;
            };
            let proof = require_record::<S, JournalTransitionProof>(self.store, entry.record)?;
            let canonical_work = require_transition_proof_blob(self.store, proof.canonical_work())?;
            let canonical_transition =
                require_transition_proof_blob(self.store, proof.canonical_transition())?;
            let manifest = require_transition_proof_blob(
                self.store,
                &service_proof_blob(&proof.proof_record().proof),
            )?;
            if manifest != proof.proof_manifest_wire() {
                return Err(JournalStoreError::Corrupt);
            }
            let published = PublishedAttestedTransition::reconstruct(
                canonical_work,
                canonical_transition,
                proof.proof_record().clone(),
                manifest,
                crate::agent_sdk::Hash(proof.publication().0),
            )
            .map_err(|_| JournalStoreError::Corrupt)?;
            if found
                .as_ref()
                .is_some_and(|retained| retained != &published)
            {
                return Err(JournalStoreError::Corrupt);
            }
            found = Some(published);
        }
        Ok(found)
    }

    fn load_retired(
        &mut self,
        key: crate::agent_sdk::proof::TransitionProofKey,
    ) -> Result<Option<AuthenticatedTransitionRetirement>, Self::Error> {
        if !key.validate() {
            return Err(JournalStoreError::NonCanonical);
        }
        let heads = self
            .store
            .heads()?
            .ok_or(JournalStoreError::NotInitialized)?;
        // Retirement recovery is intentionally not coupled to the one-write
        // freshness window required by destructive GC. Current heads carry
        // their authenticated checkpoint pointer forward across later
        // publications; validate that complete ancestry/closure, then query
        // the checkpoint's compact proof index. This lets a producer which
        // was offline across Ack, checkpoint, and subsequent writes safely
        // reclaim its exact private key without reopening a one-revision
        // window.
        validate_head_targets(self.store, &heads)?;
        let Some(checkpoint_id) = heads.checkpoint else {
            return Ok(None);
        };
        let checkpoint = require_record::<S, CheckpointManifest>(self.store, checkpoint_id)?;
        if checkpoint.id() != checkpoint_id
            || checkpoint.genesis != heads.genesis
            || checkpoint.publication_revision >= heads.publication_revision
        {
            return Err(JournalStoreError::Corrupt);
        }
        let proof_index = require_record::<S, TransitionProofIndexManifest>(
            self.store,
            checkpoint.transition_proofs,
        )?;
        if proof_index.genesis != heads.genesis || proof_index.id() != checkpoint.transition_proofs
        {
            return Err(JournalStoreError::Corrupt);
        }
        let Some(root) = proof_index.retired_root() else {
            return Ok(None);
        };
        let Some(retired_key) = transition_proof_retirement_for_invocation(
            self.store,
            heads.genesis,
            Some(root),
            key.invocation,
        )?
        else {
            return Ok(None);
        };
        AuthenticatedTransitionRetirement::new(
            retired_key,
            crate::agent_sdk::Hash(*checkpoint.id().as_bytes()),
            checkpoint.publication_revision,
        )
        .map(Some)
        .ok_or(JournalStoreError::Corrupt)
    }
}

fn map_transition_proof_index_error(
    error: super::transition_proof_journal::TransitionProofIndexError,
) -> JournalStoreError {
    use super::transition_proof_journal::TransitionProofIndexError;
    match error {
        TransitionProofIndexError::Invalid => JournalStoreError::Corrupt,
        TransitionProofIndexError::Missing | TransitionProofIndexError::Conflict => {
            JournalStoreError::Conflict
        }
        TransitionProofIndexError::Capacity => JournalStoreError::Backpressure,
    }
}

fn require_transition_proof_blob<S: AgentJournalStore>(
    store: &S,
    reference: &BlobRef,
) -> Result<Vec<u8>, JournalStoreError> {
    store
        .load_blob(JournalBlobClass::TransitionProof, reference)?
        .ok_or(JournalStoreError::MissingObject)
}

fn validate_transition_proof_anchor<S: AgentJournalStore>(
    reader: &TransitionProofClosureReader<'_, S>,
    proof: &JournalTransitionProof,
    predecessor: &JournalHeads,
    input: &ReplayInput,
) -> Result<(), JournalStoreError> {
    match proof.anchor() {
        TransitionProofAnchor::Ordered {
            entry,
            index,
            merge_frontier,
            merge_seal,
        } => {
            let retained = reader.require_record::<OrderedEntry>(entry)?;
            if retained.genesis != proof.genesis()
                || retained.input.id() != proof.input()
                || &retained.input != input
                || retained.index != index
                || retained.parent != predecessor.ordered_head
                || predecessor.ordered_index.checked_add(1) != Some(index)
                || retained.merge_frontier != merge_frontier
                || retained.merge_seal != merge_seal
            {
                return Err(JournalStoreError::Corrupt);
            }
        }
        TransitionProofAnchor::Local {
            entry,
            node,
            revision,
            ordered_base,
            merge_frontier,
        } => {
            let retained = reader.require_record::<LocalEntry>(entry)?;
            if retained.genesis != proof.genesis()
                || retained.input.id() != proof.input()
                || &retained.input != input
                || retained.node != node
                || node != predecessor.node
                || retained.revision != revision
                || retained.parent != predecessor.local_head
                || predecessor.local_revision.checked_add(1) != Some(revision)
                || retained.ordered_base != ordered_base
                || ordered_base != ordered_base_from_heads(predecessor)
                || retained.merge_frontier != merge_frontier
                || merge_frontier != predecessor.merge_frontier
            {
                return Err(JournalStoreError::Corrupt);
            }
        }
        TransitionProofAnchor::Merge {
            event,
            causal_height,
            ordered_base,
        } => {
            let retained = reader.require_record::<MergeEvent>(event)?;
            if retained.genesis != proof.genesis()
                || retained.input.id() != proof.input()
                || &retained.input != input
                || retained.causal_height != causal_height
                || retained.ordered_base != ordered_base
                || ordered_base.index > predecessor.ordered_index
            {
                return Err(JournalStoreError::Corrupt);
            }
        }
    }
    Ok(())
}

fn ordered_base_from_heads(heads: &JournalHeads) -> OrderedBase {
    OrderedBase {
        index: heads.ordered_index,
        head: heads.ordered_head,
    }
}

fn validate_transition_proof_work(
    input: &ReplayInput,
    proof: &JournalTransitionProof,
    canonical_work: &[u8],
    canonical_transition: &[u8],
) -> Result<(), JournalStoreError> {
    let decoded_work = crate::agent_sdk::RuntimeWork::decode(canonical_work)
        .map_err(|_| JournalStoreError::Corrupt)?;
    if decoded_work
        .encode()
        .map_err(|_| JournalStoreError::Corrupt)?
        != canonical_work
    {
        return Err(JournalStoreError::Corrupt);
    }
    let (context, work) = match (&input.operation, &decoded_work) {
        (
            ReplayOperation::CleanInvoke {
                context,
                work,
                authorization,
                observed_slot,
            },
            crate::agent_sdk::RuntimeWork::Invoke {
                context: exact_context,
                invocation,
                authorization: exact_authorization,
                observed_slot: exact_slot,
                ..
            },
        ) if context == exact_context
            && work == invocation.as_ref()
            && authorization == exact_authorization.as_ref()
            && observed_slot == exact_slot =>
        {
            (*context, work)
        }
        (
            ReplayOperation::CleanResume {
                context,
                work,
                yielded,
                ..
            },
            crate::agent_sdk::RuntimeWork::Resume {
                context: exact_context,
                resume,
                ..
            },
        ) if context == exact_context
            && resume.invocation == yielded.invocation
            && resume.actor == yielded.actor
            && resume.incarnation == yielded.incarnation
            && resume.deployment == yielded.deployment
            && resume.program == yielded.program
            && resume.mode == yielded.mode
            && resume.continuation == yielded.continuation
            && resume.ready_sequence == yielded.ready_sequence
            && resume.installation_data == yielded.installation_data
            && resume.availability == work.availability
            && resume.input.is_none() =>
        {
            (*context, work)
        }
        _ => return Err(JournalStoreError::Corrupt),
    };
    let crate::agent_sdk::RuntimeExecutionContext::Attested { proof_system } = context else {
        return Err(JournalStoreError::Corrupt);
    };
    let statement = &proof.proof_record().statement;
    let subject = &statement.subject;
    if statement.proof_system != proof_system
        || statement.work
            != crate::agent_sdk::proof::TransitionProofStatement::work_commitment(canonical_work)
        || statement.transition
            != crate::agent_sdk::proof::TransitionProofStatement::transition_commitment(
                canonical_transition,
            )
        || subject.space != work.space
        || subject.agent != work.agent
        || subject.runtime_deployment != work.runtime_deployment
        || subject.actor != work.actor
        || subject.incarnation != work.incarnation
        || subject.actor_deployment != work.deployment
        || subject.actor_program != work.program
        || subject.invocation != work.invocation
        || subject.mode != work.mode
        || subject.space.0 != input.runtime.space.0
        || subject.agent.0 != input.runtime.agent.0
        || subject.runtime_deployment.0 != input.runtime.deployment.0
        || subject.runtime_program.0 != input.runtime.program.0
        || service_proof_blob(&subject.runtime_package) != input.runtime.package
    {
        return Err(JournalStoreError::Corrupt);
    }
    let decoded_transition = crate::agent_sdk::RuntimeTransition::decode(canonical_transition)
        .map_err(|_| JournalStoreError::Corrupt)?;
    if decoded_transition
        .encode()
        .map_err(|_| JournalStoreError::Corrupt)?
        != canonical_transition
    {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(())
}

/// One proof may consume every independently bounded public payload, but an
/// authenticated index must not multiply those maxima by its record count.
/// This budget counts unique physical blob identities across the complete
/// closure; the index separately charges proof material logically per record.
const MAX_TRANSITION_PROOF_CLOSURE_REFERENCED_BYTES: u64 = MAX_TRANSITION_PROOF_INDEX_MATERIAL_BYTES
    + MAX_ARTIFACT_CLOSURE_REFERENCED_BYTES
    + crate::agent_sdk::wire::MAX_RUNTIME_WORK_WIRE_BYTES as u64
    + crate::agent_sdk::wire::MAX_RUNTIME_TRANSITION_WIRE_BYTES as u64
    + crate::agent_sdk::proof::MAX_TRANSITION_PROOF_MATERIAL_MANIFEST_BYTES as u64;
/// Complete unique encoded-read allowance for one proof-index authentication.
/// It admits one proof at every current payload/object maximum plus one full
/// retirement-history path, while preventing small authenticated references
/// from turning closure validation into an unbounded number of store reads.
const MAX_TRANSITION_PROOF_CLOSURE_READ_BYTES: u64 = 160 * 1024 * 1024;
const MAX_TRANSITION_PROOF_CLOSURE_FETCHES: usize = 64 * 1024;

type ProofClosureObjectKey = (JournalStorageClass, [u8; 32]);
type ProofClosureBlobKey = (JournalBlobClass, Hash, u64);

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct TransitionProofClosureReadReport {
    bytes: u64,
    fetches: usize,
    referenced_bytes: u64,
    catalog_bytes: u64,
    catalog_references: usize,
}

#[derive(Default)]
struct TransitionProofClosureReadState {
    report: TransitionProofClosureReadReport,
    objects: BTreeMap<ProofClosureObjectKey, Arc<dyn Any + Send + Sync>>,
    blobs: BTreeMap<ProofClosureBlobKey, Arc<[u8]>>,
    history_nodes: BTreeMap<InvocationHistoryNodeId, Arc<[u8]>>,
    referenced: BTreeSet<ProofClosureBlobKey>,
    catalog: BTreeSet<(Hash, u64)>,
}

impl TransitionProofClosureReadState {
    fn remaining_read_work(&self) -> Result<(u64, usize), JournalStoreError> {
        let bytes = MAX_TRANSITION_PROOF_CLOSURE_READ_BYTES
            .checked_sub(self.report.bytes)
            .ok_or(JournalStoreError::LimitExceeded)?;
        let fetches = MAX_TRANSITION_PROOF_CLOSURE_FETCHES
            .checked_sub(self.report.fetches)
            .ok_or(JournalStoreError::LimitExceeded)?;
        Ok((bytes, fetches))
    }

    fn charge_read(&mut self, bytes: u64, fetches: usize) -> Result<(), JournalStoreError> {
        let next_bytes = self
            .report
            .bytes
            .checked_add(bytes)
            .ok_or(JournalStoreError::LimitExceeded)?;
        let next_fetches = self
            .report
            .fetches
            .checked_add(fetches)
            .ok_or(JournalStoreError::LimitExceeded)?;
        if next_bytes > MAX_TRANSITION_PROOF_CLOSURE_READ_BYTES
            || next_fetches > MAX_TRANSITION_PROOF_CLOSURE_FETCHES
        {
            return Err(JournalStoreError::LimitExceeded);
        }
        self.report.bytes = next_bytes;
        self.report.fetches = next_fetches;
        Ok(())
    }

    fn reference(
        &mut self,
        class: JournalBlobClass,
        reference: &BlobRef,
    ) -> Result<(), JournalStoreError> {
        let key = (class, reference.hash, reference.len);
        if self.referenced.insert(key) {
            self.report.referenced_bytes = self
                .report
                .referenced_bytes
                .checked_add(reference.len)
                .ok_or(JournalStoreError::LimitExceeded)?;
            if self.report.referenced_bytes > MAX_TRANSITION_PROOF_CLOSURE_REFERENCED_BYTES {
                return Err(JournalStoreError::LimitExceeded);
            }
        }
        if class == JournalBlobClass::CatalogArtifact
            && self.catalog.insert((reference.hash, reference.len))
        {
            self.report.catalog_references += 1;
            self.report.catalog_bytes = self
                .report
                .catalog_bytes
                .checked_add(reference.len)
                .ok_or(JournalStoreError::LimitExceeded)?;
            if self.report.catalog_references > MAX_ARTIFACT_CLOSURE_ENTRIES
                || self.report.catalog_bytes > MAX_ARTIFACT_CLOSURE_REFERENCED_BYTES
            {
                return Err(JournalStoreError::LimitExceeded);
            }
        }
        Ok(())
    }
}

/// Ephemeral authenticated reader for one proof-index traversal. Cached
/// values never outlive the head validation which established their root.
struct TransitionProofClosureReader<'store, S> {
    store: &'store S,
    state: RefCell<TransitionProofClosureReadState>,
}

impl<'store, S: AgentJournalStore> TransitionProofClosureReader<'store, S> {
    fn new(store: &'store S) -> Self {
        Self {
            store,
            state: RefCell::new(TransitionProofClosureReadState::default()),
        }
    }

    fn report(&self) -> TransitionProofClosureReadReport {
        self.state.borrow().report
    }

    fn require_record<R>(&self, id: R::Id) -> Result<Arc<R>, JournalStoreError>
    where
        R: CanonicalJournalRecord + Any + Send + Sync,
    {
        self.require_record_with(id, |max_bytes, max_fetches| {
            self.store
                .get_with_work_limit::<R>(id, max_bytes, max_fetches)
        })
    }

    fn historical_heads(&self, id: JournalHeadsId) -> Result<Arc<JournalHeads>, JournalStoreError> {
        self.require_record_with(id, |max_bytes, max_fetches| {
            self.store
                .historical_heads_with_work_limit(id, max_bytes, max_fetches)
        })
    }

    fn require_record_with<R>(
        &self,
        id: R::Id,
        load: impl FnOnce(u64, usize) -> Result<(Option<R>, u64, usize), JournalStoreError>,
    ) -> Result<Arc<R>, JournalStoreError>
    where
        R: CanonicalJournalRecord + Any + Send + Sync,
    {
        let key = (R::STORAGE_CLASS, *id.as_bytes());
        if let Some(cached) = self.state.borrow().objects.get(&key).cloned() {
            return Arc::downcast::<R>(cached).map_err(|_| JournalStoreError::Corrupt);
        }

        let (max_bytes, max_fetches) = self.state.borrow().remaining_read_work()?;
        let (record, bytes, fetches) = load(max_bytes, max_fetches)?;
        self.state.borrow_mut().charge_read(bytes, fetches)?;
        let record = record.ok_or(JournalStoreError::MissingObject)?;
        if record.id() != id || record.validate().is_err() {
            return Err(JournalStoreError::Corrupt);
        }
        let record = Arc::new(record);
        self.state.borrow_mut().objects.insert(key, record.clone());
        Ok(record)
    }

    fn require_blob(
        &self,
        class: JournalBlobClass,
        reference: &BlobRef,
    ) -> Result<Arc<[u8]>, JournalStoreError> {
        validate_blob_reference(class, reference)?;
        let key = (class, reference.hash, reference.len);
        if let Some(cached) = self.state.borrow().blobs.get(&key).cloned() {
            return Ok(cached);
        }

        {
            let mut state = self.state.borrow_mut();
            state.reference(class, reference)?;
        }
        let (max_bytes, max_fetches) = self.state.borrow().remaining_read_work()?;
        let (bytes, read_bytes, fetches) =
            self.store
                .load_blob_with_work_limit(class, reference, max_bytes, max_fetches)?;
        self.state.borrow_mut().charge_read(read_bytes, fetches)?;
        let bytes = bytes.ok_or(JournalStoreError::MissingObject)?;
        if !reference.matches(&bytes) {
            return Err(JournalStoreError::Corrupt);
        }
        let bytes: Arc<[u8]> = bytes.into();
        self.state.borrow_mut().blobs.insert(key, bytes.clone());
        Ok(bytes)
    }
}

impl<S: AgentJournalStore> InvocationHistoryStore for TransitionProofClosureReader<'_, S> {
    type Error = JournalStoreError;

    fn load_history_node(
        &self,
        id: InvocationHistoryNodeId,
    ) -> Result<Option<Vec<u8>>, Self::Error> {
        if let Some(cached) = self.state.borrow().history_nodes.get(&id).cloned() {
            return Ok(Some(cached.as_ref().to_vec()));
        }
        let (max_bytes, max_fetches) = self.state.borrow().remaining_read_work()?;
        let (bytes, read_bytes, fetches) =
            self.store
                .load_history_node_with_work_limit(id, max_bytes, max_fetches)?;
        self.state.borrow_mut().charge_read(read_bytes, fetches)?;
        let Some(bytes) = bytes else {
            return Ok(None);
        };
        let node = InvocationHistoryNode::decode(&bytes).map_err(|_| JournalStoreError::Corrupt)?;
        if node.id() != id || node.encode() != bytes {
            return Err(JournalStoreError::Corrupt);
        }
        let bytes: Arc<[u8]> = bytes.into();
        self.state
            .borrow_mut()
            .history_nodes
            .insert(id, bytes.clone());
        Ok(Some(bytes.as_ref().to_vec()))
    }
}

fn validate_transition_proof_index_closure<S: AgentJournalStore>(
    store: &S,
    index_id: super::journal::TransitionProofIndexId,
    heads: &JournalHeads,
) -> Result<TransitionProofIndexManifest, JournalStoreError> {
    validate_transition_proof_index_closure_with_report(store, index_id, heads)
        .map(|(index, _)| index)
}

fn validate_transition_proof_index_closure_with_report<S: AgentJournalStore>(
    store: &S,
    index_id: super::journal::TransitionProofIndexId,
    heads: &JournalHeads,
) -> Result<
    (
        TransitionProofIndexManifest,
        TransitionProofClosureReadReport,
    ),
    JournalStoreError,
> {
    let reader = TransitionProofClosureReader::new(store);
    let index = reader.require_record::<TransitionProofIndexManifest>(index_id)?;
    if index.genesis != heads.genesis {
        return Err(JournalStoreError::Corrupt);
    }
    validate_transition_proof_retirement_history(&reader, &index)?;
    for entry in index.entries() {
        let proof = reader.require_record::<JournalTransitionProof>(entry.record)?;
        if proof.genesis() != heads.genesis
            || TransitionProofIndexEntry::for_record(&proof)
                .map_err(|_| JournalStoreError::Corrupt)?
                != *entry
        {
            return Err(JournalStoreError::Corrupt);
        }
        let predecessor = reader.historical_heads(proof.predecessor())?;
        if predecessor.id() != proof.predecessor()
            || predecessor.genesis != heads.genesis
            || predecessor.admission != heads.admission
            || predecessor.node != heads.node
            || predecessor.publication_revision >= heads.publication_revision
        {
            return Err(JournalStoreError::Corrupt);
        }
        let input = reader.require_record::<ReplayInput>(proof.input())?;
        validate_transition_proof_anchor(&reader, &proof, &predecessor, &input)?;
        let canonical_work =
            reader.require_blob(JournalBlobClass::TransitionProof, proof.canonical_work())?;
        let canonical_transition = reader.require_blob(
            JournalBlobClass::TransitionProof,
            proof.canonical_transition(),
        )?;
        validate_transition_proof_work(&input, &proof, &canonical_work, &canonical_transition)?;

        let manifest_reference = service_proof_blob(&proof.proof_record().proof);
        let manifest =
            reader.require_blob(JournalBlobClass::TransitionProof, &manifest_reference)?;
        if manifest.as_ref() != proof.proof_manifest_wire() {
            return Err(JournalStoreError::Corrupt);
        }
        for chunk in &proof.proof_manifest().chunks {
            reader.require_blob(
                JournalBlobClass::TransitionProof,
                &service_proof_blob(chunk),
            )?;
        }
        let closure = reader.require_record::<ArtifactClosure>(proof.artifacts())?;
        if closure.genesis != heads.genesis
            || !closure.artifacts.contains(&input.runtime.package)
            || !closure.artifacts.contains(proof.actor_package())
        {
            return Err(JournalStoreError::Corrupt);
        }
        for reference in &closure.artifacts {
            reader.require_blob(JournalBlobClass::CatalogArtifact, reference)?;
        }
    }
    let report = reader.report();
    let index = Arc::unwrap_or_clone(index);
    Ok((index, report))
}

fn validate_invocation_index<S: AgentJournalStore>(
    store: &S,
    id: InvocationIndexId,
    genesis: super::journal::AgentJournalGenesisId,
    scope: InvocationOwnershipScope,
) -> Result<InvocationIndexManifest, JournalStoreError> {
    let manifest = require_record::<S, InvocationIndexManifest>(store, id)?;
    if manifest.genesis != genesis || manifest.scope != scope {
        return Err(JournalStoreError::Corrupt);
    }
    validate_manifest_root(store, id, &manifest).map_err(map_invocation_index_error)?;
    Ok(manifest)
}

fn map_invocation_index_error(error: InvocationIndexError<JournalStoreError>) -> JournalStoreError {
    match error {
        InvocationIndexError::Storage(error) => error,
        InvocationIndexError::MissingManifest(_)
        | InvocationIndexError::MissingNode(_)
        | InvocationIndexError::MissingHistoryNode(_)
        | InvocationIndexError::MissingOutcome(_) => JournalStoreError::MissingObject,
        InvocationIndexError::PathLimit
        | InvocationIndexError::NodeLimit
        | InvocationIndexError::Capacity => JournalStoreError::LimitExceeded,
        InvocationIndexError::CorruptManifest
        | InvocationIndexError::CorruptNode(_)
        | InvocationIndexError::CorruptHistoryNode(_)
        | InvocationIndexError::CorruptOutcome(_)
        | InvocationIndexError::CorruptHistory
        | InvocationIndexError::GenesisMismatch
        | InvocationIndexError::ScopeMismatch
        | InvocationIndexError::SummaryMismatch
        | InvocationIndexError::NonCanonicalTree
        | InvocationIndexError::Cycle
        | InvocationIndexError::SharedNode
        | InvocationIndexError::ObjectCollision
        | InvocationIndexError::StoreViolation
        | InvocationIndexError::Conflict
        | InvocationIndexError::InvalidTransition => JournalStoreError::Corrupt,
    }
}

fn map_invocation_history_error(
    error: InvocationHistoryError<JournalStoreError>,
) -> JournalStoreError {
    match error {
        InvocationHistoryError::Storage(error) => error,
        InvocationHistoryError::MissingNode(_) => JournalStoreError::MissingObject,
        InvocationHistoryError::PathLimit
        | InvocationHistoryError::NodeLimit
        | InvocationHistoryError::PlanLimit => JournalStoreError::LimitExceeded,
        InvocationHistoryError::CorruptNode(_)
        | InvocationHistoryError::GenesisMismatch
        | InvocationHistoryError::ScopeMismatch
        | InvocationHistoryError::SummaryMismatch
        | InvocationHistoryError::NonCanonicalTree
        | InvocationHistoryError::Cycle
        | InvocationHistoryError::ObjectCollision(_)
        | InvocationHistoryError::Conflict
        | InvocationHistoryError::InvalidFact
        | InvocationHistoryError::InvalidPlan => JournalStoreError::Corrupt,
    }
}

/// Authenticate the retirement-history root and prove that its permanent
/// tombstones are disjoint from the current live projection.
///
/// Retirement history is cumulative and intentionally has no protocol-wide
/// cardinality ceiling. The root carries an authenticated tree-wide purpose;
/// each membership check below follows at most one 256-bit Patricia path.
/// Superseded path nodes are handled by the exact history-retirement queue,
/// independently of ordinary object sweeping.
fn validate_transition_proof_retirement_history<
    S: InvocationHistoryStore<Error = JournalStoreError>,
>(
    store: &S,
    index: &TransitionProofIndexManifest,
) -> Result<(), JournalStoreError> {
    let Some(root) = index.retired_root() else {
        return Ok(());
    };
    let history = InvocationHistory::open(
        store,
        index.genesis,
        InvocationOwnershipScope::Ordered,
        Some(root),
    )
    .map_err(map_invocation_history_error)?;
    history
        .require_history_purpose(true)
        .map_err(map_invocation_history_error)?;
    for key in index.live_entries() {
        if transition_proof_key_is_retired(store, index.genesis, Some(root), *key)? {
            return Err(JournalStoreError::Corrupt);
        }
    }
    Ok(())
}

fn validate_checkpoint_closure<S: AgentJournalStore>(
    store: &S,
    checkpoint: &CheckpointManifest,
) -> Result<(), JournalStoreError> {
    validate_checkpoint_closure_with_availability(store, checkpoint, None)
}

fn validate_checkpoint_closure_with_availability<S: AgentJournalStore>(
    store: &S,
    checkpoint: &CheckpointManifest,
    availability: Option<&ExternalCheckpointValidation<'_>>,
) -> Result<(), JournalStoreError> {
    let _ = availability;
    let genesis = store.genesis()?.ok_or(JournalStoreError::NotInitialized)?;
    if genesis.id() != checkpoint.genesis
        || genesis.admission != checkpoint.admission
        || checkpoint.runtime.space != genesis.runtime().space
        || checkpoint.runtime.agent != genesis.runtime().agent
    {
        return Err(JournalStoreError::Corrupt);
    }
    validate_invocation_index(
        store,
        checkpoint.ordered_invocations,
        checkpoint.genesis,
        InvocationOwnershipScope::Ordered,
    )?;
    validate_invocation_index(
        store,
        checkpoint.merge_invocations,
        checkpoint.genesis,
        InvocationOwnershipScope::Merge,
    )?;
    let transition_proofs =
        require_record::<S, TransitionProofIndexManifest>(store, checkpoint.transition_proofs)?;
    if transition_proofs.genesis != checkpoint.genesis {
        return Err(JournalStoreError::Corrupt);
    }
    validate_transition_proof_retirement_history(store, &transition_proofs)?;
    validate_merge_fence_structure(
        store,
        checkpoint.genesis,
        checkpoint.merge_fence,
        checkpoint.merge_seal,
        Some(checkpoint.id()),
        availability,
    )?;
    let closure = require_record::<S, ArtifactClosure>(store, checkpoint.artifacts)?;
    if closure.genesis != checkpoint.genesis
        || !closure
            .artifacts
            .iter()
            .any(|artifact| artifact == &checkpoint.runtime.package)
    {
        return Err(JournalStoreError::Corrupt);
    }
    validate_artifact_closure(store, checkpoint.artifacts, checkpoint.genesis)?;
    if checkpoint.lanes.len() != 4
        || [
            PersistedLane::Control,
            PersistedLane::Linear,
            PersistedLane::Merge,
            PersistedLane::Local,
        ]
        .into_iter()
        .any(|required| {
            checkpoint
                .lanes
                .iter()
                .filter(|lane| lane.lane == required)
                .count()
                != 1
        })
    {
        return Err(JournalStoreError::Corrupt);
    }
    for lane in &checkpoint.lanes {
        let manifest = {
            #[cfg(feature = "experimental-state-blocks")]
            if availability.is_some_and(|proof| {
                proof.permits_lane(store.instance_id(), checkpoint.id(), lane.state)
            }) {
                validate_lane_state_record(store, lane.state)?
            } else {
                validate_lane_state(store, lane.state)?
            }
            #[cfg(not(feature = "experimental-state-blocks"))]
            validate_lane_state(store, lane.state)?
        };
        if manifest.genesis != checkpoint.genesis
            || manifest.runtime != checkpoint.runtime
            || manifest.lane != lane.lane
        {
            return Err(JournalStoreError::Corrupt);
        }
        match (&lane.lane, &lane.node, &manifest.cursor) {
            (
                PersistedLane::Control | PersistedLane::Linear,
                None,
                LaneCursor::Ordered { base },
            ) if base.index == checkpoint.ordered_index && base.head == checkpoint.ordered_head => {
            }
            (PersistedLane::Merge, None, LaneCursor::Merge { frontier })
                if *frontier == checkpoint.merge_frontier => {}
            (PersistedLane::Local, Some(expected_node), LaneCursor::Local { node, .. })
                if node == expected_node => {}
            _ => return Err(JournalStoreError::Corrupt),
        }
        if let Some(index) = lane.invocations {
            validate_invocation_index(
                store,
                index,
                checkpoint.genesis,
                InvocationOwnershipScope::Local(lane.node.ok_or(JournalStoreError::Corrupt)?),
            )?;
        }
    }
    Ok(())
}

#[cfg(test)]
fn validate_checkpoint_publication<S: AgentJournalStore>(
    store: &S,
    current: &JournalHeads,
    next_transition_proofs: TransitionProofIndexId,
    checkpoint: &CheckpointManifest,
) -> Result<(), JournalStoreError> {
    validate_checkpoint_publication_with_availability(
        store,
        current,
        next_transition_proofs,
        checkpoint,
        None,
    )
}

fn validate_checkpoint_publication_with_availability<S: AgentJournalStore>(
    store: &S,
    current: &JournalHeads,
    next_transition_proofs: TransitionProofIndexId,
    checkpoint: &CheckpointManifest,
    availability: Option<&ExternalCheckpointValidation<'_>>,
) -> Result<(), JournalStoreError> {
    if checkpoint.runtime != current.runtime
        || checkpoint.ordered_invocations != current.ordered_invocations
        || checkpoint.merge_invocations != current.merge_invocations
        || checkpoint.transition_proofs != next_transition_proofs
        || checkpoint
            .lanes
            .iter()
            .any(|lane| lane.lane == PersistedLane::Local && lane.node != Some(current.node))
    {
        return Err(JournalStoreError::NonCanonical);
    }
    let local_lane = checkpoint
        .lanes
        .iter()
        .find(|lane| lane.lane == PersistedLane::Local && lane.node == Some(current.node))
        .ok_or(JournalStoreError::NonCanonical)?;
    let manifest = require_record::<S, LaneStateManifest>(store, local_lane.state)?;
    if local_lane.invocations != Some(current.local_invocations)
        || !matches!(
            manifest.cursor,
            LaneCursor::Local { node, revision, head }
                if node == current.node
                    && revision == current.local_revision
                    && head == current.local_head
        )
    {
        return Err(JournalStoreError::NonCanonical);
    }
    validate_checkpoint_closure_with_availability(store, checkpoint, availability)?;
    Ok(())
}

pub(crate) fn validate_gc_limits(limits: GcLimits) -> Result<(), JournalStoreError> {
    if limits.max_marked_objects == 0
        || limits.max_marked_blobs == 0
        || limits.max_scanned_files == 0
        || limits.max_scanned_bytes == 0
        || limits.max_unlinks_per_run == 0
    {
        return Err(JournalStoreError::LimitExceeded);
    }
    Ok(())
}

fn fresh_gc_checkpoint<S: AgentJournalStore>(
    store: &S,
    expected_heads: JournalHeadsId,
) -> Result<(JournalHeads, CheckpointManifest), JournalStoreError> {
    fresh_gc_checkpoint_with_availability(store, expected_heads, None)
}

fn fresh_gc_checkpoint_with_availability<S: AgentJournalStore>(
    store: &S,
    expected_heads: JournalHeadsId,
    availability: Option<&ExternalCheckpointValidation<'_>>,
) -> Result<(JournalHeads, CheckpointManifest), JournalStoreError> {
    let heads = store.heads()?.ok_or(JournalStoreError::NotInitialized)?;
    if heads.id() != expected_heads {
        return Err(JournalStoreError::Conflict);
    }
    let checkpoint_id = heads.checkpoint.ok_or(JournalStoreError::Conflict)?;
    let checkpoint = require_record::<S, CheckpointManifest>(store, checkpoint_id)?;
    let next_revision = checkpoint
        .publication_revision
        .checked_add(1)
        .ok_or(JournalStoreError::LimitExceeded)?;
    if checkpoint.id() != checkpoint_id
        || next_revision != heads.publication_revision
        || checkpoint.genesis != heads.genesis
        || checkpoint.admission != heads.admission
        || checkpoint.runtime != heads.runtime
        || checkpoint.ordered_head != heads.ordered_head
        || checkpoint.ordered_index != heads.ordered_index
        || checkpoint.merge_frontier != heads.merge_frontier
        || checkpoint.merge_fence != heads.merge_fence
        || checkpoint.merge_seal != heads.merge_seal
        || checkpoint.ordered_invocations != heads.ordered_invocations
        || checkpoint.merge_invocations != heads.merge_invocations
        || checkpoint.transition_proofs != heads.transition_proofs
    {
        return Err(JournalStoreError::Conflict);
    }
    let local = checkpoint
        .lanes
        .iter()
        .find(|lane| lane.lane == PersistedLane::Local)
        .ok_or(JournalStoreError::Corrupt)?;
    let local_state = require_record::<S, LaneStateManifest>(store, local.state)?;
    if local.node != Some(heads.node)
        || local.invocations != Some(heads.local_invocations)
        || !matches!(
            local_state.cursor,
            LaneCursor::Local { node, revision, head }
                if node == heads.node
                    && revision == heads.local_revision
                    && head == heads.local_head
        )
    {
        return Err(JournalStoreError::Conflict);
    }
    for lane in &checkpoint.lanes {
        let state = require_record::<S, LaneStateManifest>(store, lane.state)?;
        let exact_cursor = match (&lane.lane, &state.cursor) {
            (PersistedLane::Control | PersistedLane::Linear, LaneCursor::Ordered { base }) => {
                base.index == heads.ordered_index && base.head == heads.ordered_head
            }
            (PersistedLane::Merge, LaneCursor::Merge { frontier }) => {
                *frontier == heads.merge_frontier
            }
            (
                PersistedLane::Local,
                LaneCursor::Local {
                    node,
                    revision,
                    head,
                },
            ) => {
                *node == heads.node
                    && *revision == heads.local_revision
                    && *head == heads.local_head
            }
            _ => false,
        };
        if !exact_cursor {
            return Err(JournalStoreError::Conflict);
        }
    }
    validate_checkpoint_closure_with_availability(store, &checkpoint, availability)?;
    validate_head_targets_with_availability(store, &heads, availability)?;
    Ok((heads, checkpoint))
}

fn mark_catalog_blob<S: AgentJournalStore>(
    store: &S,
    mark: &mut GcMark,
    reference: &BlobRef,
) -> Result<(), JournalStoreError> {
    require_blob(store, JournalBlobClass::CatalogArtifact, reference)?;
    mark.blob(JournalBlobClass::CatalogArtifact, reference)
}

fn mark_transition_proof_index<S: AgentJournalStore>(
    store: &S,
    mark: &mut GcMark,
    id: super::journal::TransitionProofIndexId,
    heads: &JournalHeads,
) -> Result<(), JournalStoreError> {
    let index = validate_transition_proof_index_closure(store, id, heads)?;
    mark.object::<TransitionProofIndexManifest>(id)?;
    for entry in index.entries() {
        let proof = require_record::<S, JournalTransitionProof>(store, entry.record)?;
        mark.object::<JournalTransitionProof>(entry.record)?;
        mark.object::<ReplayInput>(proof.input())?;
        mark.object::<JournalHeads>(proof.predecessor())?;
        match proof.anchor() {
            TransitionProofAnchor::Ordered { entry, .. } => {
                mark.object::<OrderedEntry>(entry)?;
            }
            TransitionProofAnchor::Local { entry, .. } => {
                mark.object::<LocalEntry>(entry)?;
            }
            TransitionProofAnchor::Merge { event, .. } => {
                mark.object::<MergeEvent>(event)?;
            }
        }

        mark.blob(JournalBlobClass::TransitionProof, proof.canonical_work())?;
        mark.blob(
            JournalBlobClass::TransitionProof,
            proof.canonical_transition(),
        )?;
        mark.blob(
            JournalBlobClass::TransitionProof,
            &service_proof_blob(&proof.proof_record().proof),
        )?;
        for chunk in &proof.proof_manifest().chunks {
            mark.blob(
                JournalBlobClass::TransitionProof,
                &service_proof_blob(chunk),
            )?;
        }

        let artifacts = require_record::<S, ArtifactClosure>(store, proof.artifacts())?;
        mark.object::<ArtifactClosure>(proof.artifacts())?;
        for artifact in &artifacts.artifacts {
            mark_catalog_blob(store, mark, artifact)?;
        }
    }
    Ok(())
}

fn mark_lane_state<S: AgentJournalStore>(
    store: &S,
    mark: &mut GcMark,
    id: LaneStateId,
) -> Result<LaneStateManifest, JournalStoreError> {
    let state = validate_lane_state_record(store, id)?;
    #[cfg(feature = "experimental-state-blocks")]
    if let Some(root) = &state.external_root {
        mark_external_state_root(store, mark, &state, root)?;
        mark_catalog_blob(store, mark, &root.runtime.package)?;
    }
    mark.object::<LaneStateManifest>(id)?;
    mark.blob(JournalBlobClass::LaneState, &state.state)?;
    mark_catalog_blob(store, mark, &state.runtime.package)?;
    Ok(state)
}

/// Maintenance-only closure traversal. Normal publication must establish
/// incremental availability, not pay for this audit on every request.
#[cfg(feature = "experimental-state-blocks")]
fn mark_external_state_root<S: AgentJournalStore>(
    store: &S,
    mark: &mut GcMark,
    manifest: &LaneStateManifest,
    provenance: &super::journal::ExternalStateRoot,
) -> Result<(), JournalStoreError> {
    use super::state_block_store::{JournalBlockReader, journal_root_context};
    use crate::agent_sdk::{
        state_blocks::{BlockError, BlockRef, MAX_STATE_BLOCK_BYTES, ReadBudget},
        state_tree::{BlockReader, TreeError},
    };
    let genesis = store.genesis()?.ok_or(JournalStoreError::NotInitialized)?;
    if manifest.genesis != genesis.id() {
        return Err(JournalStoreError::ScopeMismatch);
    }
    let node = match manifest.cursor {
        LaneCursor::Local { node, .. } => Some(node),
        _ => None,
    };
    let context = journal_root_context(
        &genesis,
        &provenance.runtime,
        manifest.lane,
        node,
        &provenance.cursor,
    )
    .map_err(|_| JournalStoreError::ScopeMismatch)?;
    let root = provenance.descriptor;
    if root.context() != context {
        return Err(JournalStoreError::ScopeMismatch);
    }
    // The descriptor commitment is selected by this content-identified lane
    // manifest, not by bytes encountered during traversal.
    let tree = root
        .bind(context, root.commitment())
        .map_err(|_| JournalStoreError::Corrupt)?;
    // One node can reference at most 16 value chunks. Count repeated chunk
    // visits too, while marking unique blobs only once. The graph traversal's
    // own bounded frontier and these work limits prevent unbounded auditing.
    let visits = mark
        .max_blobs
        .checked_mul(17)
        .and_then(|n| u32::try_from(n).ok())
        .ok_or(JournalStoreError::LimitExceeded)?;
    let mut budget = ReadBudget::new(visits, u64::from(visits) * MAX_STATE_BLOCK_BYTES as u64);
    struct MarkingReader<'a, S> {
        inner: JournalBlockReader<'a, S>,
        mark: &'a mut GcMark,
        failure: Option<JournalStoreError>,
    }
    impl<S: AgentJournalStore> BlockReader for MarkingReader<'_, S> {
        fn read(&mut self, reference: BlockRef, output: &mut [u8]) -> Result<bool, TreeError> {
            let sdk = reference.storage_reference();
            let blob = BlobRef {
                hash: Hash(sdk.hash.0),
                len: sdk.len,
            };
            if let Err(error) = self.mark.blob(JournalBlobClass::StateBlock, &blob) {
                self.failure = Some(error);
                return Err(TreeError::Storage);
            }
            self.inner.read(reference, output)
        }
    }
    let mut reader = MarkingReader {
        inner: JournalBlockReader {
            store,
            scope: context.scope(),
        },
        mark,
        failure: None,
    };
    tree.audit(&mut reader, &mut budget).map_err(|error| {
        reader.failure.unwrap_or(match error {
            TreeError::Block(BlockError::BudgetExceeded) => JournalStoreError::LimitExceeded,
            TreeError::Block(BlockError::Unavailable) => JournalStoreError::MissingObject,
            TreeError::Storage => JournalStoreError::Unavailable,
            _ => JournalStoreError::Corrupt,
        })
    })?;
    Ok(())
}

fn mark_merge_frontier_tips<S: AgentJournalStore>(
    store: &S,
    mark: &mut GcMark,
    genesis: super::journal::AgentJournalGenesisId,
    id: MergeFrontierId,
) -> Result<MergeFrontier, JournalStoreError> {
    let frontier = require_record::<S, MergeFrontier>(store, id)?;
    if frontier.genesis != genesis {
        return Err(JournalStoreError::Corrupt);
    }
    mark.object::<MergeFrontier>(id)?;
    for event_id in &frontier.events {
        let event = require_record::<S, MergeEvent>(store, *event_id)?;
        if event.genesis != genesis {
            return Err(JournalStoreError::Corrupt);
        }
        mark.object::<MergeEvent>(*event_id)?;
        mark_catalog_blob(store, mark, &event.input.runtime.package)?;
    }
    Ok(frontier)
}

fn mark_outcome_anchor<S: AgentJournalStore>(
    store: &S,
    mark: &mut GcMark,
    outcome: &InvocationOutcomeRecord,
) -> Result<(), JournalStoreError> {
    match outcome.anchor {
        InvocationOutcomeAnchor::Ordered { entry } => {
            let entry = require_record::<S, OrderedEntry>(store, entry)?;
            if entry.genesis != outcome.genesis
                || outcome.validate_for(&entry.input).is_err()
                || outcome.key.scope != InvocationOwnershipScope::Ordered
            {
                return Err(JournalStoreError::Corrupt);
            }
            mark.object::<OrderedEntry>(entry.id())?;
            mark_catalog_blob(store, mark, &entry.input.runtime.package)?;
        }
        InvocationOutcomeAnchor::Local { entry } => {
            let entry = require_record::<S, LocalEntry>(store, entry)?;
            let InvocationOwnershipScope::Local(node) = outcome.key.scope else {
                return Err(JournalStoreError::Corrupt);
            };
            if entry.genesis != outcome.genesis
                || entry.node != node
                || outcome.validate_for(&entry.input).is_err()
            {
                return Err(JournalStoreError::Corrupt);
            }
            mark.object::<LocalEntry>(entry.id())?;
            mark_catalog_blob(store, mark, &entry.input.runtime.package)?;
        }
        InvocationOutcomeAnchor::Merge {
            source_event,
            finalizing_entry,
            seal,
        } => {
            let source = require_record::<S, MergeEvent>(store, source_event)?;
            let finalizing = require_record::<S, OrderedEntry>(store, finalizing_entry)?;
            let sealed = require_record::<S, MergeSeal>(store, seal)?;
            let expected_base = OrderedBase {
                index: finalizing
                    .index
                    .checked_sub(1)
                    .ok_or(JournalStoreError::Corrupt)?,
                head: finalizing.parent,
            };
            if outcome.key.scope != InvocationOwnershipScope::Merge
                || source.genesis != outcome.genesis
                || finalizing.genesis != outcome.genesis
                || sealed.genesis != outcome.genesis
                || outcome.validate_for(&source.input).is_err()
                || finalizing.merge_seal != Some(seal)
                || sealed.frontier != finalizing.merge_frontier
                || sealed.ordered_base != expected_base
            {
                return Err(JournalStoreError::Corrupt);
            }
            mark.object::<MergeEvent>(source_event)?;
            mark.object::<OrderedEntry>(finalizing_entry)?;
            mark.object::<MergeSeal>(seal)?;
            mark_catalog_blob(store, mark, &source.input.runtime.package)?;
            mark_catalog_blob(store, mark, &finalizing.input.runtime.package)?;
        }
    }
    Ok(())
}

fn mark_invocation_index<S: AgentJournalStore>(
    store: &S,
    mark: &mut GcMark,
    id: InvocationIndexId,
    genesis: super::journal::AgentJournalGenesisId,
    scope: InvocationOwnershipScope,
    max_nodes: usize,
) -> Result<(), JournalStoreError> {
    let manifest = require_record::<S, InvocationIndexManifest>(store, id)?;
    if manifest.genesis != genesis || manifest.scope != scope {
        return Err(JournalStoreError::Corrupt);
    }
    let reachable = collect_manifest_reachability(store, id, &manifest, max_nodes)
        .map_err(map_invocation_index_error)?;
    mark.object::<InvocationIndexManifest>(id)?;
    for node in reachable.nodes {
        mark.object::<InvocationIndexNode>(node)?;
    }
    for id in reachable.outcomes {
        let outcome = require_record::<S, InvocationOutcomeRecord>(store, id)?;
        if outcome.genesis != genesis {
            return Err(JournalStoreError::Corrupt);
        }
        mark_outcome_anchor(store, mark, &outcome)?;
        mark.object::<InvocationOutcomeRecord>(id)?;
    }
    Ok(())
}

fn build_gc_mark<S: AgentJournalStore>(
    store: &S,
    expected_heads: JournalHeadsId,
    limits: GcLimits,
) -> Result<(GcIntent, GcMark), JournalStoreError> {
    build_gc_mark_with_availability(store, expected_heads, limits, None)
}

fn build_gc_mark_with_availability<S: AgentJournalStore>(
    store: &S,
    expected_heads: JournalHeadsId,
    limits: GcLimits,
    availability: Option<&ExternalCheckpointValidation<'_>>,
) -> Result<(GcIntent, GcMark), JournalStoreError> {
    validate_gc_limits(limits)?;
    let (heads, checkpoint) =
        fresh_gc_checkpoint_with_availability(store, expected_heads, availability)?;
    let mut mark = GcMark::new(limits);
    mark.object::<CheckpointManifest>(checkpoint.id())?;

    let genesis = store.genesis()?.ok_or(JournalStoreError::NotInitialized)?;
    mark_catalog_blob(store, &mut mark, &genesis.runtime().package)?;
    mark_catalog_blob(store, &mut mark, &heads.runtime.package)?;

    let artifacts = require_record::<S, ArtifactClosure>(store, checkpoint.artifacts)?;
    if artifacts.genesis != heads.genesis {
        return Err(JournalStoreError::Corrupt);
    }
    mark.object::<ArtifactClosure>(checkpoint.artifacts)?;
    for artifact in &artifacts.artifacts {
        mark_catalog_blob(store, &mut mark, artifact)?;
    }
    for lane in &checkpoint.lanes {
        mark_lane_state(store, &mut mark, lane.state)?;
    }

    if let Some(id) = heads.ordered_head {
        let entry = require_record::<S, OrderedEntry>(store, id)?;
        if entry.genesis != heads.genesis || entry.index != heads.ordered_index {
            return Err(JournalStoreError::Corrupt);
        }
        mark.object::<OrderedEntry>(id)?;
        mark_catalog_blob(store, &mut mark, &entry.input.runtime.package)?;
    }
    if let Some(id) = heads.local_head {
        let entry = require_record::<S, LocalEntry>(store, id)?;
        if entry.genesis != heads.genesis
            || entry.node != heads.node
            || entry.revision != heads.local_revision
        {
            return Err(JournalStoreError::Corrupt);
        }
        mark.object::<LocalEntry>(id)?;
        mark_catalog_blob(store, &mut mark, &entry.input.runtime.package)?;
    }
    mark_merge_frontier_tips(store, &mut mark, heads.genesis, heads.merge_frontier)?;
    if heads.merge_fence != OrderedBase::post_genesis() {
        let fence = heads.merge_fence.head.ok_or(JournalStoreError::Corrupt)?;
        let entry = require_record::<S, OrderedEntry>(store, fence)?;
        let seal_id = heads.merge_seal.ok_or(JournalStoreError::Corrupt)?;
        let seal = require_record::<S, MergeSeal>(store, seal_id)?;
        if entry.genesis != heads.genesis
            || entry.index != heads.merge_fence.index
            || entry.merge_seal != Some(seal_id)
            || seal.genesis != heads.genesis
        {
            return Err(JournalStoreError::Corrupt);
        }
        mark.object::<OrderedEntry>(fence)?;
        mark.object::<MergeSeal>(seal_id)?;
        mark_catalog_blob(store, &mut mark, &entry.input.runtime.package)?;
        mark_merge_frontier_tips(store, &mut mark, heads.genesis, seal.frontier)?;
        mark_lane_state(store, &mut mark, seal.merge_state)?;
    }

    mark_invocation_index(
        store,
        &mut mark,
        heads.ordered_invocations,
        heads.genesis,
        InvocationOwnershipScope::Ordered,
        limits.max_index_nodes,
    )?;
    mark_invocation_index(
        store,
        &mut mark,
        heads.merge_invocations,
        heads.genesis,
        InvocationOwnershipScope::Merge,
        limits.max_index_nodes,
    )?;
    mark_invocation_index(
        store,
        &mut mark,
        heads.local_invocations,
        heads.genesis,
        InvocationOwnershipScope::Local(heads.node),
        limits.max_index_nodes,
    )?;

    // A fresh checkpoint and its successor currently share the compacted
    // proof root, but mark both explicitly so a later wire generation may
    // separate checkpoint history from the live projection without silently
    // weakening collection reachability.
    mark_transition_proof_index(store, &mut mark, checkpoint.transition_proofs, &heads)?;
    mark_transition_proof_index(store, &mut mark, heads.transition_proofs, &heads)?;
    if let Some(previous) = heads.previous {
        store
            .historical_heads(previous)?
            .ok_or(JournalStoreError::MissingObject)?;
        mark.object::<JournalHeads>(previous)?;
    }

    Ok((
        GcIntent {
            heads: expected_heads,
            checkpoint: checkpoint.id(),
        },
        mark,
    ))
}

fn mark_portable_history_tree<S: AgentJournalStore>(
    store: &S,
    mark: &mut GcMark,
    root: Option<InvocationHistoryNodeId>,
    genesis: AgentJournalGenesisId,
    scope: InvocationOwnershipScope,
    maximum: usize,
) -> Result<(), JournalStoreError> {
    let Some(root) = root else {
        return Ok(());
    };
    let mut pending = vec![root];
    let mut visited = BTreeSet::new();
    while let Some(id) = pending.pop() {
        if !visited.insert(id) {
            continue;
        }
        if visited.len() > maximum {
            return Err(JournalStoreError::LimitExceeded);
        }
        let bytes = InvocationHistoryStore::load_history_node(store, id)?
            .ok_or(JournalStoreError::MissingObject)?;
        let node = decode_object::<InvocationHistoryNode>(&bytes, id)?;
        if node.genesis() != genesis || node.scope() != scope {
            return Err(JournalStoreError::Corrupt);
        }
        mark.object::<InvocationHistoryNode>(id)?;
        if let Some((left, right)) = node.child_ids() {
            pending.push(right);
            pending.push(left);
        }
    }
    Ok(())
}

fn mark_portable_history<S: AgentJournalStore>(
    store: &S,
    heads: &JournalHeads,
    mark: &mut GcMark,
    maximum: usize,
) -> Result<(), JournalStoreError> {
    for (id, scope) in [
        (heads.ordered_invocations, InvocationOwnershipScope::Ordered),
        (heads.merge_invocations, InvocationOwnershipScope::Merge),
        (
            heads.local_invocations,
            InvocationOwnershipScope::Local(heads.node),
        ),
    ] {
        let manifest = require_record::<S, InvocationIndexManifest>(store, id)?;
        if manifest.genesis != heads.genesis || manifest.scope != scope {
            return Err(JournalStoreError::Corrupt);
        }
        mark_portable_history_tree(
            store,
            mark,
            manifest.history_root,
            heads.genesis,
            scope,
            maximum,
        )?;
    }
    let proofs = require_record::<S, TransitionProofIndexManifest>(store, heads.transition_proofs)?;
    if proofs.genesis != heads.genesis {
        return Err(JournalStoreError::Corrupt);
    }
    mark_portable_history_tree(
        store,
        mark,
        proofs.retired_root(),
        heads.genesis,
        InvocationOwnershipScope::Ordered,
        maximum,
    )
}

fn read_portable_object<S: AgentJournalStore>(
    store: &S,
    class: JournalStorageClass,
    id: [u8; 32],
) -> Result<PortableJournalObject, JournalStoreError> {
    macro_rules! load {
        ($record:ty, $id:expr) => {{
            let record = store
                .get::<$record>($id)?
                .ok_or(JournalStoreError::MissingObject)?;
            record.encode()
        }};
    }
    let bytes = match class {
        JournalStorageClass::ReplayInput => load!(ReplayInput, super::journal::ReplayInputId(id)),
        JournalStorageClass::Genesis => return Err(JournalStoreError::InvalidClass),
        JournalStorageClass::OrderedEntry => load!(OrderedEntry, OrderedEntryId(id)),
        JournalStorageClass::LocalEntry => load!(LocalEntry, LocalEntryId(id)),
        JournalStorageClass::MergeEvent => load!(MergeEvent, MergeEventId(id)),
        JournalStorageClass::MergeFrontier => load!(MergeFrontier, MergeFrontierId(id)),
        JournalStorageClass::MergeSeal => load!(MergeSeal, MergeSealId(id)),
        JournalStorageClass::LaneState => load!(LaneStateManifest, LaneStateId(id)),
        JournalStorageClass::ArtifactClosure => {
            load!(ArtifactClosure, super::journal::ArtifactClosureId(id))
        }
        JournalStorageClass::InvocationIndex => {
            load!(InvocationIndexManifest, InvocationIndexId(id))
        }
        JournalStorageClass::InvocationIndexNode => {
            load!(InvocationIndexNode, InvocationIndexNodeId(id))
        }
        JournalStorageClass::Checkpoint => load!(CheckpointManifest, CheckpointId(id)),
        JournalStorageClass::Heads => store
            .historical_heads(JournalHeadsId(id))?
            .ok_or(JournalStoreError::MissingObject)?
            .encode(),
        JournalStorageClass::InvocationOutcome => {
            load!(InvocationOutcomeRecord, InvocationOutcomeId(id))
        }
        JournalStorageClass::InvocationHistoryNode => {
            let history_id = InvocationHistoryNodeId(id);
            let bytes = InvocationHistoryStore::load_history_node(store, history_id)?
                .ok_or(JournalStoreError::MissingObject)?;
            decode_object::<InvocationHistoryNode>(&bytes, history_id)?;
            bytes
        }
        JournalStorageClass::TransitionProof => load!(
            JournalTransitionProof,
            super::journal::TransitionProofEntryId(id)
        ),
        JournalStorageClass::TransitionProofIndex => {
            load!(TransitionProofIndexManifest, TransitionProofIndexId(id))
        }
    };
    let object = PortableJournalObject { class, id, bytes };
    validate_portable_object(&object)?;
    Ok(object)
}

/// Detached maintenance export under one exclusive, freshly audited store
/// borrow. The archive carries storage integrity and source metadata only;
/// it does not convey common-checkpoint authority or publish destination heads.
/// Object/blob/history quotas bound the ID-only mark independently of the
/// external-root read budget and the encoded wire-byte ceiling.
#[cfg(all(target_os = "linux", feature = "experimental-state-blocks"))]
pub(crate) fn export_external_journal_checkpoint<S: AgentJournalStore, W: std::io::Write>(
    store: &mut S,
    genesis: &super::replay::ReplaySealedExternalGenesis,
    expected_heads: JournalHeadsId,
    limits: ExternalArchiveLimits,
    budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    output: &mut W,
) -> Result<ExternalArchiveReport, JournalStoreError> {
    limits.validate()?;
    let heads = store.heads()?.ok_or(JournalStoreError::NotInitialized)?;
    if heads.id() != expected_heads {
        return Err(JournalStoreError::Conflict);
    }
    super::replay::with_external_genesis_checkpoint_heads(
        store,
        &heads,
        genesis,
        budget,
        |store, availability| {
            let (_, mut mark) = build_gc_mark_with_availability(
                store,
                expected_heads,
                GcLimits {
                    max_index_nodes: limits.max_objects,
                    max_marked_objects: limits.max_objects,
                    max_marked_blobs: limits.max_blobs,
                    max_scanned_files: 1,
                    max_scanned_bytes: 1,
                    max_unlinks_per_run: 1,
                },
                availability,
            )?;
            mark_portable_history(store, &heads, &mut mark, limits.max_history_nodes)?;
            external_archive::write_marked_external_archive(
                store,
                &heads,
                &mark,
                availability,
                output,
                limits,
            )
        },
    )
}

pub(crate) fn export_portable_journal_checkpoint<S: AgentJournalStore>(
    store: &S,
    limits: PortableJournalLimits,
) -> Result<PortableJournalCheckpoint, JournalStoreError> {
    validate_portable_journal_limits(limits)?;
    let heads = store.heads()?.ok_or(JournalStoreError::NotInitialized)?;
    let (_, mut mark) = build_gc_mark(
        store,
        heads.id(),
        GcLimits {
            max_index_nodes: limits.max_index_nodes,
            max_marked_objects: limits.max_objects,
            max_marked_blobs: limits.max_blobs,
            max_scanned_files: 1,
            max_scanned_bytes: 1,
            max_unlinks_per_run: 1,
        },
    )?;
    mark_portable_history(store, &heads, &mut mark, limits.max_index_nodes)?;

    let mut objects = Vec::new();
    objects
        .try_reserve_exact(mark.objects.len())
        .map_err(|_| JournalStoreError::LimitExceeded)?;
    for (class, id) in mark.objects.iter().copied() {
        objects.push(read_portable_object(store, class, id)?);
    }
    let mut blobs = Vec::new();
    blobs
        .try_reserve_exact(mark.blobs.len())
        .map_err(|_| JournalStoreError::LimitExceeded)?;
    for ((class, hash), len) in &mark.blobs {
        let reference = BlobRef {
            hash: *hash,
            len: *len,
        };
        let bytes = store
            .load_blob(*class, &reference)?
            .ok_or(JournalStoreError::MissingObject)?;
        blobs.push(PortableJournalBlob {
            class: *class,
            reference,
            bytes,
        });
    }
    let image = PortableJournalCheckpoint {
        heads,
        objects,
        blobs,
    };
    image.validate_shape()?;
    image.validate_limits(limits)?;
    Ok(image)
}

fn validate_portable_journal_limits(
    limits: PortableJournalLimits,
) -> Result<(), JournalStoreError> {
    if limits.max_objects == 0
        || limits.max_objects > MAX_PORTABLE_JOURNAL_OBJECTS
        || limits.max_blobs == 0
        || limits.max_blobs > MAX_PORTABLE_JOURNAL_BLOBS
        || limits.max_index_nodes == 0
        || limits.max_bytes == 0
        || limits.max_bytes > MAX_PORTABLE_JOURNAL_IMAGE_BYTES as u64
    {
        return Err(JournalStoreError::LimitExceeded);
    }
    Ok(())
}

fn portable_image_key_sets(
    image: &PortableJournalCheckpoint,
) -> (
    BTreeSet<(JournalStorageClass, [u8; 32])>,
    BTreeMap<(JournalBlobClass, Hash), u64>,
) {
    (
        image
            .objects
            .iter()
            .map(|object| (object.class, object.id))
            .collect(),
        image
            .blobs
            .iter()
            .map(|blob| ((blob.class, blob.reference.hash), blob.reference.len))
            .collect(),
    )
}

fn validate_portable_journal_closure<S: AgentJournalStore>(
    store: &S,
    image: &PortableJournalCheckpoint,
    maximum_index_nodes: usize,
) -> Result<(), JournalStoreError> {
    image.validate_shape()?;
    let heads = store.heads()?.ok_or(JournalStoreError::NotInitialized)?;
    if heads != image.heads {
        return Err(JournalStoreError::Conflict);
    }
    let (_, mut mark) = build_gc_mark(
        store,
        heads.id(),
        GcLimits {
            max_index_nodes: maximum_index_nodes,
            max_marked_objects: image.objects.len(),
            max_marked_blobs: image.blobs.len(),
            max_scanned_files: 1,
            max_scanned_bytes: 1,
            max_unlinks_per_run: 1,
        },
    )?;
    mark_portable_history(store, &heads, &mut mark, maximum_index_nodes)?;
    let (objects, blobs) = portable_image_key_sets(image);
    if objects != mark.objects || blobs != mark.blobs {
        return Err(JournalStoreError::NonCanonical);
    }
    Ok(())
}

fn validate_history_retirement_coverage<S: AgentJournalStore>(
    store: &S,
    expected_heads: JournalHeadsId,
    queue: &HistoryRetirementQueue,
) -> Result<(), JournalStoreError> {
    queue.validate()?;
    if queue.records.is_empty() {
        return Ok(());
    }
    let (heads, checkpoint) = fresh_gc_checkpoint(store, expected_heads)?;
    if queue.genesis != heads.genesis || queue.node != heads.node {
        return Err(JournalStoreError::Corrupt);
    }
    let roots = history_roots_for_heads(store, &heads)?;
    let tail = queue.records.last().ok_or(JournalStoreError::Corrupt)?;
    if tail.next_roots != roots
        || queue
            .records
            .iter()
            .any(|record| record.publication_revision > checkpoint.publication_revision)
    {
        return Err(JournalStoreError::Conflict);
    }
    Ok(())
}

fn ordered_base_is_ancestor<S: AgentJournalStore>(
    store: &S,
    genesis: super::journal::AgentJournalGenesisId,
    ordered_head: Option<super::journal::OrderedEntryId>,
    ordered_index: u64,
    target: OrderedBase,
) -> Result<bool, JournalStoreError> {
    target.validate().map_err(supplied_decode_error)?;
    if target.index > ordered_index {
        return Ok(false);
    }
    let mut id = ordered_head;
    let mut index = ordered_index;
    let mut entries = 0_usize;
    let mut bytes = 0_usize;
    loop {
        if index == target.index {
            return Ok(id == target.head);
        }
        let current_id = id.ok_or(JournalStoreError::Corrupt)?;
        let entry = require_record::<S, OrderedEntry>(store, current_id)?;
        if entry.genesis != genesis || entry.index != index {
            return Err(JournalStoreError::Corrupt);
        }
        entries = entries
            .checked_add(1)
            .ok_or(JournalStoreError::LimitExceeded)?;
        bytes = bytes
            .checked_add(entry.encode().len())
            .ok_or(JournalStoreError::LimitExceeded)?;
        if entries > MAX_REPLAY_SUFFIX_ENTRIES || bytes > MAX_REPLAY_SUFFIX_BYTES {
            return Err(JournalStoreError::LimitExceeded);
        }
        id = entry.parent;
        index = index.checked_sub(1).ok_or(JournalStoreError::Corrupt)?;
    }
}

fn local_base_is_ancestor<S: AgentJournalStore>(
    store: &S,
    genesis: super::journal::AgentJournalGenesisId,
    node: NodeId,
    local_head: Option<LocalEntryId>,
    local_revision: u64,
    target_head: Option<LocalEntryId>,
    target_revision: u64,
) -> Result<bool, JournalStoreError> {
    if target_revision > local_revision
        || (target_revision == 0) != target_head.is_none()
        || target_head == Some(LocalEntryId::ZERO)
    {
        return Ok(false);
    }
    let mut id = local_head;
    let mut revision = local_revision;
    let mut entries = 0_usize;
    let mut bytes = 0_usize;
    loop {
        if revision == target_revision {
            return Ok(id == target_head);
        }
        let current_id = id.ok_or(JournalStoreError::Corrupt)?;
        let entry = require_record::<S, LocalEntry>(store, current_id)?;
        if entry.genesis != genesis || entry.node != node || entry.revision != revision {
            return Err(JournalStoreError::Corrupt);
        }
        entries = entries
            .checked_add(1)
            .ok_or(JournalStoreError::LimitExceeded)?;
        bytes = bytes
            .checked_add(entry.encode().len())
            .ok_or(JournalStoreError::LimitExceeded)?;
        if entries > MAX_REPLAY_SUFFIX_ENTRIES || bytes > MAX_REPLAY_SUFFIX_BYTES {
            return Err(JournalStoreError::LimitExceeded);
        }
        id = entry.parent;
        revision = revision.checked_sub(1).ok_or(JournalStoreError::Corrupt)?;
    }
}

#[derive(Debug)]
struct ValidatedMergeDag {
    events: BTreeMap<MergeEventId, MergeEvent>,
    /// Authenticated retained tips at which parent traversal stops. Their
    /// heights were checked before compaction and are therefore inputs to the
    /// retained suffix, not claims reconstructed from possibly-pruned parents.
    boundary: BTreeSet<MergeEventId>,
}

impl ValidatedMergeDag {
    fn ancestors_of(
        &self,
        roots: &[MergeEventId],
    ) -> Result<BTreeSet<MergeEventId>, JournalStoreError> {
        let mut ancestors = BTreeSet::new();
        let mut stack = Vec::new();
        for root in roots {
            let event = self.events.get(root).ok_or(JournalStoreError::Corrupt)?;
            if !self.boundary.contains(root) {
                stack.extend(event.parents.iter().copied());
            }
        }
        while let Some(id) = stack.pop() {
            if !ancestors.insert(id) {
                continue;
            }
            if self.boundary.contains(&id) {
                continue;
            }
            let event = self.events.get(&id).ok_or(JournalStoreError::Corrupt)?;
            stack.extend(event.parents.iter().copied());
        }
        Ok(ancestors)
    }

    fn canonical_frontier(
        &self,
        candidates: &[MergeEventId],
    ) -> Result<Vec<MergeEventId>, JournalStoreError> {
        let ancestors = self.ancestors_of(candidates)?;
        let mut frontier = candidates
            .iter()
            .copied()
            .filter(|candidate| !ancestors.contains(candidate))
            .collect::<Vec<_>>();
        frontier.sort_unstable();
        frontier.dedup();
        Ok(frontier)
    }

    fn contains_at_or_below(
        &self,
        roots: &[MergeEventId],
        target: MergeEventId,
    ) -> Result<bool, JournalStoreError> {
        Ok(roots.contains(&target) || self.ancestors_of(roots)?.contains(&target))
    }

    fn every_path_attaches_to(
        &self,
        root: MergeEventId,
        retained: &ValidatedMergeDag,
    ) -> Result<bool, JournalStoreError> {
        let mut seen = BTreeSet::new();
        let mut stack = vec![root];
        while let Some(id) = stack.pop() {
            if retained.events.contains_key(&id) || !seen.insert(id) {
                continue;
            }
            let event = self.events.get(&id).ok_or(JournalStoreError::Corrupt)?;
            if event.parents.is_empty() {
                return Ok(false);
            }
            stack.extend(event.parents.iter().copied());
        }
        Ok(true)
    }
}

fn load_validated_merge_dag<S: AgentJournalStore>(
    store: &S,
    genesis: super::journal::AgentJournalGenesisId,
    roots: &[MergeEventId],
    boundary: &BTreeSet<MergeEventId>,
) -> Result<ValidatedMergeDag, JournalStoreError> {
    let mut events = BTreeMap::new();
    let mut stack = roots.to_vec();
    let mut bytes = 0_usize;
    while let Some(id) = stack.pop() {
        if events.contains_key(&id) {
            continue;
        }
        let event = require_record::<S, MergeEvent>(store, id)?;
        if event.genesis != genesis {
            return Err(JournalStoreError::Corrupt);
        }
        bytes = bytes
            .checked_add(event.encode().len())
            .ok_or(JournalStoreError::LimitExceeded)?;
        if events.len() >= MAX_REPLAY_SUFFIX_ENTRIES || bytes > MAX_REPLAY_SUFFIX_BYTES {
            return Err(JournalStoreError::LimitExceeded);
        }
        if !boundary.contains(&id) {
            stack.extend(event.parents.iter().copied());
        }
        events.insert(id, event);
    }
    if !boundary.iter().all(|id| events.contains_key(id)) {
        return Err(JournalStoreError::Corrupt);
    }
    for (id, event) in &events {
        if boundary.contains(id) {
            continue;
        }
        let expected_height = if event.parents.is_empty() {
            1
        } else {
            event
                .parents
                .iter()
                .map(|parent| {
                    events
                        .get(parent)
                        .map(|event| event.causal_height)
                        .ok_or(JournalStoreError::Corrupt)
                })
                .collect::<Result<Vec<_>, _>>()?
                .into_iter()
                .max()
                .ok_or(JournalStoreError::Corrupt)?
                .checked_add(1)
                .ok_or(JournalStoreError::LimitExceeded)?
        };
        if event.causal_height != expected_height {
            return Err(JournalStoreError::Corrupt);
        }
    }
    Ok(ValidatedMergeDag {
        events,
        boundary: boundary.clone(),
    })
}

fn validate_frontier<S: AgentJournalStore>(
    store: &S,
    frontier: &MergeFrontier,
    boundary: &BTreeSet<MergeEventId>,
) -> Result<ValidatedMergeDag, JournalStoreError> {
    let dag = load_validated_merge_dag(store, frontier.genesis, &frontier.events, boundary)?;
    if dag.canonical_frontier(&frontier.events)? != frontier.events {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(dag)
}

#[derive(Debug)]
struct RetainedMergeBoundary {
    tips: BTreeSet<MergeEventId>,
}

/// Resolve the proof-index image which became authoritative at one exact
/// replay boundary. A checkpoint is a direct authenticated boundary. For a
/// newer Merge fence, walk the bounded post-checkpoint heads history back to
/// the first successor carrying that fence; later publications with the same
/// fence may contain terminal facts which occur after the boundary and must
/// not be applied retroactively while replaying its retained suffix.
pub(crate) fn transition_proof_index_at_replay_boundary<S: AgentJournalStore>(
    store: &S,
    heads: &JournalHeads,
    boundary: OrderedBase,
) -> Result<TransitionProofIndexManifest, JournalStoreError> {
    if heads.validate().is_err()
        || heads.id() == JournalHeadsId::ZERO
        || boundary.validate().is_err()
        || boundary.index > heads.merge_fence.index
        || (boundary.index == heads.merge_fence.index && boundary.head != heads.merge_fence.head)
    {
        return Err(JournalStoreError::Corrupt);
    }

    let checkpoint = heads
        .checkpoint
        .map(|id| require_record::<S, CheckpointManifest>(store, id))
        .transpose()?;
    if let Some(checkpoint) = &checkpoint {
        if checkpoint.id() != heads.checkpoint.ok_or(JournalStoreError::Corrupt)?
            || checkpoint.genesis != heads.genesis
            || checkpoint.publication_revision >= heads.publication_revision
            || checkpoint.merge_fence.index > boundary.index
            || (checkpoint.merge_fence.index == boundary.index
                && checkpoint.merge_fence.head != boundary.head)
        {
            return Err(JournalStoreError::Corrupt);
        }
        if checkpoint.merge_fence == boundary {
            let index = require_record::<S, TransitionProofIndexManifest>(
                store,
                checkpoint.transition_proofs,
            )?;
            return (index.genesis == heads.genesis && index.id() == checkpoint.transition_proofs)
                .then_some(index)
                .ok_or(JournalStoreError::Corrupt);
        }
    } else if boundary == OrderedBase::post_genesis() {
        let empty = TransitionProofIndexManifest::empty(heads.genesis);
        let stored = require_record::<S, TransitionProofIndexManifest>(store, empty.id())?;
        return (stored == empty)
            .then_some(stored)
            .ok_or(JournalStoreError::Corrupt);
    }

    let minimum_revision = checkpoint
        .as_ref()
        .map(|checkpoint| checkpoint.publication_revision.saturating_add(1))
        .unwrap_or(0);
    let mut cursor = heads.clone();
    for _ in 0..=MAX_REPLAY_SUFFIX_ENTRIES.saturating_add(1) {
        if cursor.merge_fence == boundary {
            let is_first_successor = if cursor.publication_revision == minimum_revision {
                true
            } else {
                let previous_id = cursor.previous.ok_or(JournalStoreError::MissingObject)?;
                let previous = store
                    .historical_heads(previous_id)?
                    .ok_or(JournalStoreError::MissingObject)?;
                if previous.id() != previous_id
                    || previous.genesis != heads.genesis
                    || previous.admission != heads.admission
                    || previous.node != heads.node
                    || previous.publication_revision.checked_add(1)
                        != Some(cursor.publication_revision)
                {
                    return Err(JournalStoreError::Corrupt);
                }
                if previous.merge_fence == boundary {
                    cursor = previous;
                    continue;
                }
                true
            };
            if is_first_successor {
                let index = require_record::<S, TransitionProofIndexManifest>(
                    store,
                    cursor.transition_proofs,
                )?;
                return (index.genesis == heads.genesis && index.id() == cursor.transition_proofs)
                    .then_some(index)
                    .ok_or(JournalStoreError::Corrupt);
            }
        }
        if cursor.publication_revision <= minimum_revision {
            break;
        }
        let previous_id = cursor.previous.ok_or(JournalStoreError::MissingObject)?;
        let previous = store
            .historical_heads(previous_id)?
            .ok_or(JournalStoreError::MissingObject)?;
        if previous.id() != previous_id
            || previous.genesis != heads.genesis
            || previous.admission != heads.admission
            || previous.node != heads.node
            || previous.publication_revision.checked_add(1) != Some(cursor.publication_revision)
        {
            return Err(JournalStoreError::Corrupt);
        }
        cursor = previous;
    }
    Err(JournalStoreError::MissingObject)
}

fn retained_merge_boundary<S: AgentJournalStore>(
    store: &S,
    heads: &JournalHeads,
) -> Result<RetainedMergeBoundary, JournalStoreError> {
    // A checkpoint taken after the latest lifecycle fence is the newest
    // authenticated compaction boundary. If the lifecycle fence advanced
    // after that checkpoint, its retained seal is newer instead.
    let boundary_frontier = if let Some(checkpoint_id) = heads.checkpoint {
        let checkpoint = require_record::<S, CheckpointManifest>(store, checkpoint_id)?;
        if checkpoint.genesis != heads.genesis
            || checkpoint.merge_fence.index > heads.merge_fence.index
        {
            return Err(JournalStoreError::Corrupt);
        }
        if checkpoint.merge_fence == heads.merge_fence {
            Some(checkpoint.merge_frontier)
        } else {
            heads
                .merge_seal
                .map(|seal| require_record::<S, MergeSeal>(store, seal))
                .transpose()?
                .map(|seal| seal.frontier)
        }
    } else {
        heads
            .merge_seal
            .map(|seal| require_record::<S, MergeSeal>(store, seal))
            .transpose()?
            .map(|seal| seal.frontier)
    };
    let Some(frontier_id) = boundary_frontier else {
        return Ok(RetainedMergeBoundary {
            tips: BTreeSet::new(),
        });
    };
    let frontier = require_record::<S, MergeFrontier>(store, frontier_id)?;
    if frontier.genesis != heads.genesis {
        return Err(JournalStoreError::Corrupt);
    }
    // Boundary tips themselves remain immutable retained objects. Their
    // internal ancestry may already have been collected, so do not descend.
    let tips = frontier.events.iter().copied().collect::<BTreeSet<_>>();
    validate_frontier(store, &frontier, &tips)?;
    Ok(RetainedMergeBoundary { tips })
}

/// Validate the objects named by a fence, but do not confer ordered ancestry.
/// Ancestry is established by a replay-sealed publication token. On Local
/// cold recovery, the exact checkpoint named by the owned durable descriptor
/// is the transitive trust boundary; Shared mode replaces that trust step
/// with the QC committed by `FenceAncestryEvidence`.
fn validate_merge_fence_structure<S: AgentJournalStore>(
    store: &S,
    genesis: super::journal::AgentJournalGenesisId,
    fence: OrderedBase,
    seal_id: Option<super::journal::MergeSealId>,
    checkpoint: Option<CheckpointId>,
    availability: Option<&ExternalCheckpointValidation<'_>>,
) -> Result<(), JournalStoreError> {
    if fence == OrderedBase::post_genesis() {
        return if seal_id.is_none() {
            Ok(())
        } else {
            Err(JournalStoreError::Corrupt)
        };
    }
    let fence_entry =
        require_record::<S, OrderedEntry>(store, fence.head.ok_or(JournalStoreError::Corrupt)?)?;
    let seal_id = seal_id.ok_or(JournalStoreError::Corrupt)?;
    let seal = require_record::<S, MergeSeal>(store, seal_id)?;
    if fence_entry.genesis != genesis
        || fence_entry.index != fence.index
        || fence_entry.merge_seal != Some(seal_id)
        || seal.genesis != genesis
        || seal.frontier != fence_entry.merge_frontier
        || seal.ordered_base
            != (OrderedBase {
                index: fence_entry.index.saturating_sub(1),
                head: fence_entry.parent,
            })
    {
        return Err(JournalStoreError::Corrupt);
    }
    let frontier = require_record::<S, MergeFrontier>(store, seal.frontier)?;
    if frontier.genesis != genesis {
        return Err(JournalStoreError::Corrupt);
    }
    let sealed_tips = frontier.events.iter().copied().collect::<BTreeSet<_>>();
    validate_frontier(store, &frontier, &sealed_tips)?;
    let state = if availability
        .zip(checkpoint)
        .is_some_and(|(proof, checkpoint)| {
            proof.permits_lane(store.instance_id(), checkpoint, seal.merge_state)
        }) {
        validate_lane_state_record(store, seal.merge_state)?
    } else {
        validate_lane_state(store, seal.merge_state)?
    };
    #[cfg(feature = "experimental-state-blocks")]
    if state.external_root.is_some()
        && (!frontier.events.is_empty()
            || !matches!(
                fence_entry.input.operation,
                ReplayOperation::CleanManage {
                    request: crate::agent_sdk::ManagementRequest::Install(_),
                    ..
                }
            ))
    {
        return Err(JournalStoreError::Unavailable);
    }
    if state.genesis != genesis
        || state.lane != PersistedLane::Merge
        || !matches!(
            state.cursor,
            LaneCursor::Merge { frontier } if frontier == seal.frontier
        )
    {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(())
}

fn validate_head_targets<S: AgentJournalStore>(
    store: &S,
    heads: &JournalHeads,
) -> Result<(), JournalStoreError> {
    validate_head_targets_with_availability(store, heads, None)
}

pub(crate) fn validate_head_targets_with_availability<S: AgentJournalStore>(
    store: &S,
    heads: &JournalHeads,
    availability: Option<&ExternalCheckpointValidation<'_>>,
) -> Result<(), JournalStoreError> {
    if availability.is_some_and(|proof| !proof.matches_heads(store.instance_id(), heads)) {
        return Err(JournalStoreError::Conflict);
    }
    let genesis = store.genesis()?.ok_or(JournalStoreError::NotInitialized)?;
    if genesis.id() != heads.genesis
        || genesis.admission != heads.admission
        || heads.runtime.space != genesis.runtime().space
        || heads.runtime.agent != genesis.runtime().agent
        || genesis.runtime().agent == AgentId::ZERO
    {
        return Err(JournalStoreError::Corrupt);
    }
    require_blob(
        store,
        JournalBlobClass::CatalogArtifact,
        &heads.runtime.package,
    )?;
    validate_invocation_index(
        store,
        heads.ordered_invocations,
        heads.genesis,
        InvocationOwnershipScope::Ordered,
    )?;
    validate_invocation_index(
        store,
        heads.merge_invocations,
        heads.genesis,
        InvocationOwnershipScope::Merge,
    )?;
    validate_invocation_index(
        store,
        heads.local_invocations,
        heads.genesis,
        InvocationOwnershipScope::Local(heads.node),
    )?;
    validate_transition_proof_index_closure(store, heads.transition_proofs, heads)?;

    if let Some(previous) = heads.previous {
        let predecessor = store
            .historical_heads(previous)?
            .ok_or(JournalStoreError::MissingObject)?;
        if predecessor.id() != previous
            || predecessor.genesis != heads.genesis
            || predecessor.admission != heads.admission
            || predecessor.node != heads.node
            || predecessor.publication_revision.checked_add(1) != Some(heads.publication_revision)
        {
            return Err(JournalStoreError::Corrupt);
        }
    }

    validate_merge_fence_structure(
        store,
        heads.genesis,
        heads.merge_fence,
        heads.merge_seal,
        heads.checkpoint,
        availability,
    )?;
    if let Some(id) = heads.ordered_head {
        let entry = require_record::<S, OrderedEntry>(store, id)?;
        if entry.genesis != heads.genesis || entry.index != heads.ordered_index {
            return Err(JournalStoreError::Corrupt);
        }
    }
    if let Some(id) = heads.local_head {
        let entry = require_record::<S, LocalEntry>(store, id)?;
        if entry.genesis != heads.genesis
            || entry.node != heads.node
            || entry.revision != heads.local_revision
        {
            return Err(JournalStoreError::Corrupt);
        }
    }
    let (ordered_boundary, local_boundary_head, local_boundary_revision, checkpoint_covers_fence) =
        if let Some(id) = heads.checkpoint {
            let checkpoint = require_record::<S, CheckpointManifest>(store, id)?;
            if checkpoint.genesis != heads.genesis
                || checkpoint.publication_revision >= heads.publication_revision
            {
                return Err(JournalStoreError::Corrupt);
            }
            validate_checkpoint_closure_with_availability(store, &checkpoint, availability)?;
            let local = checkpoint
                .lanes
                .iter()
                .find(|lane| lane.lane == PersistedLane::Local);
            let (local_head, local_revision) = if let Some(lane) = local {
                if lane.node != Some(heads.node) {
                    return Err(JournalStoreError::Corrupt);
                }
                let state = require_record::<S, LaneStateManifest>(store, lane.state)?;
                match state.cursor {
                    LaneCursor::Local {
                        node,
                        revision,
                        head,
                    } if node == heads.node => (head, revision),
                    _ => return Err(JournalStoreError::Corrupt),
                }
            } else {
                (None, 0)
            };
            (
                OrderedBase {
                    index: checkpoint.ordered_index,
                    head: checkpoint.ordered_head,
                },
                local_head,
                local_revision,
                checkpoint.merge_fence == heads.merge_fence,
            )
        } else {
            (OrderedBase::post_genesis(), None, 0, false)
        };
    if !ordered_base_is_ancestor(
        store,
        heads.genesis,
        heads.ordered_head,
        heads.ordered_index,
        ordered_boundary,
    )? {
        return Err(JournalStoreError::Corrupt);
    }
    if !checkpoint_covers_fence
        && !ordered_base_is_ancestor(
            store,
            heads.genesis,
            heads.ordered_head,
            heads.ordered_index,
            heads.merge_fence,
        )?
    {
        return Err(JournalStoreError::Corrupt);
    }
    if !local_base_is_ancestor(
        store,
        heads.genesis,
        heads.node,
        heads.local_head,
        heads.local_revision,
        local_boundary_head,
        local_boundary_revision,
    )? {
        return Err(JournalStoreError::Corrupt);
    }
    let frontier = require_record::<S, MergeFrontier>(store, heads.merge_frontier)?;
    if frontier.genesis != heads.genesis {
        return Err(JournalStoreError::Corrupt);
    }
    if heads.publication_revision == 0
        && (!frontier.events.is_empty() || heads.merge_seal.is_some())
    {
        return Err(JournalStoreError::Corrupt);
    }
    let boundary = retained_merge_boundary(store, heads)?;
    validate_frontier(store, &frontier, &boundary.tips)?;
    Ok(())
}

fn validate_anchor_dependencies_with_availability<S, R>(
    store: &S,
    current: &JournalHeads,
    anchor: &R,
    next: &JournalHeads,
    availability: Option<&ExternalCheckpointValidation<'_>>,
) -> Result<(), JournalStoreError>
where
    S: AgentJournalStore,
    R: CanonicalJournalRecord,
{
    if availability.is_some_and(|proof| {
        !proof.matches_heads(store.instance_id(), current)
            || !proof.matches_heads(store.instance_id(), next)
    }) {
        return Err(JournalStoreError::Conflict);
    }
    if R::STORAGE_CLASS == JournalStorageClass::MergeEvent {
        let event = decode_anchor::<MergeEvent, _>(anchor)?;
        if event.ordered_base.index < current.merge_fence.index
            || event.ordered_base.index > current.ordered_index
        {
            return Err(JournalStoreError::NonCanonical);
        }
        let current_frontier = require_record::<S, MergeFrontier>(store, current.merge_frontier)?;
        let next_frontier = require_record::<S, MergeFrontier>(store, next.merge_frontier)?;
        if current_frontier.genesis != current.genesis || next_frontier.genesis != current.genesis {
            return Err(JournalStoreError::Corrupt);
        }
        let boundary = retained_merge_boundary(store, current)?;
        let current_dag = validate_frontier(store, &current_frontier, &boundary.tips)?;
        let mut candidates = current_frontier.events.clone();
        candidates.push(event.id());
        candidates.sort_unstable();
        candidates.dedup();
        let dag = load_validated_merge_dag(store, current.genesis, &candidates, &boundary.tips)?;
        if !boundary.tips.is_empty() && !dag.every_path_attaches_to(event.id(), &current_dag)? {
            // After a compacting checkpoint or lifecycle seal, every path in
            // an imported branch must terminate in the retained boundary or
            // current suffix. A still-present pre-boundary object is not proof
            // that a pruned internal parent was admissible.
            return Err(JournalStoreError::NonCanonical);
        }
        if dag.contains_at_or_below(&current_frontier.events, event.id())? {
            // An already reachable EventId is an exact no-op and must use the
            // idempotent `next == current` publication path.
            return Err(JournalStoreError::Conflict);
        }
        if dag.canonical_frontier(&candidates)? != next_frontier.events {
            return Err(JournalStoreError::NonCanonical);
        }
    } else if R::STORAGE_CLASS == JournalStorageClass::Checkpoint {
        let checkpoint = decode_anchor::<CheckpointManifest, _>(anchor)?;
        validate_checkpoint_publication_with_availability(
            store,
            current,
            next.transition_proofs,
            &checkpoint,
            availability,
        )?;
    }
    Ok(())
}

fn validate_idempotent_anchor<S, R>(
    store: &S,
    current: &JournalHeads,
    anchor: &R,
) -> Result<(), JournalStoreError>
where
    S: AgentJournalStore,
    R: CanonicalJournalRecord,
{
    let matches = match R::STORAGE_CLASS {
        JournalStorageClass::OrderedEntry => {
            Some(decode_anchor::<OrderedEntry, _>(anchor)?.id()) == current.ordered_head
        }
        JournalStorageClass::LocalEntry => {
            Some(decode_anchor::<LocalEntry, _>(anchor)?.id()) == current.local_head
        }
        JournalStorageClass::Checkpoint => {
            Some(decode_anchor::<CheckpointManifest, _>(anchor)?.id()) == current.checkpoint
        }
        JournalStorageClass::MergeEvent => {
            let event = decode_anchor::<MergeEvent, _>(anchor)?;
            let frontier = require_record::<S, MergeFrontier>(store, current.merge_frontier)?;
            let boundary = retained_merge_boundary(store, current)?;
            let dag = validate_frontier(store, &frontier, &boundary.tips)?;
            dag.contains_at_or_below(&frontier.events, event.id())?
        }
        _ => false,
    };
    if matches {
        Ok(())
    } else {
        Err(JournalStoreError::Conflict)
    }
}

fn validate_sealed_fence_ancestry<S: AgentJournalStore>(
    store: &S,
    publication: &ReplaySealedPublication,
) -> Result<(), JournalStoreError> {
    let current = store.heads()?.ok_or(JournalStoreError::NotInitialized)?;
    let next = publication.next();
    let evidence = publication.fence_ancestry();
    let canonical_head = OrderedBase {
        index: next.ordered_index,
        head: next.ordered_head,
    };
    if current.id() != publication.expected() && current != *next {
        return Err(JournalStoreError::Conflict);
    }
    if next.validate().is_err()
        || !evidence.validate()
        || evidence.genesis() != next.genesis
        || evidence.canonical_head() != canonical_head
        || evidence.fence() != next.merge_fence
        || evidence.commitment() == Hash::ZERO
    {
        return Err(JournalStoreError::NonCanonical);
    }

    match publication.anchor() {
        ReplayPublicationAnchor::Checkpoint(checkpoint) => {
            let sealed = publication
                .checkpoint_validation()
                .ok_or(JournalStoreError::NonCanonical)?;
            if sealed.fence_ancestry() != evidence
                || evidence.checkpoint_base() != canonical_head
                || checkpoint.ordered_index != canonical_head.index
                || checkpoint.ordered_head != canonical_head.head
                || checkpoint.merge_fence != evidence.fence()
            {
                return Err(JournalStoreError::NonCanonical);
            }
        }
        ReplayPublicationAnchor::Ordered(_)
        | ReplayPublicationAnchor::Local(_)
        | ReplayPublicationAnchor::Merge { .. } => {
            if publication.checkpoint_validation().is_some() {
                return Err(JournalStoreError::NonCanonical);
            }
            let replay_boundary = if let Some(checkpoint_id) = current.checkpoint {
                let checkpoint = require_record::<S, CheckpointManifest>(store, checkpoint_id)?;
                if checkpoint.id() != checkpoint_id || checkpoint.genesis != current.genesis {
                    return Err(JournalStoreError::Corrupt);
                }
                OrderedBase {
                    index: checkpoint.ordered_index,
                    head: checkpoint.ordered_head,
                }
            } else {
                OrderedBase::post_genesis()
            };
            let matches_boundary = match evidence.common_checkpoint() {
                Some(checkpoint) => current.checkpoint == Some(checkpoint)
                    && evidence.checkpoint_base().index <= replay_boundary.index,
                None => evidence.checkpoint_base() == replay_boundary,
            };
            if !matches_boundary {
                return Err(JournalStoreError::NonCanonical);
            }
        }
    }
    Ok(())
}

fn validate_shared_merge_projection(
    publication: &ReplaySealedPublication,
) -> Result<Option<&ReplaySealedSharedMergeProjection>, JournalStoreError> {
    let projection = publication.shared_merge_projection();
    match publication.mode() {
        ReplayPublicationMode::Canonical => {
            if projection.is_some() {
                return Err(JournalStoreError::NonCanonical);
            }
            Ok(None)
        }
        ReplayPublicationMode::SharedOrderedPreserveMerge
        | ReplayPublicationMode::SharedOrderedInstallFence => {
            let projection = projection.ok_or(JournalStoreError::NonCanonical)?;
            let entry = match publication.anchor() {
                ReplayPublicationAnchor::Ordered(entry) => entry,
                ReplayPublicationAnchor::Local(_)
                | ReplayPublicationAnchor::Merge { .. }
                | ReplayPublicationAnchor::Checkpoint(_) => {
                    return Err(JournalStoreError::NonCanonical);
                }
            };
            let manifest = projection.manifest();
            if entry.validate().is_err()
                || manifest.validate().is_err()
                || entry.genesis != publication.next().genesis
                || publication.next().ordered_head != Some(entry.id())
                || manifest.genesis != entry.genesis
                || manifest.runtime != entry.input.runtime
                || manifest.lane != PersistedLane::Merge
                || !matches!(
                    &manifest.cursor,
                    LaneCursor::Merge { frontier } if *frontier == entry.merge_frontier
                )
            {
                return Err(JournalStoreError::NonCanonical);
            }
            validate_supplied_blob(
                JournalBlobClass::LaneState,
                &manifest.state,
                projection.state(),
            )?;
            Ok(Some(projection))
        }
    }
}

fn validate_shared_ordered_commit(
    publication: &ReplaySealedPublication,
) -> Result<Option<SharedOrderedCommitBinding>, JournalStoreError> {
    let sealed = publication.shared_ordered_commit();
    match publication.mode() {
        ReplayPublicationMode::Canonical => {
            if sealed.is_some() {
                return Err(JournalStoreError::NonCanonical);
            }
            Ok(None)
        }
        ReplayPublicationMode::SharedOrderedPreserveMerge
        | ReplayPublicationMode::SharedOrderedInstallFence => {
            let sealed = sealed.ok_or(JournalStoreError::NonCanonical)?;
            let entry = match publication.anchor() {
                ReplayPublicationAnchor::Ordered(entry) => entry,
                ReplayPublicationAnchor::Local(_)
                | ReplayPublicationAnchor::Merge { .. }
                | ReplayPublicationAnchor::Checkpoint(_) => {
                    return Err(JournalStoreError::NonCanonical);
                }
            };
            let claim = sealed.claim();
            let projection = publication
                .shared_merge_projection()
                .ok_or(JournalStoreError::NonCanonical)?;
            let manifest = projection.manifest();
            let committed = OrderedBase {
                index: entry.index,
                head: Some(entry.id()),
            };
            if claim.validate().is_err()
                || claim.genesis() != entry.genesis
                || claim.admission().as_bytes() != publication.next().admission.as_bytes()
                || claim.ordered() != committed
                || claim.merge_frontier() != entry.merge_frontier
                || claim.merge().manifest() != manifest.id()
                || claim.merge().state() != &manifest.state
                || claim.runtime() != &publication.next().runtime
                || claim.ordered_invocations() != publication.next().ordered_invocations
                || claim.merge_fence() != publication.next().merge_fence
                || claim.merge_seal() != publication.next().merge_seal
                || sealed.raft_payload_commitment() == Hash::ZERO
            {
                return Err(JournalStoreError::NonCanonical);
            }
            SharedOrderedCommitBinding::new(
                sealed.journal_store(),
                entry.id(),
                claim.clone(),
                sealed.raft_payload_commitment(),
                publication.next().id(),
            )
            .map(Some)
            .map_err(|_| JournalStoreError::NonCanonical)
        }
    }
}

fn stage_shared_merge_projection<S: AgentJournalStore>(
    store: &mut S,
    publication: &ReplaySealedPublication,
) -> Result<bool, JournalStoreError> {
    let Some(projection) = validate_shared_merge_projection(publication)? else {
        return Ok(false);
    };
    let manifest = projection.manifest();
    let state = projection.state();

    // State bytes become durable before the immutable manifest which names
    // them. Both are read back through the store interface before any anchor
    // or successor head can be installed.
    let mut created = store.put_blob(JournalBlobClass::LaneState, &manifest.state, state)?;
    created |= store.put(manifest)?;
    if store.get::<LaneStateManifest>(manifest.id())?.as_ref() != Some(manifest)
        || store
            .load_blob(JournalBlobClass::LaneState, &manifest.state)?
            .as_deref()
            != Some(state)
    {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(created)
}

fn stage_shared_ordered_commit<S: SharedOrderedCommitStore>(
    store: &mut S,
    binding: &SharedOrderedCommitBinding,
) -> Result<bool, JournalStoreError> {
    let created = store.persist_shared_ordered_commit(binding)?;
    if store.shared_ordered_commit(binding.entry())?.as_ref() != Some(binding) {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(created)
}

/// Reproduce the real dependency-write boundary before the mutable head CAS.
#[cfg(test)]
pub(crate) fn stage_shared_binding_before_heads_for_test<S: SharedOrderedCommitStore>(
    store: &mut S,
    publication: &ReplaySealedPublication,
    include_anchor: bool,
) -> Result<(), JournalStoreError> {
    validate_shared_merge_projection(publication)?;
    let binding =
        validate_shared_ordered_commit(publication)?.ok_or(JournalStoreError::NonCanonical)?;
    stage_shared_merge_projection(store, publication)?;
    stage_shared_ordered_commit(store, &binding)?;
    if include_anchor {
        let ReplayPublicationAnchor::Ordered(entry) = publication.anchor() else {
            return Err(JournalStoreError::NonCanonical);
        };
        store.put(entry)?;
    }
    Ok(())
}

fn persist_and_read_back_authority_record<S, R>(
    store: &mut S,
    record: &R,
    load: impl Fn(&S, R::Id) -> Result<Option<R>, JournalStoreError>,
    persist: impl Fn(&mut S, &R) -> Result<(), JournalStoreError>,
) -> Result<bool, JournalStoreError>
where
    S: SystemAuthorityHistoryStore,
    R: Clone + PartialEq,
    R::Id: Copy,
    R: AuthorityRecordId,
{
    let id = record.authority_id();
    let created = load(store, id)?.is_none();
    persist(store, record)?;
    if load(store, id)?.as_ref() != Some(record) {
        return Err(JournalStoreError::Corrupt);
    }
    Ok(created)
}

trait AuthorityRecordId {
    type Id;

    fn authority_id(&self) -> Self::Id;
}

impl AuthorityRecordId for SystemAuthorityDecisionNode {
    type Id = SystemAuthorityDecisionNodeId;

    fn authority_id(&self) -> Self::Id {
        self.id()
    }
}

impl AuthorityRecordId for SystemAuthorityRotationNode {
    type Id = SystemAuthorityRotationNodeId;

    fn authority_id(&self) -> Self::Id {
        self.id()
    }
}

impl AuthorityRecordId for SystemAuthorityCatalogNode {
    type Id = SystemAuthorityCatalogNodeId;

    fn authority_id(&self) -> Self::Id {
        self.id()
    }
}

impl AuthorityRecordId for SystemAuthorityCatalogRecord {
    type Id = SystemAuthorityCatalogRecordId;

    fn authority_id(&self) -> Self::Id {
        self.id()
    }
}

impl AuthorityRecordId for SystemAuthorityCommitteeRecord {
    type Id = SystemAuthorityCommitteeId;

    fn authority_id(&self) -> Self::Id {
        self.id()
    }
}

fn validate_authority_committee_closure(
    records: &[SystemAuthorityCommitteeRecord],
) -> Result<(), JournalStoreError> {
    if records.is_empty() || records.windows(2).any(|pair| pair[0].id() >= pair[1].id()) {
        return Err(JournalStoreError::NonCanonical);
    }
    Ok(())
}

const MAX_SYSTEM_AUTHORITY_CATALOG_PATH_NODES: usize = 257;

fn catalog_outcome_matches_record(
    outcome: super::system_authority::SystemAuthorityCatalogFinalizeOutcome,
    record: &SystemAuthorityCatalogRecord,
    exact_retry: bool,
) -> bool {
    let fact = record.receipt().fact();
    outcome.operation() == record.operation_id()
        && outcome.result() == Some(fact.result().commitment())
        && outcome.catalog_head() == Some(fact.resulting_catalog_head())
        && outcome.authority_generation() == Some(fact.resulting_authority_generation())
        && outcome.sequence() == Some(fact.sequence())
        && outcome.exact_retry() == exact_retry
        && !outcome.operation_conflicted()
}

fn load_catalog_record_required<S: SystemAuthorityHistoryStore>(
    store: &S,
    id: SystemAuthorityCatalogRecordId,
) -> Result<SystemAuthorityCatalogRecord, JournalStoreError> {
    store
        .load_system_authority_catalog_record(id)?
        .ok_or(JournalStoreError::MissingObject)
}

fn prove_stored_catalog<S: SystemAuthorityHistoryStore>(
    store: &S,
    root: SystemAuthorityCatalogNodeId,
    operation: crate::service::OperationId,
) -> Result<super::system_authority::SystemAuthorityCatalogProof, JournalStoreError> {
    prove_catalog(root, operation, |id| {
        store
            .load_system_authority_catalog_node(id)
            .map(|node| node.map(|node| node.encode()))
    })
    .map_err(|_| JournalStoreError::Corrupt)
}

fn stage_system_authority_catalog_dependencies<S: SystemAuthorityHistoryStore>(
    store: &mut S,
    command: &super::system_authority::SystemAuthorityCatalogFinalize,
    record: Option<&SystemAuthorityCatalogRecord>,
    history: &super::system_authority::SystemAuthorityCatalogWritePlan,
    outcome: super::system_authority::SystemAuthorityCatalogFinalizeOutcome,
) -> Result<bool, JournalStoreError> {
    command
        .validate()
        .map_err(|_| JournalStoreError::NonCanonical)?;
    let operation = command.operation_id();
    if outcome.operation() != operation
        || history.previous_root() == SystemAuthorityCatalogNodeId::ZERO
        || history.root() == SystemAuthorityCatalogNodeId::ZERO
        || command
            .proof()
            .root()
            .map_err(|_| JournalStoreError::NonCanonical)?
            != history.previous_root()
    {
        return Err(JournalStoreError::NonCanonical);
    }

    let prior = prove_stored_catalog(store, history.previous_root(), operation)?;
    if &prior != command.proof() {
        return Err(JournalStoreError::Corrupt);
    }

    if !history.inserted() {
        if history.root() != history.previous_root()
            || !history.nodes().is_empty()
            || !history.retired_node_ids().is_empty()
        {
            return Err(JournalStoreError::NonCanonical);
        }
        let occupied = command
            .proof()
            .occupied_record_id()
            .ok_or(JournalStoreError::NonCanonical)?;
        let stored = load_catalog_record_required(store, occupied)?;
        if stored.operation_id() != operation {
            return Err(JournalStoreError::Corrupt);
        }
        return match record {
            Some(record)
                if occupied == record.id()
                    && stored == *record
                    && record.receipt() == command.receipt()
                    && catalog_outcome_matches_record(outcome, record, true) =>
            {
                Ok(false)
            }
            None if outcome.operation_conflicted()
                && outcome.occupied_record_id() == Some(occupied)
                && stored.receipt() != command.receipt() =>
            {
                Ok(false)
            }
            _ => Err(JournalStoreError::NonCanonical),
        };
    }

    let record = record.ok_or(JournalStoreError::NonCanonical)?;
    if command.proof().occupied_record_id().is_some()
        || outcome.operation_conflicted()
        || outcome.exact_retry()
        || record.receipt() != command.receipt()
        || !catalog_outcome_matches_record(outcome, record, false)
        || history.root() == history.previous_root()
        || history.nodes().len() != MAX_SYSTEM_AUTHORITY_CATALOG_PATH_NODES
        || history.retired_node_ids().len() >= MAX_SYSTEM_AUTHORITY_CATALOG_PATH_NODES
        || history
            .nodes()
            .windows(2)
            .any(|pair| pair[0].id() >= pair[1].id())
        || history.nodes().iter().any(|node| node.validate().is_err())
        || history
            .nodes()
            .iter()
            .all(|node| node.id() != history.root())
        || history
            .nodes()
            .iter()
            .all(|node| node != &SystemAuthorityCatalogNode::Leaf(record.clone()))
        || history
            .retired_node_ids()
            .windows(2)
            .any(|pair| pair[0] >= pair[1])
        || history.retired_node_ids().iter().any(|id| {
            *id == SystemAuthorityCatalogNodeId::ZERO
                || history
                    .nodes()
                    .binary_search_by_key(id, SystemAuthorityCatalogNode::id)
                    .is_ok()
        })
    {
        return Err(JournalStoreError::NonCanonical);
    }

    // Every displaced path node remains permanent audit history. Prove that
    // the write plan names only already-durable nodes before creating any
    // successor dependency.
    for id in history.retired_node_ids() {
        if store.load_system_authority_catalog_node(*id)?.is_none() {
            return Err(JournalStoreError::MissingObject);
        }
    }

    // The separately addressable receipt precedes the sparse nodes which
    // commit to its ID. This lets conflict and exact-retry recovery resolve
    // an occupied proof without scanning or trusting incoming receipt bytes.
    let mut created = persist_and_read_back_authority_record(
        store,
        record,
        SystemAuthorityHistoryStore::load_system_authority_catalog_record,
        SystemAuthorityHistoryStore::persist_system_authority_catalog_record,
    )?;
    for node in history.nodes() {
        created |= persist_and_read_back_authority_record(
            store,
            node,
            SystemAuthorityHistoryStore::load_system_authority_catalog_node,
            SystemAuthorityHistoryStore::persist_system_authority_catalog_node,
        )?;
    }

    let installed = prove_stored_catalog(store, history.root(), operation)?;
    if installed.occupied_record_id() != Some(record.id()) {
        return Err(JournalStoreError::Corrupt);
    }
    for id in history.retired_node_ids() {
        if store.load_system_authority_catalog_node(*id)?.is_none() {
            return Err(JournalStoreError::Corrupt);
        }
    }
    Ok(created)
}

fn stage_system_authority_dependencies<S: SystemAuthorityPublicationStore>(
    store: &mut S,
    publication: &ReplaySealedPublication,
    storage: &ReplaySystemAuthorityStoragePlan,
) -> Result<bool, JournalStoreError> {
    if publication.mode() != ReplayPublicationMode::Canonical
        || publication.shared_ordered_commit().is_some()
        || publication.shared_merge_projection().is_some()
        || !matches!(publication.anchor(), ReplayPublicationAnchor::Ordered(_))
    {
        return Err(JournalStoreError::NonCanonical);
    }
    let write = publication
        .system_authority_write()
        .ok_or(JournalStoreError::NonCanonical)?;
    if let (
        StandardSystemAuthorityWrite::Catalog { record, history },
        LifecycleReply::CatalogFinalized(outcome),
    ) = (write.selected(), write.result())
    {
        let ReplayPublicationAnchor::Ordered(entry) = publication.anchor() else {
            return Err(JournalStoreError::NonCanonical);
        };
        let ReplayOperation::Management {
            request: LifecycleRequest::FinalizeCatalog(command),
        } = &entry.input.operation
        else {
            return Err(JournalStoreError::NonCanonical);
        };
        let storage_history = storage
            .catalog_history()
            .ok_or(JournalStoreError::NonCanonical)?;
        let record = record.as_ref().ok_or(JournalStoreError::NonCanonical)?;
        let committee_records = storage.committee_records();
        if !history.inserted()
            || storage_history.record() != record
            || storage_history.root() != history.root()
            || committee_records.len() != 1
            || committee_records[0].id().as_bytes() != &record.receipt().certificate().committee().0
            || record
                .verify(
                    command.receipt().fact().intent().binding(),
                    committee_records[0].committee(),
                )
                .is_err()
        {
            return Err(JournalStoreError::NonCanonical);
        }
        let mut created = persist_and_read_back_authority_record(
            store,
            &committee_records[0],
            SystemAuthorityHistoryStore::load_system_authority_committee_record,
            SystemAuthorityHistoryStore::persist_system_authority_committee_record,
        )?;
        created |= stage_system_authority_catalog_dependencies(
            store,
            command,
            Some(record),
            history,
            *outcome,
        )?;
        return Ok(created);
    }
    let rotation_history = storage
        .rotation_history()
        .ok_or(JournalStoreError::NonCanonical)?;
    validate_authority_committee_closure(storage.committee_records())?;

    let mut created = false;
    let exact_retry = match (write.selected(), write.result()) {
        (
            StandardSystemAuthorityWrite::Rotation { record, history },
            LifecycleReply::SystemAuthorityRotated {
                rotation,
                epoch,
                exact_retry,
            },
        ) => {
            if record != rotation_history.record()
                || record.id() != *rotation
                || record.new_epoch() != *epoch
                || history.root() != rotation_history.root()
                || history.previous_root() == SystemAuthorityRotationNodeId::ZERO
                || history.root() == SystemAuthorityRotationNodeId::ZERO
                || history.inserted() == *exact_retry
                || *exact_retry
                || !history.inserted()
                || storage.committee_records().len() != 2
                || storage.committee_records()[0].id()
                    != record.old_committee().min(record.new_committee())
                || storage.committee_records()[1].id()
                    != record.old_committee().max(record.new_committee())
            {
                return Err(JournalStoreError::NonCanonical);
            }
            if history.nodes().is_empty()
                || history
                    .nodes()
                    .windows(2)
                    .any(|pair| pair[0].id() >= pair[1].id())
                || history
                    .nodes()
                    .iter()
                    .all(|node| node.id() != history.root())
                || history
                    .nodes()
                    .iter()
                    .all(|node| node != &SystemAuthorityRotationNode::Leaf(record.clone()))
                || history.committee_records() != storage.committee_records()
            {
                return Err(JournalStoreError::NonCanonical);
            }
            for node in history.nodes() {
                created |= persist_and_read_back_authority_record(
                    store,
                    node,
                    SystemAuthorityHistoryStore::load_system_authority_rotation_node,
                    SystemAuthorityHistoryStore::persist_system_authority_rotation_node,
                )?;
            }
            *exact_retry
        }
        _ => return Err(JournalStoreError::NonCanonical),
    };

    let ReplayPublicationAnchor::Ordered(entry) = publication.anchor() else {
        return Err(JournalStoreError::NonCanonical);
    };
    let ReplayOperation::Management {
        request: LifecycleRequest::RotateSystemAuthority(command),
    } = &entry.input.operation
    else {
        return Err(JournalStoreError::NonCanonical);
    };
    let lookup = prove_rotation(
        rotation_history.root(),
        rotation_history.record().new_epoch(),
        |id| {
            store
                .load_system_authority_rotation_node(id)
                .map(|node| node.map(|node| node.encode()))
        },
    )
    .map_err(|_| JournalStoreError::Corrupt)?;
    if lookup.occupied_record() != Some(rotation_history.record())
        || (exact_retry && lookup.proof() != command.proof())
    {
        return Err(JournalStoreError::Corrupt);
    }

    for record in storage.committee_records() {
        if exact_retry {
            if store
                .load_system_authority_committee_record(record.id())?
                .as_ref()
                != Some(record)
            {
                return Err(JournalStoreError::MissingObject);
            }
        } else {
            created |= persist_and_read_back_authority_record(
                store,
                record,
                SystemAuthorityHistoryStore::load_system_authority_committee_record,
                SystemAuthorityHistoryStore::persist_system_authority_committee_record,
            )?;
        }
    }
    Ok(created)
}

fn stage_sealed_dependencies<S: SharedOrderedCommitStore>(
    store: &mut S,
    publication: &ReplaySealedPublication,
) -> Result<bool, JournalStoreError> {
    validate_sealed_fence_ancestry(store, publication)?;
    // Validate the complete Shared authority/projection pair before either
    // immutable dependency is written. Persistence order then guarantees the
    // pinned projection and replay-derived Raft binding precede head exposure.
    validate_shared_merge_projection(publication)?;
    let shared_commit = validate_shared_ordered_commit(publication)?;
    let mut created = stage_shared_merge_projection(store, publication)?;
    if let Some(binding) = &shared_commit {
        created |= stage_shared_ordered_commit(store, binding)?;
    }
    // AJPT closure validation dereferences its exact transition anchor. Make
    // that immutable record durable before validating/staging the proof
    // index; publish_anchor will read it back idempotently immediately before
    // the sole mutable head CAS.
    created |= match publication.anchor() {
        ReplayPublicationAnchor::Ordered(entry) => store.put(entry)?,
        ReplayPublicationAnchor::Local(entry) => store.put(entry)?,
        ReplayPublicationAnchor::Merge { event, frontier } => {
            let event_created = store.put(event)?;
            let frontier_created = store.put(frontier)?;
            event_created || frontier_created
        }
        ReplayPublicationAnchor::Checkpoint(_) => false,
    };
    created |= stage_transition_proof_batch(store, publication)?;
    let mut outcome_ids = BTreeSet::new();
    for sealed in publication.outcomes() {
        let record = sealed.record();
        if !outcome_ids.insert(record.id())
            || record
                .validate_for_genesis(publication.next().genesis, sealed.input())
                .is_err()
        {
            return Err(JournalStoreError::NonCanonical);
        }
        // Exact result bytes must be immutable and readable before a
        // successor invocation-index root which references them can become
        // visible through `heads`.
        created |= store.put(record)?;
    }
    match publication.anchor() {
        ReplayPublicationAnchor::Merge { frontier, .. } => {
            if publication.checkpoint_validation().is_some()
                || frontier.id() != publication.next().merge_frontier
            {
                return Err(JournalStoreError::NonCanonical);
            }
        }
        ReplayPublicationAnchor::Checkpoint(manifest) => {
            let sealed = publication
                .checkpoint_validation()
                .ok_or(JournalStoreError::NonCanonical)?;
            if sealed.manifest() != manifest
                || sealed.artifacts().id() != manifest.artifacts
                || sealed.lanes().len() != manifest.lanes.len()
                || !sealed
                    .lanes()
                    .iter()
                    .zip(&manifest.lanes)
                    .all(|((lane, state), expected)| lane == expected && state.id() == lane.state)
            {
                return Err(JournalStoreError::NonCanonical);
            }
            for (_, state) in sealed.lanes() {
                created |= store.put(state)?;
            }
            created |= store.put(sealed.artifacts())?;
            for (id, index) in sealed.invocation_indexes() {
                if index.id() != *id {
                    return Err(JournalStoreError::NonCanonical);
                }
                created |= store.put(index)?;
            }
        }
        ReplayPublicationAnchor::Ordered(_) | ReplayPublicationAnchor::Local(_) => {
            if publication.checkpoint_validation().is_some() {
                return Err(JournalStoreError::NonCanonical);
            }
        }
    }
    Ok(created)
}

fn stage_transition_proof_batch<S: SharedOrderedCommitStore>(
    store: &mut S,
    publication: &ReplaySealedPublication,
) -> Result<bool, JournalStoreError> {
    let authoritative = store.heads()?.ok_or(JournalStoreError::NotInitialized)?;
    let next = publication.next();
    if publication.transition_proof_actions().len() > MAX_REPLAY_SUFFIX_ENTRIES {
        return Err(JournalStoreError::LimitExceeded);
    }
    let Some(batch) = publication.transition_proof_batch() else {
        if next.transition_proofs != authoritative.transition_proofs {
            return Err(JournalStoreError::NonCanonical);
        }
        if publication.transition_proof_actions().is_empty() {
            return Ok(false);
        }
        let previous = require_record::<S, TransitionProofIndexManifest>(
            store,
            authoritative.transition_proofs,
        )?;
        let (derived, retired) =
            derive_transition_proof_apply(store, publication, &authoritative, &previous, &[])?;
        return if derived == previous && retired.is_empty() {
            Ok(false)
        } else {
            Err(JournalStoreError::NonCanonical)
        };
    };
    let exact_retry = authoritative.id() == next.id();
    let predecessor = if exact_retry {
        let predecessor = store
            .historical_heads(publication.expected())?
            .ok_or(JournalStoreError::MissingObject)?;
        if predecessor.id() != publication.expected()
            || next.previous != Some(predecessor.id())
            || authoritative != *next
        {
            return Err(JournalStoreError::Corrupt);
        }
        predecessor
    } else {
        if authoritative.id() != publication.expected() {
            return Err(JournalStoreError::Conflict);
        }
        authoritative
    };
    if batch.store() != store.instance_id()
        || batch.predecessor() != publication.expected()
        || batch.previous() != predecessor.transition_proofs
        || batch.next().id() != next.transition_proofs
        || batch.next().genesis != predecessor.genesis
    {
        return Err(JournalStoreError::Conflict);
    }
    let previous = require_record::<S, TransitionProofIndexManifest>(store, batch.previous())?;
    let mut derived = previous.clone();
    let mut retired_keys = Vec::new();
    match batch.mutation() {
        StagedTransitionProofMutation::Apply => {
            if matches!(publication.anchor(), ReplayPublicationAnchor::Checkpoint(_))
                || publication.transition_proof_actions().is_empty()
            {
                return Err(JournalStoreError::NonCanonical);
            }
            (derived, retired_keys) = derive_transition_proof_apply(
                store,
                publication,
                &predecessor,
                &previous,
                batch.publications(),
            )?;
        }
        StagedTransitionProofMutation::Checkpoint => {
            if !batch.publications().is_empty()
                || !publication.transition_proof_actions().is_empty()
                || !matches!(publication.anchor(), ReplayPublicationAnchor::Checkpoint(_))
                || batch.retirement_plan().is_some()
            {
                return Err(JournalStoreError::NonCanonical);
            }
            derived = derived
                .checkpointed()
                .map_err(map_transition_proof_index_error)?;
        }
    }
    let expected_retirement_facts = missing_transition_proof_retirement_facts(
        store,
        predecessor.genesis,
        previous.retired_root(),
        &retired_keys,
    )?;
    match batch.retirement_plan() {
        Some(plan) => {
            if plan.genesis() != predecessor.genesis
                || plan.scope() != InvocationOwnershipScope::Ordered
                || plan.expected_root() != previous.retired_root()
                || plan.inserted_facts() != expected_retirement_facts
            {
                return Err(JournalStoreError::NonCanonical);
            }
            derived = derived
                .with_retired_root(previous.retired_root(), plan.root())
                .map_err(map_transition_proof_index_error)?;
        }
        None if !expected_retirement_facts.is_empty()
            || derived.retired_root() != previous.retired_root() =>
        {
            return Err(JournalStoreError::NonCanonical);
        }
        None => {}
    }
    if derived != *batch.next() {
        return Err(JournalStoreError::NonCanonical);
    }
    let created = store.put(batch.next())?;
    let exact = require_record::<S, TransitionProofIndexManifest>(store, batch.next().id())?;
    if exact != *batch.next() {
        return Err(JournalStoreError::Corrupt);
    }
    validate_transition_proof_index_closure(store, batch.next().id(), next)?;
    Ok(created)
}

fn transition_proof_publication_expected_live(
    input: &ReplayInput,
) -> Option<Option<crate::agent_sdk::proof::TransitionProofKey>> {
    match &input.operation {
        ReplayOperation::CleanInvoke {
            context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
            ..
        } => Some(None),
        ReplayOperation::CleanResume {
            context: crate::agent_sdk::RuntimeExecutionContext::Attested { .. },
            expected_live: Some(expected_live),
            ..
        } => Some(Some(*expected_live)),
        ReplayOperation::Management { .. }
        | ReplayOperation::CleanManage { .. }
        | ReplayOperation::Invoke { .. }
        | ReplayOperation::CleanInvoke { .. }
        | ReplayOperation::CleanResume { .. }
        | ReplayOperation::CleanAcknowledge { .. }
        | ReplayOperation::Acknowledge { .. }
        | ReplayOperation::SealMerge => None,
    }
}

fn transition_proof_intent_matches_input(
    intent: ReplayTransitionProofIntent,
    input: &ReplayInput,
    actual_live: Option<crate::agent_sdk::proof::TransitionProofKey>,
    target: crate::agent_sdk::proof::TransitionProofKey,
    prepared: bool,
) -> bool {
    let encoded = transition_proof_publication_expected_live(input);
    match intent {
        ReplayTransitionProofIntent::FirstPublication => {
            encoded == Some(None)
                && (actual_live.is_none() || !prepared && actual_live == Some(target))
        }
        ReplayTransitionProofIntent::Resume(expected) => {
            encoded == Some(Some(expected))
                && (actual_live == Some(expected) || !prepared && actual_live == Some(target))
        }
        ReplayTransitionProofIntent::Recanonicalize => encoded.is_some() && actual_live.is_some(),
    }
}

/// Process-local reference implementation used by deterministic replay and
/// storage-adapter tests.
#[derive(Debug)]
pub struct MemoryAgentJournalStore {
    instance_id: JournalStoreInstanceId,
    agent: AgentId,
    node: NodeId,
    genesis_admission: Option<Hash>,
    genesis: Option<Vec<u8>>,
    heads: Option<Vec<u8>>,
    authority: BTreeMap<(AuthorityStorageClass, [u8; 32]), Vec<u8>>,
    shared_ordered_commits: BTreeMap<OrderedEntryId, Vec<u8>>,
    objects: BTreeMap<(JournalStorageClass, [u8; 32]), Vec<u8>>,
    history_nodes: BTreeMap<InvocationHistoryNodeId, Vec<u8>>,
    history_retirements: Option<HistoryRetirementQueue>,
    // Copy-on-write keeps already-issued catalog resolver snapshots immutable
    // while preserving cheap candidate clones for rollback-safe publication.
    blobs: Arc<BTreeMap<(JournalBlobClass, Hash), Vec<u8>>>,
    gc_intent: Option<GcIntent>,
    replayed_root: Option<ReplayedRootJournalIdentity>,
}

static NEXT_MEMORY_JOURNAL_STORE_INSTANCE: AtomicU64 = AtomicU64::new(1);

fn new_memory_journal_store_instance(
    agent: AgentId,
    node: NodeId,
) -> Result<JournalStoreInstanceId, JournalStoreError> {
    let mut entropy = [0_u8; 32];
    getrandom::getrandom(&mut entropy).map_err(|_| JournalStoreError::Unavailable)?;
    JournalStoreInstanceId::from_bytes(
        Hash::digest(
            b"vos/agent/journal-store/memory-instance",
            &[&agent.0, &node.0, &entropy],
        )
        .0,
    )
    .ok_or(JournalStoreError::Unavailable)
}

fn cloned_memory_journal_store_instance(parent: JournalStoreInstanceId) -> JournalStoreInstanceId {
    let sequence = NEXT_MEMORY_JOURNAL_STORE_INSTANCE
        .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |value| {
            value.checked_add(1)
        })
        .expect("memory journal-store instance counter exhausted");
    JournalStoreInstanceId::from_bytes(
        Hash::digest(
            b"vos/agent/journal-store/memory-clone-instance",
            &[parent.as_bytes(), &sequence.to_le_bytes()],
        )
        .0,
    )
    .expect("memory journal-store instance commitment is nonzero")
}

impl Clone for MemoryAgentJournalStore {
    /// A public clone is an independently mutable in-memory store, so it must
    /// not inherit a Shared application capability for the source instance.
    fn clone(&self) -> Self {
        let mut cloned =
            self.copy_with_instance(cloned_memory_journal_store_instance(self.instance_id));
        // A public clone is a different physical journal capability. Root
        // provenance is process-local and may only come from that clone's own
        // independently reverified initialize/open boundary.
        cloned.replayed_root = None;
        cloned
    }
}

/// Immutable snapshot of an in-memory catalog namespace.
#[derive(Clone, Debug)]
pub(crate) struct MemoryCatalogBlobResolver {
    blobs: Arc<BTreeMap<(JournalBlobClass, Hash), Vec<u8>>>,
}

impl CatalogBlobResolver for MemoryCatalogBlobResolver {
    fn load_catalog(&self, reference: &BlobRef) -> Result<Option<Vec<u8>>, JournalStoreError> {
        validate_blob_reference(JournalBlobClass::CatalogArtifact, reference)?;
        self.blobs
            .get(&(JournalBlobClass::CatalogArtifact, reference.hash))
            .map(|bytes| {
                validate_stored_blob(JournalBlobClass::CatalogArtifact, reference, bytes)?;
                Ok(bytes.clone())
            })
            .transpose()
    }
}

impl CatalogBlobResolverFactory for MemoryAgentJournalStore {
    type Resolver = MemoryCatalogBlobResolver;

    fn catalog_blob_resolver(&self) -> Result<Self::Resolver, JournalStoreError> {
        Ok(MemoryCatalogBlobResolver {
            blobs: Arc::clone(&self.blobs),
        })
    }
}

impl MemoryAgentJournalStore {
    pub fn new(agent: AgentId, node: NodeId) -> Result<Self, JournalStoreError> {
        if agent == AgentId::ZERO || node == NodeId::ZERO {
            return Err(JournalStoreError::ScopeMismatch);
        }
        Ok(Self {
            instance_id: new_memory_journal_store_instance(agent, node)?,
            agent,
            node,
            genesis_admission: None,
            genesis: None,
            heads: None,
            authority: BTreeMap::new(),
            shared_ordered_commits: BTreeMap::new(),
            objects: BTreeMap::new(),
            history_nodes: BTreeMap::new(),
            history_retirements: None,
            blobs: Arc::new(BTreeMap::new()),
            gc_intent: None,
            replayed_root: None,
        })
    }

    pub(crate) fn initialize_shared<T: ReplaySealedOrdinaryGenesis>(
        &mut self,
        sealed: &T,
    ) -> Result<bool, JournalStoreError> {
        self.initialize_ordinary(sealed)
    }

    /// Experimental Local bootstrap. Build and validate the entire candidate
    /// before exposing any genesis/head; ordinary initialization stays closed.
    #[cfg(feature = "experimental-state-blocks")]
    pub(crate) fn initialize_external_local(
        &mut self,
        sealed: &super::replay::ReplaySealedExternalLocalGenesis,
        budget: &mut crate::agent_sdk::state_blocks::ReadBudget,
    ) -> Result<bool, JournalStoreError> {
        self.ensure_no_gc_pending()?;
        let genesis = sealed.genesis();
        let heads = sealed
            .initial_heads()
            .map_err(|_| JournalStoreError::NonCanonical)?;
        if genesis.runtime().agent != self.agent
            || heads.node != self.node
            || self.replayed_root.is_some()
        {
            return Err(JournalStoreError::ScopeMismatch);
        }
        let encoded = encode_object(genesis)?;
        let encoded_heads = encode_object(&heads)?;
        for artifact in &sealed.artifacts().artifacts {
            require_blob(self, JournalBlobClass::CatalogArtifact, artifact)?;
        }
        if self
            .genesis_admission
            .is_some_and(|id| id != genesis.admission.as_hash())
            || self
                .genesis
                .as_ref()
                .is_some_and(|bytes| bytes != &encoded.bytes)
            || self
                .heads
                .as_ref()
                .is_some_and(|bytes| bytes != &encoded_heads.bytes)
        {
            return Err(JournalStoreError::Conflict);
        }
        let created = self.genesis.is_none() || self.heads.is_none();
        let mut candidate = self.candidate_clone();
        sealed.with_staged_roots(&mut candidate, budget, |candidate, availability| {
            if let Some(admission) = sealed.admission_record() {
                candidate.persist_authority(admission)?;
            }
            candidate.put(sealed.empty_frontier())?;
            candidate.put(sealed.ordered_invocations())?;
            candidate.put(sealed.merge_invocations())?;
            candidate.put(sealed.local_invocations())?;
            candidate.put(sealed.artifacts())?;
            for lane in [
                PersistedLane::Control,
                PersistedLane::Linear,
                PersistedLane::Merge,
                PersistedLane::Local,
            ] {
                let manifest = sealed.lane_manifest(lane);
                candidate.put_blob(
                    JournalBlobClass::LaneState,
                    &manifest.state,
                    genesis_state_component(sealed.post_create(), lane),
                )?;
                candidate.put(&manifest)?;
            }
            candidate.put(
                &sealed
                    .initial_checkpoint()
                    .map_err(|_| JournalStoreError::NonCanonical)?,
            )?;
            candidate.genesis_admission = Some(genesis.admission.as_hash());
            candidate.genesis = Some(encoded.bytes);
            persist_initial_transition_proof_index(candidate, &heads)?;
            candidate.persist_historical_heads(&sealed.initial_predecessor_heads())?;
            candidate.heads = Some(encoded_heads.bytes);
            candidate.history_retirements =
                Some(HistoryRetirementQueue::empty(genesis.id(), self.node));
            validate_head_targets_with_availability(candidate, &heads, Some(availability))
        })?;
        *self = candidate;
        Ok(created)
    }

    pub(crate) fn install_portable_checkpoint(
        &mut self,
        image: &PortableJournalCheckpoint,
        maximum_index_nodes: usize,
    ) -> Result<(), JournalStoreError> {
        image.validate_shape()?;
        let current = self.heads()?.ok_or(JournalStoreError::NotInitialized)?;
        if current.genesis != image.heads.genesis
            || current.admission != image.heads.admission
            || current.node != image.heads.node
            || current.ordered_index != 0
            || current.ordered_head.is_some()
            || current.local_revision != 0
            || current.local_head.is_some()
            || current.checkpoint.is_some()
        {
            return Err(JournalStoreError::Conflict);
        }
        let mut candidate = self.candidate_clone();
        for blob in &image.blobs {
            candidate.put_blob(blob.class, &blob.reference, &blob.bytes)?;
        }
        for object in &image.objects {
            validate_portable_object(object)?;
            let key = (object.class, object.id);
            let target = if object.class == JournalStorageClass::InvocationHistoryNode {
                let id = InvocationHistoryNodeId(object.id);
                match candidate.history_nodes.get(&id) {
                    Some(bytes) if bytes == &object.bytes => continue,
                    Some(_) => return Err(JournalStoreError::Corrupt),
                    None => {
                        candidate.history_nodes.insert(id, object.bytes.clone());
                        continue;
                    }
                }
            } else {
                &mut candidate.objects
            };
            match target.get(&key) {
                Some(bytes) if bytes == &object.bytes => {}
                Some(_) => return Err(JournalStoreError::Corrupt),
                None => {
                    target.insert(key, object.bytes.clone());
                }
            }
        }
        candidate.heads = Some(image.heads.encode());
        validate_head_targets(&candidate, &image.heads)?;
        validate_portable_journal_closure(&candidate, image, maximum_index_nodes)?;
        *self = candidate;
        Ok(())
    }

    /// Pure destination reconstruction for the fixed common checkpoint
    /// profile. The caller must independently authenticate the source image
    /// and subsequently replay/validate this result before signing it. This
    /// in-memory helper grants no filesystem publication authority.
    pub(crate) fn rebind_common_checkpoint<T: ReplaySealedOrdinaryGenesis>(
        sealed: &T,
        source: &PortableJournalCheckpoint,
        predecessor: &JournalHeads,
        limits: PortableJournalLimits,
    ) -> Result<(Self, PortableJournalCheckpoint), JournalStoreError> {
        source.validate_shape()?;
        source.validate_limits(limits)?;
        let initial = sealed.initial_heads();
        if predecessor.genesis != initial.genesis
            || predecessor.admission != initial.admission
            || predecessor.node != initial.node
            || predecessor.local_revision != 0
            || predecessor.local_head.is_some()
            || predecessor.local_invocations != initial.local_invocations
            || source.heads.genesis != initial.genesis
            || source.heads.admission != initial.admission
            || source.heads.runtime != initial.runtime
            || source.heads.ordered_index < predecessor.ordered_index
            || (source.heads.ordered_index == predecessor.ordered_index
                && source.heads.ordered_head != predecessor.ordered_head)
        {
            return Err(JournalStoreError::ScopeMismatch);
        }
        let mut candidate = Self::new(initial.runtime.agent, initial.node)?;
        for blob in &source.blobs {
            candidate.put_blob(blob.class, &blob.reference, &blob.bytes)?;
        }
        candidate.initialize_shared(sealed)?;
        for object in &source.objects {
            validate_portable_object(object)?;
            if object.class == JournalStorageClass::InvocationHistoryNode {
                candidate
                    .history_nodes
                    .insert(InvocationHistoryNodeId(object.id), object.bytes.clone());
            } else {
                candidate
                    .objects
                    .insert((object.class, object.id), object.bytes.clone());
            }
        }
        let mut checkpoint = candidate
            .get::<CheckpointManifest>(
                source
                    .heads
                    .checkpoint
                    .ok_or(JournalStoreError::NonCanonical)?,
            )?
            .ok_or(JournalStoreError::MissingObject)?;
        let mut local = sealed.lane_manifest(PersistedLane::Local);
        local.runtime = checkpoint.runtime.clone();
        local
            .validate()
            .map_err(|_| JournalStoreError::NonCanonical)?;
        candidate.put_blob(
            JournalBlobClass::LaneState,
            &local.state,
            &sealed.post_create().local,
        )?;
        candidate.put(&local)?;
        candidate.put(sealed.local_invocations())?;
        let lane = checkpoint
            .lanes
            .iter_mut()
            .find(|lane| lane.lane == PersistedLane::Local)
            .ok_or(JournalStoreError::Corrupt)?;
        lane.node = Some(initial.node);
        lane.state = local.id();
        lane.invocations = Some(initial.local_invocations);
        checkpoint.publication_revision = predecessor.publication_revision;
        checkpoint
            .validate()
            .map_err(|_| JournalStoreError::NonCanonical)?;
        candidate.put(&checkpoint)?;
        candidate.persist_historical_heads(predecessor)?;
        let mut next = source.heads.clone();
        next.node = initial.node;
        next.local_invocations = initial.local_invocations;
        next.local_head = None;
        next.local_revision = 0;
        next.publication_revision = predecessor
            .publication_revision
            .checked_add(1)
            .ok_or(JournalStoreError::LimitExceeded)?;
        next.previous = Some(predecessor.id());
        next.checkpoint = Some(checkpoint.id());
        predecessor
            .validate_successor(&next)
            .map_err(|_| JournalStoreError::NonCanonical)?;
        candidate.heads = Some(next.encode());
        validate_head_targets(&candidate, &next)?;
        let image = export_portable_journal_checkpoint(&candidate, limits)?;
        Ok((candidate, image))
    }

    #[cfg(test)]
    pub(crate) fn remove_transition_proof_index_for_test(
        &mut self,
        id: super::journal::TransitionProofIndexId,
    ) -> bool {
        self.objects
            .remove(&(JournalStorageClass::TransitionProofIndex, *id.as_bytes()))
            .is_some()
    }

    #[cfg(all(test, feature = "experimental-state-blocks"))]
    pub(crate) fn replace_heads_for_external_fixture(&mut self, heads: &JournalHeads) {
        heads.validate().unwrap();
        assert_eq!(heads.runtime.agent, self.agent);
        assert_eq!(heads.node, self.node);
        self.heads = Some(heads.encode());
    }

    #[cfg(all(test, feature = "experimental-state-blocks"))]
    pub(crate) fn remove_state_block_for_test(
        &mut self,
        reference: crate::agent_sdk::state_blocks::BlockRef,
    ) -> Option<Vec<u8>> {
        Arc::make_mut(&mut self.blobs).remove(&(
            JournalBlobClass::StateBlock,
            Hash(reference.storage_reference().hash.0),
        ))
    }

    fn copy_with_instance(&self, instance_id: JournalStoreInstanceId) -> Self {
        Self {
            instance_id,
            agent: self.agent,
            node: self.node,
            genesis_admission: self.genesis_admission,
            genesis: self.genesis.clone(),
            heads: self.heads.clone(),
            authority: self.authority.clone(),
            shared_ordered_commits: self.shared_ordered_commits.clone(),
            objects: self.objects.clone(),
            history_nodes: self.history_nodes.clone(),
            history_retirements: self.history_retirements.clone(),
            blobs: Arc::clone(&self.blobs),
            gc_intent: self.gc_intent,
            replayed_root: self.replayed_root,
        }
    }

    /// Transactional copy for one publication attempt. Unlike public Clone,
    /// this candidate remains the same logical journal instance and replaces
    /// `self` only after the complete transition validates.
    fn candidate_clone(&self) -> Self {
        self.copy_with_instance(self.instance_id)
    }

    fn ensure_no_gc_pending(&self) -> Result<(), JournalStoreError> {
        if self.gc_intent.is_some() {
            Err(JournalStoreError::GcPending)
        } else {
            Ok(())
        }
    }

    fn validate_scope(&self, genesis: &AgentJournalGenesis) -> Result<(), JournalStoreError> {
        if genesis.runtime().agent != self.agent {
            return Err(JournalStoreError::ScopeMismatch);
        }
        Ok(())
    }

    fn history_queue(
        &self,
        genesis: AgentJournalGenesisId,
    ) -> Result<&HistoryRetirementQueue, JournalStoreError> {
        let queue = self
            .history_retirements
            .as_ref()
            .ok_or(JournalStoreError::NotInitialized)?;
        queue.validate()?;
        if queue.genesis != genesis || queue.node != self.node {
            return Err(JournalStoreError::Corrupt);
        }
        Ok(queue)
    }

    fn install_history_candidate(
        &mut self,
        overlay: &HistoryCandidateOverlay,
    ) -> Result<bool, JournalStoreError> {
        let mut created = false;
        for plan in &overlay.plans {
            for write in plan.overlay_nodes() {
                match self.history_nodes.get(&write.id()) {
                    Some(bytes) if bytes == write.bytes() => {}
                    Some(_) => return Err(JournalStoreError::Corrupt),
                    None if write.needs_write() => {
                        let node =
                            decode_object::<InvocationHistoryNode>(write.bytes(), write.id())?;
                        self.history_nodes.insert(node.id(), write.bytes().to_vec());
                        created = true;
                    }
                    None => return Err(JournalStoreError::Corrupt),
                }
            }
        }
        Ok(created)
    }

    fn enqueue_history_retirement(
        &mut self,
        intent: &HistoryCandidateIntent,
    ) -> Result<(), JournalStoreError> {
        let queue = self
            .history_retirements
            .as_mut()
            .ok_or(JournalStoreError::NotInitialized)?;
        if queue.commitment() != intent.queue_commitment {
            return Err(JournalStoreError::Corrupt);
        }
        queue.preflight_append(&intent.retirement)?;
        queue.records.push(intent.retirement.clone());
        queue.validate()
    }

    fn persist_authority<R: CanonicalAuthorityRecord>(
        &mut self,
        record: &R,
    ) -> Result<bool, JournalStoreError> {
        self.ensure_no_gc_pending()?;
        let id = record.storage_id();
        let bytes = record.encode();
        decode_authority_record::<R>(&bytes, id)?;
        let key = (R::STORAGE_CLASS, id);
        if let Some(existing) = self.authority.get(&key) {
            decode_authority_record::<R>(existing, id)?;
            return if existing == &bytes {
                Ok(false)
            } else {
                Err(JournalStoreError::Corrupt)
            };
        }
        self.authority.insert(key, bytes);
        Ok(true)
    }

    fn read_authority<R: CanonicalAuthorityRecord>(
        &self,
        expected: [u8; 32],
    ) -> Result<Option<R>, JournalStoreError> {
        if expected == [0; 32] {
            return Err(JournalStoreError::Corrupt);
        }
        self.authority
            .get(&(R::STORAGE_CLASS, expected))
            .map(|bytes| decode_authority_record::<R>(bytes, expected))
            .transpose()
    }

    fn persist_authority_with_readback<R: CanonicalAuthorityRecord>(
        &mut self,
        record: &R,
    ) -> Result<(), JournalStoreError> {
        let id = record.storage_id();
        self.persist_authority(record)?;
        if self.read_authority::<R>(id)?.as_ref() != Some(record) {
            return Err(JournalStoreError::Corrupt);
        }
        Ok(())
    }

    fn object_bytes<R: CanonicalJournalRecord>(&self, id: R::Id) -> Option<&[u8]> {
        if R::STORAGE_CLASS == JournalStorageClass::InvocationHistoryNode {
            return self
                .history_nodes
                .get(&InvocationHistoryNodeId(*id.as_bytes()))
                .map(Vec::as_slice);
        }
        self.objects
            .get(&(R::STORAGE_CLASS, *id.as_bytes()))
            .map(Vec::as_slice)
    }

    fn persist_historical_heads(
        &mut self,
        heads: &JournalHeads,
    ) -> Result<bool, JournalStoreError> {
        self.ensure_no_gc_pending()?;
        let encoded = encode_object(heads)?;
        if encoded.class != JournalStorageClass::Heads || heads.node != self.node {
            return Err(JournalStoreError::ScopeMismatch);
        }
        let key = (JournalStorageClass::Heads, encoded.id);
        let created = match self.objects.get(&key) {
            Some(existing) if existing == &encoded.bytes => false,
            Some(_) => return Err(JournalStoreError::Corrupt),
            None => {
                self.objects.insert(key, encoded.bytes);
                true
            }
        };
        if self.historical_heads(heads.id())?.as_ref() != Some(heads) {
            return Err(JournalStoreError::Corrupt);
        }
        Ok(created)
    }

    #[cfg(test)]
    pub(crate) fn persist_historical_heads_for_test(
        &mut self,
        heads: &JournalHeads,
    ) -> Result<bool, JournalStoreError> {
        self.persist_historical_heads(heads)
    }

    fn preflight_merge_event_insert(&self, encoded_bytes: usize) -> Result<(), JournalStoreError> {
        let mut objects = 0_usize;
        let mut bytes = 0_usize;
        for ((class, _), stored) in &self.objects {
            if *class != JournalStorageClass::MergeEvent {
                continue;
            }
            objects = objects
                .checked_add(1)
                .ok_or(JournalStoreError::Backpressure)?;
            bytes = bytes
                .checked_add(stored.len())
                .ok_or(JournalStoreError::Backpressure)?;
        }
        if objects >= MAX_MERGE_EVENT_OBJECTS
            || bytes
                .checked_add(encoded_bytes)
                .is_none_or(|next| next > MAX_MERGE_EVENT_BYTES)
        {
            return Err(JournalStoreError::Backpressure);
        }
        Ok(())
    }

    fn publish_anchor_with_mode<R: CanonicalJournalRecord>(
        &mut self,
        expected: JournalHeadsId,
        anchor: &R,
        next: &JournalHeads,
        mode: ReplayPublicationMode,
        transition_proof_change: bool,
    ) -> Result<JournalPublication, JournalStoreError> {
        self.publish_anchor_with_availability(
            expected,
            anchor,
            next,
            mode,
            transition_proof_change,
            None,
        )
    }

    fn publish_anchor_with_availability<R: CanonicalJournalRecord>(
        &mut self,
        expected: JournalHeadsId,
        anchor: &R,
        next: &JournalHeads,
        mode: ReplayPublicationMode,
        transition_proof_change: bool,
        availability: Option<&ExternalCheckpointValidation<'_>>,
    ) -> Result<JournalPublication, JournalStoreError> {
        self.ensure_no_gc_pending()?;
        ensure_publication_class(R::STORAGE_CLASS)?;
        let encoded_anchor = encode_object(anchor)?;
        let encoded_next = encode_object(next)?;
        let current = self.heads()?.ok_or(JournalStoreError::NotInitialized)?;

        if current.id() == next.id() {
            let existing = self
                .objects
                .get(&(encoded_anchor.class, encoded_anchor.id))
                .ok_or(JournalStoreError::Corrupt)?;
            if existing != &encoded_anchor.bytes {
                return Err(JournalStoreError::Corrupt);
            }
            validate_head_targets_with_availability(self, &current, availability)?;
            validate_idempotent_anchor(self, &current, anchor)?;
            let predecessor = next.previous.ok_or(JournalStoreError::Corrupt)?;
            if predecessor != expected
                || self
                    .historical_heads(predecessor)?
                    .ok_or(JournalStoreError::MissingObject)?
                    .id()
                    != predecessor
            {
                return Err(JournalStoreError::Corrupt);
            }
            return Ok(JournalPublication {
                object_created: false,
                heads_advanced: false,
            });
        }
        if current.id() != expected {
            return Err(JournalStoreError::Conflict);
        }
        validate_head_targets_with_availability(self, &current, availability)?;
        current
            .validate_successor(next)
            .map_err(supplied_decode_error)?;
        validate_publication_shape_with_mode(
            &current,
            anchor,
            next,
            mode,
            transition_proof_change,
        )?;

        // Build the candidate in a clone so an in-memory reference has the
        // same all-or-nothing head visibility as the filesystem head swap.
        let mut candidate = self.candidate_clone();
        let snapshot_created = candidate.persist_historical_heads(&current)?;
        let object_created = candidate.put(anchor)? || snapshot_created;
        validate_anchor_dependencies_with_availability(
            &candidate,
            &current,
            anchor,
            next,
            availability,
        )?;
        validate_head_targets_with_availability(&candidate, next, availability)?;
        candidate.heads = Some(encoded_next.bytes);
        *self = candidate;
        Ok(JournalPublication {
            object_created,
            heads_advanced: true,
        })
    }

    fn publish_anchor<R: CanonicalJournalRecord>(
        &mut self,
        expected: JournalHeadsId,
        anchor: &R,
        next: &JournalHeads,
    ) -> Result<JournalPublication, JournalStoreError> {
        self.publish_anchor_with_mode(
            expected,
            anchor,
            next,
            ReplayPublicationMode::Canonical,
            false,
        )
    }

    fn publish_sealed_internal(
        &mut self,
        publication: &ReplaySealedPublication,
        authority: Option<&ReplaySystemAuthorityStoragePlan>,
    ) -> Result<JournalPublication, JournalStoreError> {
        self.publish_sealed_with_availability(publication, authority, None)
    }

    fn publish_sealed_with_availability(
        &mut self,
        publication: &ReplaySealedPublication,
        authority: Option<&ReplaySystemAuthorityStoragePlan>,
        availability: Option<&ExternalCheckpointValidation<'_>>,
    ) -> Result<JournalPublication, JournalStoreError> {
        #[cfg(feature = "experimental-state-blocks")]
        if publication.external_execution().is_some()
            && !availability
                .is_some_and(|proof| proof.permits_mutation(self.instance_id(), publication))
        {
            return Err(JournalStoreError::Unavailable);
        }
        match (publication.system_authority_write(), authority) {
            (None, None) | (Some(_), Some(_)) => {}
            _ => return Err(JournalStoreError::NonCanonical),
        }
        self.ensure_no_gc_pending()?;
        let expected = publication.expected();
        let next = publication.next();
        let transition_proof_plan = publication
            .transition_proof_batch()
            .and_then(StagedTransitionProofBatch::retirement_plan);
        let current = self.heads()?.ok_or(JournalStoreError::NotInitialized)?;
        let exact_retry = publication_is_exact_retry(&current, expected, next)?;
        if exact_retry {
            validate_idempotent_history_plans(
                self,
                &current,
                publication.history_plans(),
                transition_proof_plan,
            )?;
        }
        let overlay = if exact_retry {
            None
        } else {
            let queue = self.history_queue(current.genesis)?.clone();
            build_history_candidate(
                self,
                &current,
                next,
                publication.history_plans(),
                transition_proof_plan,
                &queue,
            )?
        };

        // Build the complete candidate in a private clone. Authority history
        // is exact-read back before the anchor CAS and again after the
        // candidate's head has advanced, but is not exposed if validation or
        // the CAS fails.
        let mut candidate = self.candidate_clone();
        let history_created = overlay
            .as_ref()
            .map(|overlay| candidate.install_history_candidate(overlay))
            .transpose()?
            .unwrap_or(false);
        let authority_created = authority
            .map(|plan| stage_system_authority_dependencies(&mut candidate, publication, plan))
            .transpose()?
            .unwrap_or(false);
        let dependency_created = stage_sealed_dependencies(&mut candidate, publication)?;
        let transition_proof_change = publication.transition_proof_batch().is_some();
        let mut result = match publication.anchor() {
            ReplayPublicationAnchor::Ordered(entry) => candidate.publish_anchor_with_availability(
                expected,
                entry,
                next,
                publication.mode(),
                transition_proof_change,
                availability,
            )?,
            ReplayPublicationAnchor::Local(entry) => candidate.publish_anchor_with_availability(
                expected,
                entry,
                next,
                publication.mode(),
                transition_proof_change,
                availability,
            )?,
            ReplayPublicationAnchor::Merge { event, .. } => candidate.publish_anchor_with_mode(
                expected,
                event,
                next,
                publication.mode(),
                transition_proof_change,
            )?,
            ReplayPublicationAnchor::Checkpoint(checkpoint) => candidate
                .publish_anchor_with_availability(
                    expected,
                    checkpoint,
                    next,
                    publication.mode(),
                    transition_proof_change,
                    availability,
                )?,
        };
        if result.heads_advanced
            && let Some(overlay) = &overlay
        {
            candidate.enqueue_history_retirement(&overlay.intent)?;
        }
        if let Some(plan) = authority {
            stage_system_authority_dependencies(&mut candidate, publication, plan)?;
        }
        *self = candidate;
        result.object_created |= authority_created || dependency_created || history_created;
        Ok(result)
    }

    #[cfg(test)]
    pub(crate) fn initialize_raw_for_test(
        &mut self,
        genesis: &AgentJournalGenesis,
    ) -> Result<bool, JournalStoreError> {
        self.ensure_no_gc_pending()?;
        let encoded = encode_object(genesis)?;
        self.validate_scope(genesis)?;
        if self
            .load_blob(
                JournalBlobClass::CatalogArtifact,
                &genesis.runtime().package,
            )?
            .is_none()
        {
            return Err(JournalStoreError::MissingObject);
        }
        let empty_frontier = MergeFrontier {
            genesis: genesis.id(),
            events: Vec::new(),
        };
        let ordered_invocations =
            InvocationIndexManifest::empty(genesis.id(), InvocationOwnershipScope::Ordered);
        let merge_invocations =
            InvocationIndexManifest::empty(genesis.id(), InvocationOwnershipScope::Merge);
        let local_invocations = InvocationIndexManifest::empty(
            genesis.id(),
            InvocationOwnershipScope::Local(self.node),
        );
        let initial = JournalHeads::initial(
            genesis.id(),
            genesis.admission,
            self.node,
            empty_frontier.id(),
            genesis.runtime().clone(),
        );
        let encoded_heads = encode_object(&initial)?;
        let test_admission = genesis.admission.as_hash();

        if self
            .genesis_admission
            .is_some_and(|existing| existing != test_admission)
            || self
                .genesis
                .as_ref()
                .is_some_and(|existing| existing != &encoded.bytes)
            || self
                .heads
                .as_ref()
                .is_some_and(|existing| existing != &encoded_heads.bytes)
        {
            return Err(JournalStoreError::Conflict);
        }
        let created = self.genesis.is_none() || self.heads.is_none();
        let mut candidate = self.candidate_clone();
        candidate.put(&empty_frontier)?;
        candidate.put(&ordered_invocations)?;
        candidate.put(&merge_invocations)?;
        candidate.put(&local_invocations)?;
        candidate.genesis_admission = Some(test_admission);
        candidate.genesis = Some(encoded.bytes);
        persist_initial_transition_proof_index(&mut candidate, &initial)?;
        candidate.heads = Some(encoded_heads.bytes);
        candidate.history_retirements =
            Some(HistoryRetirementQueue::empty(genesis.id(), self.node));
        candidate.replayed_root = None;
        validate_head_targets(&candidate, &initial)?;
        *self = candidate;
        Ok(created)
    }

    fn initialize_ordinary<T: ReplaySealedOrdinaryGenesis>(
        &mut self,
        sealed: &T,
    ) -> Result<bool, JournalStoreError> {
        if sealed.genesis_checkpoint().is_some() {
            return Err(JournalStoreError::Unavailable);
        }
        self.ensure_no_gc_pending()?;
        let shape = validate_sealed_ordinary_genesis_shape(sealed, self.agent, self.node)?;
        if self.replayed_root.is_some() {
            return Err(JournalStoreError::ScopeMismatch);
        }
        let genesis = sealed.genesis();
        let encoded = encode_object(genesis)?;
        let encoded_heads = encode_object(&shape.initial)?;
        for reference in &sealed.artifacts().artifacts {
            require_blob(self, JournalBlobClass::CatalogArtifact, reference)?;
        }
        if self
            .genesis_admission
            .is_some_and(|existing| existing != sealed.admission_commitment())
            || self
                .genesis
                .as_ref()
                .is_some_and(|existing| existing != &encoded.bytes)
            || self
                .heads
                .as_ref()
                .is_some_and(|existing| existing != &encoded_heads.bytes)
        {
            return Err(JournalStoreError::Conflict);
        }
        let created = self.genesis.is_none() || self.heads.is_none();
        let mut candidate = self.candidate_clone();
        candidate.put(sealed.empty_frontier())?;
        candidate.put(sealed.ordered_invocations())?;
        candidate.put(sealed.merge_invocations())?;
        candidate.put(&shape.local_invocations)?;
        candidate.put(sealed.artifacts())?;
        for lane in &shape.lanes {
            candidate.put_blob(
                JournalBlobClass::LaneState,
                &lane.state,
                genesis_state_component(sealed.post_create(), lane.lane),
            )?;
            candidate.put(lane)?;
        }
        candidate.genesis_admission = Some(sealed.admission_commitment());
        candidate.genesis = Some(encoded.bytes);
        persist_initial_transition_proof_index(&mut candidate, &shape.initial)?;
        candidate.heads = Some(encoded_heads.bytes);
        candidate.history_retirements =
            Some(HistoryRetirementQueue::empty(genesis.id(), self.node));
        candidate.replayed_root = None;
        validate_head_targets(&candidate, &shape.initial)?;
        *self = candidate;
        Ok(created)
    }

    #[cfg(test)]
    pub(crate) fn initialize_ordinary_for_test<T: ReplaySealedOrdinaryGenesis>(
        &mut self,
        sealed: &T,
    ) -> Result<bool, JournalStoreError> {
        self.initialize_ordinary(sealed)
    }
}

impl AgentJournalStore for MemoryAgentJournalStore {
    #[cfg(feature = "experimental-state-blocks")]
    fn publish_external_shared_checkpoint(
        &mut self,
        publication: &ReplaySealedPublication,
        availability: &ExternalCheckpointValidation<'_>,
    ) -> Result<JournalPublication, JournalStoreError> {
        AuditedCheckpointStore::publish_audited_checkpoint(self, publication, availability)
    }

    #[cfg(feature = "experimental-state-blocks")]
    fn publish_available_shared(
        &mut self,
        publication: &ReplaySealedPublication,
        availability: &ExternalCheckpointValidation<'_>,
    ) -> Result<JournalPublication, JournalStoreError> {
        ExternalMutationStore::publish_external_mutation(self, publication, availability)
    }
    fn instance_id(&self) -> JournalStoreInstanceId {
        self.instance_id
    }

    fn initialize(&mut self, sealed: &ReplaySealedGenesis) -> Result<bool, JournalStoreError> {
        self.ensure_no_gc_pending()?;
        let shape = validate_sealed_genesis_shape(sealed, self.agent, self.node)?;
        let replayed_root = sealed
            .replayed_root_identity()
            .map_err(|_| JournalStoreError::ScopeMismatch)?;
        let genesis = sealed.genesis();
        let encoded = encode_object(genesis)?;
        let encoded_heads = encode_object(&shape.initial)?;
        for reference in &sealed.artifacts().artifacts {
            require_blob(self, JournalBlobClass::CatalogArtifact, reference)?;
        }
        if self
            .genesis_admission
            .is_some_and(|existing| existing != sealed.admission_commitment())
            || self
                .genesis
                .as_ref()
                .is_some_and(|existing| existing != &encoded.bytes)
            || self
                .heads
                .as_ref()
                .is_some_and(|existing| existing != &encoded_heads.bytes)
            || self
                .replayed_root
                .is_some_and(|existing| existing != replayed_root)
        {
            return Err(JournalStoreError::Conflict);
        }
        let created = self.genesis.is_none() || self.heads.is_none();
        let mut candidate = self.candidate_clone();
        candidate.persist_authority(sealed.root_anchor())?;
        candidate.persist_authority(sealed.admission_evidence())?;
        candidate.persist_authority(sealed.admission_record())?;
        candidate.put(sealed.empty_frontier())?;
        candidate.put(sealed.ordered_invocations())?;
        candidate.put(sealed.merge_invocations())?;
        candidate.put(&shape.local_invocations)?;
        candidate.put(sealed.artifacts())?;
        for lane in &shape.lanes {
            candidate.put_blob(
                JournalBlobClass::LaneState,
                &lane.state,
                genesis_state_component(sealed.post_create(), lane.lane),
            )?;
            candidate.put(lane)?;
        }
        candidate.genesis_admission = Some(sealed.admission_commitment());
        candidate.genesis = Some(encoded.bytes);
        persist_initial_transition_proof_index(&mut candidate, &shape.initial)?;
        candidate.heads = Some(encoded_heads.bytes);
        candidate.history_retirements =
            Some(HistoryRetirementQueue::empty(genesis.id(), self.node));
        candidate.replayed_root = Some(replayed_root);
        validate_head_targets(&candidate, &shape.initial)?;
        *self = candidate;
        Ok(created)
    }

    fn genesis(&self) -> Result<Option<AgentJournalGenesis>, JournalStoreError> {
        self.genesis
            .as_deref()
            .map(|bytes| {
                let decoded =
                    AgentJournalGenesis::decode(bytes).map_err(|_| JournalStoreError::Corrupt)?;
                decode_object(bytes, decoded.id())
            })
            .transpose()
    }

    fn heads(&self) -> Result<Option<JournalHeads>, JournalStoreError> {
        self.heads
            .as_deref()
            .map(|bytes| {
                let decoded =
                    JournalHeads::decode(bytes).map_err(|_| JournalStoreError::Corrupt)?;
                let decoded = decode_object::<JournalHeads>(bytes, decoded.id())?;
                if decoded.node != self.node {
                    return Err(JournalStoreError::ScopeMismatch);
                }
                Ok(decoded)
            })
            .transpose()
    }

    fn historical_heads(
        &self,
        id: JournalHeadsId,
    ) -> Result<Option<JournalHeads>, JournalStoreError> {
        if id == JournalHeadsId::ZERO {
            return Err(JournalStoreError::Corrupt);
        }
        self.objects
            .get(&(JournalStorageClass::Heads, *id.as_bytes()))
            .map(|bytes| {
                let heads = decode_object::<JournalHeads>(bytes, id)?;
                if heads.node != self.node {
                    return Err(JournalStoreError::ScopeMismatch);
                }
                Ok(heads)
            })
            .transpose()
    }

    fn put<R: CanonicalJournalRecord>(&mut self, record: &R) -> Result<bool, JournalStoreError> {
        self.ensure_no_gc_pending()?;
        ensure_writable_content_class(R::STORAGE_CLASS)?;
        let encoded = encode_object(record)?;
        let key = (encoded.class, encoded.id);
        match self.objects.get(&key) {
            Some(existing) if existing == &encoded.bytes => Ok(false),
            Some(_) => Err(JournalStoreError::Corrupt),
            None => {
                if encoded.class == JournalStorageClass::MergeEvent {
                    self.preflight_merge_event_insert(encoded.bytes.len())?;
                }
                self.objects.insert(key, encoded.bytes);
                Ok(true)
            }
        }
    }

    fn get<R: CanonicalJournalRecord>(&self, id: R::Id) -> Result<Option<R>, JournalStoreError> {
        ensure_readable_content_class(R::STORAGE_CLASS)?;
        self.object_bytes::<R>(id)
            .map(|bytes| decode_object(bytes, id))
            .transpose()
    }

    fn put_blob(
        &mut self,
        class: JournalBlobClass,
        reference: &BlobRef,
        bytes: &[u8],
    ) -> Result<bool, JournalStoreError> {
        self.ensure_no_gc_pending()?;
        validate_supplied_blob(class, reference, bytes)?;
        let key = (class, reference.hash);
        match self.blobs.get(&key) {
            Some(existing) if existing == bytes => Ok(false),
            Some(_) => Err(JournalStoreError::Corrupt),
            None => {
                Arc::make_mut(&mut self.blobs).insert(key, bytes.to_vec());
                Ok(true)
            }
        }
    }

    fn load_blob(
        &self,
        class: JournalBlobClass,
        reference: &BlobRef,
    ) -> Result<Option<Vec<u8>>, JournalStoreError> {
        validate_blob_reference(class, reference)?;
        self.blobs
            .get(&(class, reference.hash))
            .map(|bytes| {
                validate_stored_blob(class, reference, bytes)?;
                Ok(bytes.clone())
            })
            .transpose()
    }

    fn publish(
        &mut self,
        publication: &ReplaySealedPublication,
    ) -> Result<JournalPublication, JournalStoreError> {
        self.publish_sealed_internal(publication, None)
    }
}

#[cfg(feature = "experimental-state-blocks")]
impl AuditedCheckpointStore for MemoryAgentJournalStore {
    fn publish_audited_checkpoint(
        &mut self,
        publication: &ReplaySealedPublication,
        availability: &ExternalCheckpointValidation<'_>,
    ) -> Result<JournalPublication, JournalStoreError> {
        if !matches!(publication.anchor(), ReplayPublicationAnchor::Checkpoint(_))
            || !availability.matches_heads(self.instance_id(), publication.next())
        {
            return Err(JournalStoreError::NonCanonical);
        }
        self.publish_sealed_with_availability(publication, None, Some(availability))
    }
}

#[cfg(feature = "experimental-state-blocks")]
impl ExternalMutationStore for MemoryAgentJournalStore {
    fn publish_external_mutation(
        &mut self,
        publication: &ReplaySealedPublication,
        availability: &ExternalCheckpointValidation<'_>,
    ) -> Result<JournalPublication, JournalStoreError> {
        if !availability.permits_mutation(self.instance_id(), publication) {
            return Err(JournalStoreError::NonCanonical);
        }
        self.publish_sealed_with_availability(publication, None, Some(availability))
    }
}

impl TransitionProofPublicationStore for MemoryAgentJournalStore {
    fn stage_proof_predecessor(&mut self, heads: &JournalHeads) -> Result<bool, JournalStoreError> {
        let current = self.heads()?.ok_or(JournalStoreError::NotInitialized)?;
        if current.id() != heads.id() || current != *heads {
            return Err(JournalStoreError::Conflict);
        }
        self.persist_historical_heads(heads)
    }
}

impl UnpublishedCatalogBlobStore for MemoryAgentJournalStore {
    fn stage_catalog_blob(
        &mut self,
        predecessor: JournalHeadsId,
        reference: &BlobRef,
        bytes: &[u8],
    ) -> Result<Option<UnpublishedCatalogBlob>, JournalStoreError> {
        if self.heads()?.ok_or(JournalStoreError::NotInitialized)?.id() != predecessor {
            return Err(JournalStoreError::Conflict);
        }
        self.put_blob(JournalBlobClass::CatalogArtifact, reference, bytes)
            .map(|created| {
                created.then(|| UnpublishedCatalogBlob {
                    store: self.instance_id(),
                    predecessor,
                    reference: reference.clone(),
                })
            })
    }

    fn rollback_catalog_blob(
        &mut self,
        token: UnpublishedCatalogBlob,
    ) -> Result<(), JournalStoreError> {
        self.ensure_no_gc_pending()?;
        if token.store != self.instance_id()
            || self.heads()?.ok_or(JournalStoreError::NotInitialized)?.id() != token.predecessor
        {
            return Err(JournalStoreError::Conflict);
        }
        let key = (JournalBlobClass::CatalogArtifact, token.reference.hash);
        let bytes = self.blobs.get(&key).ok_or(JournalStoreError::Corrupt)?;
        validate_stored_blob(JournalBlobClass::CatalogArtifact, &token.reference, bytes)?;
        Arc::make_mut(&mut self.blobs).remove(&key);
        Ok(())
    }
}

impl SharedOrderedCommitStore for MemoryAgentJournalStore {
    fn shared_ordered_commit(
        &self,
        entry: OrderedEntryId,
    ) -> Result<Option<SharedOrderedCommitBinding>, JournalStoreError> {
        if entry == OrderedEntryId::ZERO {
            return Err(JournalStoreError::Corrupt);
        }
        let binding = self
            .shared_ordered_commits
            .get(&entry)
            .map(|bytes| decode_shared_ordered_commit_binding(bytes, entry))
            .transpose()?;
        if let Some(binding) = &binding {
            let heads = self.heads()?.ok_or(JournalStoreError::NotInitialized)?;
            validate_shared_ordered_commit_scope(binding, &heads, self.instance_id())?;
        }
        Ok(binding)
    }

    fn persist_shared_ordered_commit(
        &mut self,
        binding: &SharedOrderedCommitBinding,
    ) -> Result<bool, JournalStoreError> {
        self.ensure_no_gc_pending()?;
        binding.validate()?;
        let heads = self.heads()?.ok_or(JournalStoreError::NotInitialized)?;
        validate_shared_ordered_commit_scope(binding, &heads, self.instance_id())?;
        let bytes = binding.encode();
        if bytes.len() > MAX_SHARED_ORDERED_COMMIT_BINDING_BYTES {
            return Err(JournalStoreError::LimitExceeded);
        }
        match self.shared_ordered_commits.get(&binding.entry) {
            Some(existing) => {
                decode_shared_ordered_commit_binding(existing, binding.entry)?;
                if existing == &bytes {
                    Ok(false)
                } else {
                    Err(JournalStoreError::Conflict)
                }
            }
            None => {
                if self.shared_ordered_commits.len() == MAX_SHARED_ORDERED_COMMIT_BINDINGS {
                    return Err(JournalStoreError::LimitExceeded);
                }
                self.shared_ordered_commits.insert(binding.entry, bytes);
                Ok(true)
            }
        }
    }

    fn shared_ordered_commit_ids(&self) -> Result<Vec<OrderedEntryId>, JournalStoreError> {
        if self.shared_ordered_commits.len() > MAX_SHARED_ORDERED_COMMIT_BINDINGS {
            return Err(JournalStoreError::LimitExceeded);
        }
        let mut ids = Vec::new();
        ids.try_reserve(self.shared_ordered_commits.len())
            .map_err(|_| JournalStoreError::LimitExceeded)?;
        for (&entry, bytes) in self.shared_ordered_commits.iter() {
            decode_shared_ordered_commit_binding(bytes, entry)?;
            ids.push(entry);
        }
        Ok(ids)
    }
}

#[cfg(feature = "storage")]
impl SharedOrderedCommitRetirementStore for MemoryAgentJournalStore {
    fn retire_shared_ordered_commits(
        &mut self,
        snapshot: &super::shared_raft::InstalledAgentRaftSnapshotV2,
        maximum: usize,
    ) -> Result<SharedOrderedCommitRetirement, JournalStoreError> {
        validate_snapshot_retirement_scope(self, snapshot)?;
        let mut eligible = Vec::new();
        for (&entry, bytes) in &self.shared_ordered_commits {
            let binding = decode_shared_ordered_commit_binding(bytes, entry)?;
            if binding_retired_by_snapshot(&binding, snapshot)? {
                eligible.push(entry);
            }
        }
        let removed = eligible.len().min(maximum);
        for entry in eligible.iter().take(removed) {
            self.shared_ordered_commits.remove(entry);
        }
        Ok(SharedOrderedCommitRetirement {
            removed,
            remaining: eligible.len().saturating_sub(removed),
        })
    }
}

